**Description of the Terraform Program:**

This Terraform configuration sets up a Route 53 query logging system that sends DNS query logs to an AWS CloudWatch Logs log group. It includes the following components:

- A Route 53 hosted zone named "primary".
- A CloudWatch Logs log group named "aws_route53_example_com".
- A CloudWatch Logs resource policy named "route53-query-logging-policy" that grants Route 53 permission to write logs to the log group.
- A Route 53 query logging configuration that associates the hosted zone with the log group.

The configuration ensures that all necessary IAM permissions are in place and that the infrastructure is fully declarative and deployable.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_route53_zone" "primary" {
  name = "example.com"
  tags = {
    Name = "primary"
  }
}

resource "aws_cloudwatch_log_group" "aws_route53_example_com" {
  name = "aws_route53_example_com"
  retention_in_days = 30
}

resource "aws_iam_role" "route53_query_logging_role" {
  name = "route53-query-logging-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "route53.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "route53_query_logging" {
  role       = aws_iam_role.route53_query_logging_role.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchLambdaInsightsExecutionRolePolicy"
}

resource "aws_cloudwatch_log_resource_policy" "route53_query_logging_policy" {
  name = "route53-query-logging-policy"
  policy_document = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "route53.amazonaws.com"
      }
      Action = [
        "logs:CreateLogStream",
        "logs:PutLogEvents"
      ]
      Resource = aws_cloudwatch_log_group.aws_route53_example_com.arn
    }]
  })
}

resource "aws_route53_query_log" "example_com" {
  zone_id = aws_route53_zone.primary.id
  log_group_arn = aws_cloudwatch_log_group.aws_route53_example_com.arn
}
```

---

This configuration is ready to be applied with `terraform apply` and will create the necessary infrastructure for logging Route 53 queries into CloudWatch Logs.

