**Description of the Terraform Program:**

This Terraform configuration sets up two Route 53 private and public hosted zones named "private" and "public" respectively. It provisions two RDS instances: one internal (non-publicly accessible) and one public (publicly accessible). The internal RDS instance is associated with a subnet group named "main" and is placed in a private subnet, while the public RDS instance is placed in a public subnet. Route 53 is configured to return the appropriate database endpoint based on the user's location: internal users (within the VPC) are directed to the internal RDS instance, and external users are directed to the public RDS instance.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create VPC
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "main-vpc"
  }
}

# Create public subnet
resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  map_public_ip_on_launch = true
  availability_zone = "us-west-2a"
  tags = {
    Name = "public-subnet"
  }
}

# Create private subnet
resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2a"
  tags = {
    Name = "private-subnet"
  }
}

# Create subnet group for internal RDS
resource "aws_db_subnet_group" "main" {
  name       = "main"
  subnet_ids = [aws_subnet.private.id]
  tags = {
    Name = "main-subnet-group"
  }
}

# Create public RDS instance
resource "aws_db_instance" "public" {
  allocated_storage      = 20
  engine                 = "mysql"
  engine_version         = "8.0.30"
  instance_class         = "db.t3.micro"
  db_name                = "public_db"
  username               = "admin"
  password               = "Password123!"
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds_public.id]
  publicly_accessible    = true
  tags = {
    Name = "public-db"
  }
}

# Create internal RDS instance
resource "aws_db_instance" "internal" {
  allocated_storage      = 20
  engine                 = "mysql"
  engine_version         = "8.0.30"
  instance_class         = "db.t3.micro"
  db_name                = "internal_db"
  username               = "admin"
  password               = "Password123!"
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds_internal.id]
  publicly_accessible    = false
  tags = {
    Name = "internal-db"
  }
}

# Create security group for public RDS
resource "aws_security_group" "rds_public" {
  name        = "rds-public-sg"
  description = "Allow access to public RDS instance"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0/0"]
  }

  tags = {
    Name = "rds-public-sg"
  }
}

# Create security group for internal RDS
resource "aws_security_group" "rds_internal" {
  name        = "rds-internal-sg"
  description = "Allow access to internal RDS instance"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0/0"]
  }

  tags = {
    Name = "rds-internal-sg"
  }
}

# Create Route 53 public hosted zone
resource "aws_route53_zone" "public" {
  name = "example.com"
  tags = {
    Name = "public-zone"
  }
}

# Create Route 53 private hosted zone
resource "aws_route53_zone" "private" {
  name = "example.com"
  vpc {
    vpc_id      = aws_vpc.main.id
    private_zone = true
  }
  tags = {
    Name = "private-zone"
  }
}

# Create A record for public zone
resource "aws_route53_record" "public_db" {
  zone_id = aws_route53_zone.public.id
  name    = "db.example.com"
  type    = "A"
  ttl     = 300
  records = [aws_db_instance.public.endpoint.address]
}

# Create A record for private zone
resource "aws_route53_record" "private_db" {
  zone_id = aws_route53_zone.private.id
  name    = "db.example.com"
  type    = "A"
  ttl     = 300
  records = [aws_db_instance.internal.endpoint.address]
}
```

---

**Notes:**

- This configuration assumes you have an existing AWS account and proper permissions.
- The Route 53 zones are both named `example.com`, but one is public and one is private. You can change the domain name as needed.
- The RDS instances are configured with a default password. In a real-world scenario, you should use a secure password and possibly a secret manager like AWS Secrets Manager.
- The subnet group is named "main" and is associated with the private subnet.
- The security groups ensure that only internal traffic can reach the internal RDS instance, and all traffic can reach the public RDS instance.

