**Description of the Terraform Program:**

This Terraform configuration creates an Elastic Beanstalk environment with autoscaling settings based on CPU utilization thresholds. It defines an IAM role (`eb_ec2_role`) and an instance profile (`eb_ec2_profile`) that will be used by the Elastic Beanstalk environment. The Elastic Beanstalk application is named `my_api_app`, and the environment is configured with autoscaling policies that adjust the number of instances based on CPU utilization thresholds.

---

**Terraform HCL Code:**

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "ec2.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  roles = [aws_iam_role.eb_ec2_role.name]
}

resource "aws_iam_role_policy_attachment" "eb_ec2_role_ec2" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2RoleforSSM"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_role_awslogs" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonAWSLogServicesFullAccess"
}

resource "aws_elasticbeanstalk_application" "my_api_app" {
  name        = "my_api_app"
  description = "Elastic Beanstalk application for my API"
}

resource "aws_elasticbeanstalk_environment" "my_api_env" {
  name                = "my_api_env"
  application         = aws_elasticbeanstalk_application.my_api_app.name
  environment_name    = "my_api_env"
  solution_stack_name = "64bit Amazon Linux 2023 v3.3.6 running Python 3.10"
  description         = "Elastic Beanstalk environment with autoscaling based on CPU utilization"

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "AutoScalingGroupName"
    value     = "my_api_env_asg"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment:loadbalancer"
    name      = "ServicePort"
    value     = "80"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment:process:default"
    name      = "HealthCheckPath"
    value     = "/health"
  }

  autoscaling {
    min_size = 1
    max_size = 5
    desired_capacity = 2

    policy {
      name = "cpu_scale_out"
      type = "TargetTrackingScaling"
      target_tracking_configuration {
        predefined_metric = "ASGAverageCPUUtilization"
        target_value = 70
      }
    }

    policy {
      name = "cpu_scale_in"
      type = "TargetTrackingScaling"
      target_tracking_configuration {
        predefined_metric = "ASGAverageCPUUtilization"
        target_value = 30
      }
    }
  }
}
```

