**Description of the Terraform Program:**

This Terraform configuration sets up a Blue/Green deployment strategy using AWS Elastic Beanstalk and Route53. It creates two Elastic Beanstalk environments named "blue" and "green" and configures a Route53 weighted routing policy to distribute traffic between them. The configuration includes:

- An AWS provider block with a specified region.
- Two Elastic Beanstalk environments with default configurations.
- A Route53 hosted zone (assumed to be pre-created or created by this configuration).
- A Route53 record set with a weighted routing policy that points to both environments.
- IAM roles and policies for Elastic Beanstalk environments to ensure proper permissions.

---

**Terraform HCL Code:**

```hcl
provider "aws" {
  region = "us-east-1"
}

# Create Elastic Beanstalk environment for Blue
resource "aws_elastic_beanstalk_environment" "blue" {
  name                = "blue"
  application         = aws_elastic_beanstalk_application.example.name
  solution_stack_name = "64bit Amazon Linux 2023 running Python 3.10"
  description         = "Blue environment for Blue/Green deployment"
  tags = {
    Environment = "blue"
  }
}

# Create Elastic Beanstalk environment for Green
resource "aws_elastic_beanstalk_environment" "green" {
  name                = "green"
  application         = aws_elastic_beanstalk_application.example.name
  solution_stack_name = "64bit Amazon Linux 2023 running Python 3.10"
  description         = "Green environment for Blue/Green deployment"
  tags = {
    Environment = "green"
  }
}

# Create Elastic Beanstalk Application
resource "aws_elastic_beanstalk_application" "example" {
  name        = "blue-green-app"
  description = "Application for Blue/Green deployment"
}

# Create IAM role for Elastic Beanstalk environments
resource "aws_iam_role" "eb_role" {
  name = "eb-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "elasticbeanstalk.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "eb_role_policy" {
  role       = aws_iam_role.eb_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

# Attach the role to both environments
resource "aws_elastic_beanstalk_environment" "blue" {
  name                = "blue"
  application         = aws_elastic_beanstalk_application.example.name
  solution_stack_name = "64bit Amazon Linux 2023 running Python 3.10"
  description         = "Blue environment for Blue/Green deployment"
  tags = {
    Environment = "blue"
  }
  # Assign the IAM role
  environment_name = "blue"
  role             = aws_iam_role.eb_role.arn
}

resource "aws_elastic_beanstalk_environment" "green" {
  name                = "green"
  application         = aws_elastic_beanstalk_application.example.name
  solution_stack_name = "64bit Amazon Linux 2023 running Python 3.10"
  description         = "Green environment for Blue/Green deployment"
  tags = {
    Environment = "green"
  }
  # Assign the IAM role
  environment_name = "green"
  role             = aws_iam_role.eb_role.arn
}

# Route53 Hosted Zone (Assuming it already exists, but can be created if needed)
# If you want to create it, uncomment the following block
# resource "aws_route53_zone" "example" {
#   name = "example.com"
# }

# Route53 Weighted Record Set
resource "aws_route53_record" "weighted" {
  zone_id = "Z1234567890ABCDEF" # Replace with your actual hosted zone ID
  name    = "example.com"
  type    = "A"
  ttl     = 300
  records = [
    aws_elastic_beanstalk_environment.blue.cname,
    aws_elastic_beanstalk_environment.green.cname
  ]
  weighted_routing_policy {
    weight = 50
  }
}
```

---

**Notes:**

- Replace `"Z1234567890ABCDEF"` with your actual Route53 hosted zone ID.
- The `aws_route53_zone` resource is commented out by default. Uncomment and configure it if you need to create a new hosted zone.
- The `solution_stack_name` is set to a default stack for Python 3.10. You can change it based on your application requirements.
- The weighted routing policy is set to 50/50. You can adjust the weights as needed for traffic distribution.

