      Effect = "Allow"
      Principal = { Service = "elasticbeanstalk.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "elastic_beanstalk_service_role_eu_central" {
  role       = aws_iam_role.elastic_beanstalk_service_role_eu_central.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_elastic_beanstalk_environment" "us_west" {
  name                = var.environment_name_us_west
  application         = "my_app"
  region              = var.aws_region_us_west
  solution_stack_name = "64bit Amazon Linux 2023 v3.3.10 running Python 3.10"
  environment_type    = "LoadBalanced"
  tags = {
    Name = var.environment_name_us_west
  }
  # You can add your application code or configuration here
}

resource "aws_elastic_beanstalk_environment" "eu_central" {
  provider = aws.eu
  name                = var.environment_name_eu_central
  application         = "my_app"
  region              = var.aws_region_eu_central
  solution_stack_name = "64bit Amazon Linux 2023 v3.3.10 running Python 3.10"
  environment_type    = "LoadBalanced"
  tags = {
    Name = var.environment_name_eu_central
  }
  # You can add your application code or configuration here
}

resource "aws_route53_zone" "example_com" {
  name = var.route53_zone_name
  tags = {
    Name = "example.com"
  }
}

resource "aws_route53_record" "app" {
  zone_id = aws_route53_zone.example_com.id
  name    = "${var.route53_record_name}.${var.route53_zone_name}"
  type    = "A"
  alias {
    name   = aws_elastic_beanstalk_environment.us_west.load_balancer_dns_name
    zone_id = aws_elastic_beanstalk_environment.us_west.load_balancer_zone_id
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "app_eu" {
  provider = aws.eu
  zone_id = aws_route53_zone.example_com.id
  name    = "${var.route53_record_name}.${var.route53_zone_name}"
  type    = "A"
  alias {
    name   = aws_elastic_beanstalk_environment.eu_central.load_balancer_dns_name
    zone_id = aws_elastic_beanstalk_environment.eu_central.load_balancer_zone_id
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "latency_based_routing" {
  zone_id = aws_route53_zone.example_com.id
  name    = "${var.route53_record_name}.${var.route53_zone_name}"
  type    = "A"
  alias {
    name   = aws_route53_record.app.alias.0.name
    zone_id = aws_route53_record.app.alias.0.zone_id
    evaluate_target_health = true
  }
  latency_routing_policy {
    region = var.aws_region_us_west
  }
}

resource "aws_route53_record" "latency_based_routing_eu" {
  provider = aws.eu
  zone_id = aws_route53_zone.example_com.id
  name    = "${var.route53_record_name}.${var.route53_zone_name}"
  type    = "A"
  alias {
    name   = aws_route53_record.app_eu.alias.0.name
    zone_id = aws_route53_record.app_eu.alias.0.zone_id
    evaluate_target_health = true
  }
  latency_routing_policy {
    region = var.aws_region_eu_central
  }
}
```

---

**Notes:**

- This configuration assumes you have an existing Route 53 zone named `example.com`. If not, you can create it using `aws_route53_zone`.
- The Elastic Beanstalk environments are configured with a basic solution stack. You can replace this with your own application configuration or use a `.zip` file with your application code.
- The latency-based routing is set up to direct traffic to the closest environment based on the user's location.
- The configuration uses two AWS providers, one for each region, to manage resources in their respective regions.

