**Description of the Terraform Program:**

This Terraform configuration sets up a blue/green deployment using AWS Elastic Beanstalk environments. It provisions two Elastic Beanstalk environments (blue and green), each associated with an RDS database instance named "my_db". Before deploying to the green environment, a snapshot of the current RDS database is taken. An IAM instance profile named "ec2_eb_profile1" is created and assigned to the Elastic Beanstalk environments to grant them the necessary permissions to interact with the RDS database. The configuration includes a provider block for AWS, default region, and all required resources and variables.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "db_name" {
  default = "my_db"
}

variable "db_instance_class" {
  default = "db.t3.micro"
}

variable "db_engine" {
  default = "mysql"
}

variable "db_engine_version" {
  default = "8.0.30"
}

variable "db_allocated_storage" {
  default = 20
}

variable "db_username" {
  default = "admin"
}

variable "db_password" {
  default = "SecurePassword123!"
}

variable "snapshot_name" {
  default = "my_db_snapshot_before_deployment"
}

variable "environment_name_blue" {
  default = "blue_env"
}

variable "environment_name_green" {
  default = "green_env"
}

variable "instance_profile_name" {
  default = "ec2_eb_profile1"
}

resource "aws_iam_role" "ec2_eb_role" {
  name = var.instance_profile_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "elasticbeanstalk.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "ec2_eb_role_rds" {
  role       = aws_iam_role.ec2_eb_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonRDSFullAccess"
}

resource "aws_iam_instance_profile" "ec2_eb_profile" {
  name = var.instance_profile_name
  role = aws_iam_role.ec2_eb_role.name
}

resource "aws_db_instance" "my_db" {
  identifier             = var.db_name
  engine                 = var.db_engine
  engine_version         = var.db_engine_version
  instance_class         = var.db_instance_class
  allocated_storage      = var.db_allocated_storage
  username               = var.db_username
  password               = var.db_password
  skip_final_snapshot    = true
  db_subnet_group_name   = "default"
  vpc_security_group_ids = [aws_security_group.ec2_eb_sg.id]
  tags = {
    Name = var.db_name
  }
}

resource "aws_db_snapshot" "pre_deployment_snapshot" {
  db_instance_identifier = aws_db_instance.my_db.identifier
  snapshot_identifier    = var.snapshot_name
  depends_on             = [aws_db_instance.my_db]
}

resource "aws_security_group" "ec2_eb_sg" {
  name        = "ec2_eb_sg"
  description = "Security group for Elastic Beanstalk EC2 instances"
  vpc_id      = "vpc-12345678" # Replace with your actual VPC ID

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_elasticbeanstalk_environment" "blue_env" {
  name                = var.environment_name_blue
  application         = "my_app"
  environment_name    = var.environment_name_blue
