**Description of the Terraform Program:**

This Terraform configuration provisions a complete AWS infrastructure for deploying a web application using Elastic Beanstalk. It includes:

- An AWS provider configuration with a specified region.
- An IAM role for Elastic Beanstalk to manage application deployment and access to other AWS resources.
- A VPC with an Internet Gateway for public internet access.
- Two public subnets within the VPC.
- Route tables and route entries to ensure proper network routing.
- An RDS instance (MySQL) for the application's database needs, configured with a security group to allow access from the Elastic Beanstalk environment.
- An Elastic Beanstalk environment that uses the VPC and connects to the RDS instance.

All resources are defined with default values where applicable, and the configuration is designed to be deployable with Terraform 1.9.8 and the AWS provider version 5.75.

---

**Terraform HCL Code:**

```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM Role for Elastic Beanstalk
resource "aws_iam_role" "elastic_beanstalk_role" {
  name = "elastic_beanstalk_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "elasticbeanstalk.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "elastic_beanstalk_role_policy" {
  role       = aws_iam_role.elastic_beanstalk_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "main-vpc"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "main-igw"
  }
}

# Subnets
resource "aws_subnet" "public_subnet_1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  map_public_ip_on_launch = true
  availability_zone = "us-east-1a"
  tags = {
    Name = "public-subnet-1"
  }
}

resource "aws_subnet" "public_subnet_2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  map_public_ip_on_launch = true
  availability_zone = "us-east-1b"
  tags = {
    Name = "public-subnet-2"
  }
}

# Route Table for VPC
resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "main-route-table"
  }
}

# Route to Internet Gateway
resource "aws_route" "igw_route" {
  route_table_id         = aws_route_table.main.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

# Associate Subnets with Route Table
resource "aws_route_table_association" "public_subnet_1" {
  subnet_id      = aws_subnet.public_subnet_1.id
  route_table_id = aws_route_table.main.id
}

resource "aws_route_table_association" "public_subnet_2" {
  subnet_id      = aws_subnet.public_subnet_2.id
  route_table_id = aws_route_table.main.id
}

# RDS Instance
resource "aws_db_instance" "main" {
  allocated_storage      = 20
  engine                 = "mysql"
  engine_version         = "8.0.30"
  instance_class         = "db.t3.micro"
  db_name                = "mydb"
  username               = "admin"
  password               = "SecurePassword123!"
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds_sg.id]
  skip_final_snapshot    = true
  tags = {
    Name = "main-db"
  }
}

# RDS Subnet Group
resource "aws_db_subnet_group" "main" {
  name       = "main-db-subnet-group"
  subnet_ids = [aws_subnet.public_subnet_1.id, aws_subnet.public_subnet_2.id]
  tags = {
    Name = "main-db-subnet-group"
  }
}

# Security Group for RDS
resource "aws_security_group" "rds_sg" {
  name        = "rds-sg"
  description = "Allow access to RDS from Elastic Beanstalk"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "rds-sg"
  }
}

# Elastic Beanstalk Environment
resource "aws_elasticbeanstalk_environment" "main" {
  name                = "my-eb-env"
  application         = "my-eb-app"
  environment_name    = "my-eb-env"
  solution_stack_name = "64bit Amazon Linux 2023 v3.3.6 running Python 3.10"
  tags = {
    Name = "my-eb-env"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ResourceType"
    value     = "VPC"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment:process:default"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment:process:default"
    name      = "Subnets"
    value     = join(",", [aws_subnet.public_subnet_1.id, aws_subnet.public_subnet_2.id])
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment:process:default"
    name      = "SecurityGroups"
    value     = aws_security_group.rds_sg.id
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment:process:default"
    name      = "IamInstanceProfile"
    value     = aws_iam_role.elastic_beanstalk_role.arn
  }
}

# Elastic Beanstalk Application
resource "aws_elasticbeanstalk_application" "main" {
  name = "my-eb-app"
}
```

