**Description of the Terraform Program:**

This Terraform configuration creates an AWS VPC named `eb_vpc` with an Internet Gateway, two public subnets named `eb_subnet_public_1` and `eb_subnet_public_2`, a security group named `eb_env_sg`, and a route table associated with the public subnets. It also provisions two Elastic Beanstalk environments that are connected to the VPC and a shared RDS database named `shared_rds`. The RDS database is linked to the public subnets, and the Elastic Beanstalk environments are configured to use the `eb_env_sg` security group for network access.

---

**Terraform HCL Code:**

```hcl
provider "aws" {
  region = "us-west-2"
}

# VPC
resource "aws_vpc" "eb_vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "eb_vpc"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "eb_igw" {
  vpc_id = aws_vpc.eb_vpc.id
  tags = {
    Name = "eb_igw"
  }
}

# Public Subnets
resource "aws_subnet" "eb_subnet_public_1" {
  vpc_id            = aws_vpc.eb_vpc.id
  cidr_block        = "10.0.1.0/24"
  map_public_ip_on_launch = true
  availability_zone = "us-west-2a"
  tags = {
    Name = "eb_subnet_public_1"
  }
}

resource "aws_subnet" "eb_subnet_public_2" {
  vpc_id            = aws_vpc.eb_vpc.id
  cidr_block        = "10.0.2.0/24"
  map_public_ip_on_launch = true
  availability_zone = "us-west-2b"
  tags = {
    Name = "eb_subnet_public_2"
  }
}

# Route Table for Public Subnets
resource "aws_route_table" "eb_route_table" {
  vpc_id = aws_vpc.eb_vpc.id
  tags = {
    Name = "eb_route_table"
  }
}

resource "aws_route" "eb_route" {
  route_table_id         = aws_route_table.eb_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.eb_igw.id
}

# Associate Route Table with Subnets
resource "aws_route_table_association" "eb_subnet_1_assoc" {
  subnet_id      = aws_subnet.eb_subnet_public_1.id
  route_table_id = aws_route_table.eb_route_table.id
}

resource "aws_route_table_association" "eb_subnet_2_assoc" {
  subnet_id      = aws_subnet.eb_subnet_public_2.id
  route_table_id = aws_route_table.eb_route_table.id
}

# Security Group for Elastic Beanstalk Environments
resource "aws_security_group" "eb_env_sg" {
  name        = "eb_env_sg"
  description = "Security group for Elastic Beanstalk environments"
  vpc_id      = aws_vpc.eb_vpc.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "eb_env_sg"
  }
}

# Shared RDS Database
resource "aws_db_subnet_group" "shared_rds_subnet_group" {
  name       = "shared_rds_subnet_group"
  subnet_ids = [aws_subnet.eb_subnet_public_1.id, aws_subnet.eb_subnet_public_2.id]
  tags = {
    Name = "shared_rds_subnet_group"
  }
}

resource "aws_db_instance" "shared_rds" {
  identifier             = "shared_rds"
  engine                 = "mysql"
  engine_version         = "8.0.30"
  instance_class         = "db.t3.micro"
  allocated_storage      = 20
  username               = "admin"
  password               = "SecurePassword123!"
  db_subnet_group_name   = aws_db_subnet_group.shared_rds_subnet_group.name
  vpc_security_group_ids = [aws_security_group.eb_env_sg.id]
  skip_final_snapshot    = true
  tags = {
    Name = "shared_rds"
  }
}

# Elastic Beanstalk Environments
resource "aws_elasticbeanstalk_environment" "eb_env_1" {
  name                = "eb_env_1"
  application         = "eb_app"
  environment_name    = "eb_env_1"
  solution_stack_name = "64bit Amazon Linux 2023 v3.3.6 running Python 3.10"
  subnet_ids          = [aws_subnet.eb_subnet_public_1.id, aws_subnet.eb_subnet_public_2.id]
  security_groups     = [aws_security_group.eb_env_sg.id]
  tags = {
    Name = "eb_env_1"
  }
}

resource "aws_elasticbeanstalk_environment" "eb_env_2" {
  name                = "eb_env_2"
  application         = "eb_app"
  environment_name    = "eb_env_2"
  solution_stack_name = "64bit Amazon Linux 2023 v3.3.6 running Python 3.10"
  subnet_ids          = [aws_subnet.eb_subnet_public_1.id, aws_subnet.eb_subnet_public_2.id]
  security_groups     = [aws_security_group.eb_env_sg.id]
  tags = {
    Name = "eb_env_2"
  }
}

# Application for Elastic Beanstalk
resource "aws_elasticbeanstalk_application" "eb_app" {
  name        = "eb_app"
  description = "Elastic Beanstalk application for environments"
  tags = {
    Name = "eb_app"
  }
}
```

