**Description of the Terraform Program:**

This Terraform configuration provisions a multi-region application deployment using Elastic Beanstalk and Route 53. It creates two Elastic Beanstalk environments in the "us-east-1" and "eu-west-1" regions, each with a connected RDS database. A Route 53 hosted zone is created for the domain, and two A record aliases are set up to direct traffic to the respective Elastic Beanstalk environments. An IAM instance profile is created for the Elastic Beanstalk EC2 instances. All resources are named according to the specified naming conventions.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  region = "eu-west-1"
  alias  = "eu-west-1"
}

variable "domain_name" {
  description = "The domain name to be managed by Route 53"
  default     = "example.com"
}

variable "hosted_zone_id" {
  description = "The Route 53 hosted zone ID for the domain"
  default     = "Z1234567890ABCDEF"
}

resource "aws_route53_record" "us_east_alias" {
  zone_id = var.hosted_zone_id
  name    = "myapp.example.com"
  type    = "A"
  alias {
    name   = aws_elastic_beanstalk_environment.myenv_us_east.cname
    zone_id = aws_elastic_beanstalk_environment.myenv_us_east.hosted_zone_id
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "eu_west_alias" {
  zone_id = var.hosted_zone_id
  name    = "myapp.example.com"
  type    = "A"
  alias {
    name   = aws_elastic_beanstalk_environment.myenv_eu_west.cname
    zone_id = aws_elastic_beanstalk_environment.myenv_eu_west.hosted_zone_id
    evaluate_target_health = true
  }
}

resource "aws_iam_instance_profile" "eb_ec2_profile3" {
  name = "eb_ec2_profile3"
  role = aws_iam_role.eb_role.name
}

resource "aws_iam_role" "eb_role" {
  name = "eb_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "elasticbeanstalk.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "eb_role_policy" {
  role       = aws_iam_role.eb_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_elastic_beanstalk_application" "myapp_us_east" {
  name        = "myapp_us_east"
  description = "Elastic Beanstalk application for us-east-1"
}

resource "aws_elastic_beanstalk_application_version" "myapp_us_east_version" {
  application_name = aws_elastic_beanstalk_application.myapp_us_east.name
