  solution_stack_name = "64bit Amazon Linux 2023 v3.3.10 running Python 3.10"
  instance_profile    = aws_iam_instance_profile.eb_ec2_profile3.name
  tags = {
    Environment = "us-east-1"
  }
}

resource "aws_db_instance" "main_db_us_east" {
  identifier = "main_db_us_east"
  engine     = "mysql"
  engine_version = "8.0.33"
  instance_class = "db.t3.micro"
  allocated_storage = 20
  username = "admin"
  password = "SecurePassword123!"
  db_name  = "mydb"
  skip_final_snapshot = true
}

resource "aws_elastic_beanstalk_application" "myapp_eu_west" {
  name        = "myapp_eu_west"
  description = "Elastic Beanstalk application for eu-west-1"
}

resource "aws_elastic_beanstalk_application_version" "myapp_eu_west_version" {
  application_name = aws_elastic_beanstalk_application.myapp_eu_west.name
  name             = "v1.0"
  description      = "Initial version of the application"
  source_bundle {
    s3_bucket = "my-bucket"
