**Description of the Terraform Program:**

This Terraform configuration sets up a blue/green deployment architecture using AWS Route 53. It creates two Route 53 records (one for each environment: blue and green) that point to separate EC2 instances. Both environments share a common RDS database named "myapp_db". Health checks are enabled on the Route 53 records to monitor the health of each environment, and a failover routing policy is implemented to automatically route traffic to the healthy environment. An IAM instance profile named "eb_ec2_profile" is created to allow EC2 instances to access the shared RDS database.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-east-1"
}

# Create IAM instance profile for EC2 instances
resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  roles = [aws_iam_role.ec2_role.name]
}

resource "aws_iam_role" "ec2_role" {
  name = "ec2_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "ec2.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "rds_access" {
  role       = aws_iam_role.ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonRDSFullAccess"
}

# Create RDS database
resource "aws_db_instance" "myapp_db" {
  identifier = "myapp_db"
  engine     = "mysql"
  engine_version = "8.0.30"
  allocated_storage = 20
  username = "admin"
  password = "SecurePassword123!"
  db_subnet_group_name = aws_db_subnet_group.myapp_db_subnet_group.name
  vpc_security_group_ids = [aws_security_group.db_sg.id]
  skip_final_snapshot = true
  instance_class = "db.t2.micro"
}

resource "aws_db_subnet_group" "myapp_db_subnet_group" {
  name = "myapp_db_subnet_group"
  subnet_ids = [
    aws_subnet.private_subnet1.id,
    aws_subnet.private_subnet2.id
  ]
  db_subnet_group_description = "Subnet group for myapp_db"
  tags = {
    Name = "myapp_db_subnet_group"
  }
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "main_vpc"
  }
}

resource "aws_subnet" "private_subnet1" {
  vpc_id = aws_vpc.main.id
  cidr_block = "10.0.1.0/24"
  map_public_ip_on_launch = false
  availability_zone = "us-east-1a"
  tags = {
    Name = "private_subnet1"
  }
}

resource "aws_subnet" "private_subnet2" {
  vpc_id = aws_vpc.main.id
  cidr_block = "10.0.2.0/24"
  map_public_ip_on_launch = false
  availability_zone = "us-east-1b"
  tags = {
    Name = "private_subnet2"
  }
}

resource "aws_security_group" "db_sg" {
  name        = "db_sg"
  description = "Security group for RDS"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "db_sg"
  }
}

# Create EC2 instances for blue and green environments
resource "aws_instance" "blue_env" {
  ami           = "ami-0c55b159cbfafe1f0"
  instance_type = "t2.micro"
  subnet_id     = aws_subnet.private_subnet1.id
  iam_instance_profile = aws_iam_instance_profile.eb_ec2_profile.name
  tags = {
    Name = "blue_env"
  }
}

resource "aws_instance" "green_env" {
  ami           = "ami-0c55b159cbfafe1f0"
  instance_type = "t2.micro"
  subnet_id     = aws_subnet.private_subnet2.id
  iam_instance_profile = aws_iam_instance_profile.eb_ec2_profile.name
  tags = {
    Name = "green_env"
  }
}

# Create Route 53 hosted zone
resource "aws_route53_zone" "example_com" {
  name = "example.com"
  tags = {
    Name = "example.com"
  }
}

# Create Route 53 records for blue and green environments
resource "aws_route53_record" "blue_env_a" {
  zone_id = aws_route53_zone.example_com.id
  name    = "app.example.com"
  type    = "A"
  alias {
    name   = aws_instance.blue_env.public_ip
    zone_id = aws_instance.blue_env.vpc_info.associate_public_ip_address ? aws_route53_zone.example_com.id : aws_route53_zone.example_com.id
    evaluate_target_health = true
  }
  health_check_id = aws_route53_health_check.blue_env.id
}

resource "aws_route53_record" "green_env_a" {
  zone_id = aws_route53_zone.example_com.id
  name    = "app.example.com"
  type    = "A"
  alias {
    name   = aws_instance.green_env.public_ip
    zone_id = aws_instance.green_env.vpc_info.associate_public_ip_address ? aws_route53_zone.example_com.id : aws_route53_zone.example_com.id
    evaluate_target_health = true
  }
  health_check_id = aws_route53_health_check.green_env.id
}

# Create health checks for blue and green environments
resource "aws_route53_health_check" "blue_env" {
  ip_address = aws_instance.blue_env.public_ip
  port       = 80
  type       = "HTTP"
  resource_path = "/"
  failure_threshold = 3
  request_interval = 30
}

resource "aws_route53_health_check" "green_env" {
  ip_address = aws_instance.green_env.public_ip
  port       = 80
  type       = "HTTP"
  resource_path = "/"
  failure_threshold = 3
  request_interval = 30
}

# Create failover routing policy
resource "aws_route53_record" "failover_record" {
  zone_id = aws_route53_zone.example_com.id
  name    = "app.example.com"
  type    = "A"
  failover = "PRIMARY"
  alias {
    name   = aws_instance.blue_env.public_ip
    zone_id = aws_instance.blue_env.vpc_info.associate_public_ip_address ? aws_route53_zone.example_com.id : aws_route53_zone.example_com.id
    evaluate_target_health = true
  }
  health_check_id = aws_route53_health_check.blue_env.id
}

resource "aws_route53_record" "failover_record_secondary" {
  zone_id = aws_route53_zone.example_com.id
  name    = "app.example.com"
  type    = "A"
  failover = "SECONDARY"
  alias {
    name   = aws_instance.green_env.public_ip
    zone_id = aws_instance.green_env.vpc_info.associate_public_ip_address ? aws_route53_zone.example_com.id : aws_route53_zone.example_com.id
    evaluate_target_health = true
  }
  health_check_id = aws_route53_health_check.green_env.id
}
```

---

**Notes:**

- This configuration assumes that the EC2 instances are already running a web service on port 80 that can be health-checked.
- The health checks are configured to use HTTP on port 80 and check the root path (`/`).
- The failover policy ensures that traffic is directed to the primary environment (blue) unless it fails, in which case it routes to the secondary (green).
- The RDS instance is shared between both environments and is accessible via the security group and subnet configuration.
- The IAM instance profile allows EC2 instances to access the RDS database.

