This Terraform configuration creates an Elastic Beanstalk WebServer environment with an associated Elastic Beanstalk application. It also defines an IAM role (`eb_ec2_role`) and an instance profile (`eb_ec2_profile`) that will be used by the EC2 instances in the Elastic Beanstalk environment. The Elastic Beanstalk application is named `my_application`. The configuration includes a provider block for AWS, default values for variables, and ensures that all resources are fully specified and deployable.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "ec2.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

resource "aws_iam_role_policy_attachment" "eb_ec2_role_ec2" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2RoleforSSM"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_role_s3" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess"
}

resource "aws_elasticbeanstalk_application" "my_application" {
  name        = "my_application"
  description = "Elastic Beanstalk application for web service"
}

resource "aws_elasticbeanstalk_environment" "web_env" {
  name                = "my_environment"
  application         = aws_elasticbeanstalk_application.my_application.name
  environment_name    = "my_environment"
  solution_stack_name = "64bit Amazon Linux 2023 v3.3.10 running Python 3.10"
  tier                = "WebServer"
  instance_profile    = aws_iam_instance_profile.eb_ec2_profile.name
}
```

---

This configuration is ready to be applied with Terraform version `~> 1.9.8` and the AWS provider version `~> 5.75`. It ensures that the Elastic Beanstalk environment is created with the correct IAM role and instance profile, and the application is properly set up.

