**Description of the Terraform Program:**

This Terraform configuration creates an Elastic Beanstalk application that runs a Go-based application. It includes the necessary AWS resources such as an S3 bucket for storing the application source code, an IAM role for Elastic Beanstalk, and the Elastic Beanstalk application itself. The configuration assumes that the Go application has been compiled into a ZIP file and uploaded to an S3 bucket. The Elastic Beanstalk environment is configured to use the Go platform and will deploy the application from the specified S3 bucket.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "go_app_bucket" {
  bucket = "go-app-bucket-${random_string.bucket_suffix.result}"
  acl    = "private"

  tags = {
    Name = "go-app-bucket"
  }
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}

resource "aws_s3_bucket_object" "go_app_code" {
  bucket = aws_s3_bucket.go_app_bucket.bucket
  key    = "go-app-code.zip"
  source = "path/to/your/go-app-code.zip" # Replace with the actual path to your Go app ZIP file
}

resource "aws_iam_role" "elastic_beanstalk_role" {
  name = "elastic-beanstalk-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "elasticbeanstalk.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "elastic_beanstalk_role_policy" {
  role       = aws_iam_role.elastic_beanstalk_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_elasticbeanstalk_application" "go_app" {
  name        = "go-app"
  description = "Go application deployed via Elastic Beanstalk"
}

resource "aws_elasticbeanstalk_application_version" "go_app_version" {
  application = aws_elasticbeanstalk_application.go_app.name
  version_label = "v1.0.0"
  source_bundle {
    s3_bucket = aws_s3_bucket.go_app_bucket.bucket
    s3_key    = aws_s3_bucket_object.go_app_code.key
  }
}

resource "aws_elasticbeanstalk_environment" "go_env" {
  name                = "go-env"
  application         = aws_elasticbeanstalk_application.go_app.name
  environment_name    = "go-env"
  solution_stack_name = "64bit Amazon Linux 2023 v3.3.10 running Go 1.21"
  tier {
    name = "WebServer"
    type = "Standard"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment:process:default"
    name      = "Port"
    value     = "8080"
  }

  tags = {
    Environment = "dev"
  }
}
```

