**Description of the Terraform Program:**

This Terraform configuration provisions an AWS infrastructure to deploy and scale a web application. It includes:

- An **AWS EC2 instance** to host the web application.
- A **security group** to allow HTTP traffic to the instance.
- A **launch template** to define the instance configuration.
- An **Auto Scaling group** to scale the number of instances based on CPU utilization.
- A **load balancer** (Application Load Balancer) to distribute traffic across instances.
- A **target group** associated with the load balancer.
- A **launch configuration** (or launch template) used by the Auto Scaling group.
- A **CloudWatch alarm** to trigger scaling actions based on CPU utilization.
- A **default VPC and subnet** to ensure the resources are deployed in a valid network environment.

The web application is assumed to be built using a supported programming language (e.g., Python, Node.js, etc.) and is deployed via a script or package installed on the EC2 instance.

---

**Terraform HCL Code:**

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  map_public_ip_on_launch = true
  availability_zone = "us-east-1a"
  tags = {
    Name = "public-subnet"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "main-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "public-route-table"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route" "internet_gateway" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_security_group" "web" {
  name        = "web-sg"
  description = "Allow HTTP traffic"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "web-sg"
  }
}

resource "aws_launch_template" "web_app" {
  name_prefix = "web-app-launch-template"
  image_id    = "ami-0c55b159cbfafe1f0" # Amazon Linux 2 AMI (example)
  instance_type = "t2.micro"
  key_name      = "your-ssh-key-name" # Replace with your actual key name
  vpc_security_group_ids = [aws_security_group.web.id]
  user_data = <<-EOF
              #!/bin/bash
              sudo yum update -y
              sudo yum install -y httpd
              sudo systemctl start httpd
              sudo systemctl enable httpd
              echo "Hello from Terraform!" | sudo tee /var/www/html/index.html
              EOF
}

resource "aws_autoscaling_group" "web_app" {
  launch_template {
    id      = aws_launch_template.web_app.id
    version = "$Latest"
  }

  min_size = 1
  max_size = 3
  desired_capacity = 1

  vpc_zone_identifier = [aws_subnet.public.id]

  target_group_arns = [aws_lb_target_group.web_app.arn]

  tag {
    key                 = "Name"
    value               = "web-app-instance"
    propagate_at_launch = true
  }
}

resource "aws_lb" "web_app" {
  name               = "web-app-lb"
  internal           = false
  security_groups    = [aws_security_group.web.id]
  subnets            = [aws_subnet.public.id]
  enable_deletion_protection = false
}

resource "aws_lb_target_group" "web_app" {
  name     = "web-app-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    path = "/"
  }
}

resource "aws_lb_listener" "web_app" {
  load_balancer_arn = aws_lb.web_app.arn
  port              = 80
  protocol          = "HTTP"

  default_actions {
    type             = "forward"
    target_group_arn = aws_lb_target_group.web_app.arn
  }
}

resource "aws_cloudwatch_metric_alarm" "scale_up" {
  alarm_name          = "web-app-scale-up"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = "1"
  metric_name         = "CPUUtilization"
  namespace           = "AWS/EC2"
  period              = 300
  statistic           = "Average"
  threshold           = 70
  dimensions = {
    AutoScalingGroupName = aws_autoscaling_group.web_app.name
  }
  treat_missing_data = "notBreaching"
  alarm_description  = "Scale up when CPU utilization is above 70% for 1 minute"
  actions = [
    aws_autoscaling_policy.scale_up.arn
  ]
}

resource "aws_autoscaling_policy" "scale_up" {
  name                   = "web-app-scale-up"
  autoscaling_group_name = aws_autoscaling_group.web_app.name
  policy_type            = "StepScaling"
  step_adjustments {
    scaling_adjustment = 1
    metric_interval_upper_bound = 100
  }
}
```

---

**Notes:**

- Replace `"your-ssh-key-name"` with the name of your actual SSH key pair in AWS.
- The `image_id` is for Amazon Linux 2 in `us-east-1`. You may need to update it for other regions or OS versions.
- This configuration assumes the web application is a simple HTTP server (e.g., Apache with a static HTML page). You can replace the `user_data` script with your application deployment logic (e.g., installing Node.js, Python, etc.).
- The Auto Scaling group scales based on CPU utilization, and the CloudWatch alarm triggers scaling actions.

Let me know if you'd like to add a CI/CD pipeline or use a containerized application (e.g., with ECS or EKS).

