**Description of the Terraform Program:**

This Terraform configuration creates an AWS CodeBuild project with the following features:
- A CodeBuild project that builds from a primary and secondary source.
- An IAM role that grants the necessary permissions for CodeBuild to access AWS resources (e.g., S3 for build logs, CodeCommit for source code).
- The primary source is set to a CodeCommit repository, and the secondary source is also set to a CodeCommit repository.
- The provider is configured with a valid AWS region (us-east-1 by default).
- All required variables are defined with default values for ease of deployment.

---

**Terraform HCL Code:**

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "codebuild_project_name" {
  description = "Name of the CodeBuild project"
  default     = "example-codebuild-project"
}

variable "primary_source_repo" {
  description = "Name of the primary CodeCommit repository"
  default     = "primary-repo"
}

variable "secondary_source_repo" {
  description = "Name of the secondary CodeCommit repository"
  default     = "secondary-repo"
}

variable "buildspec_file" {
  description = "Path to the buildspec file in the primary source"
  default     = "buildspec.yml"
}

resource "aws_iam_role" "codebuild_role" {
  name = "codebuild-role-${var.codebuild_project_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "codebuild.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "codebuild_basic" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSCodeBuildBasicPolicy"
}

resource "aws_iam_role_policy_attachment" "codebuild_s3_access" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess"
}

resource "aws_codebuild_project" "example" {
  name         = var.codebuild_project_name
  description  = "Example CodeBuild project with primary and secondary sources"
  service_role = aws_iam_role.codebuild_role.arn

  source {
    type            = "CODECOMMIT"
    location        = "https://git-codecommit.us-east-1.amazonaws.com/v1/repos/${var.primary_source_repo}"
    buildspec       = var.buildspec_file
    secondary_buildspecs = {
      secondary-source = var.buildspec_file
    }
  }

  secondary_source {
    type            = "CODECOMMIT"
    location        = "https://git-codecommit.us-east-1.amazonaws.com/v1/repos/${var.secondary_source_repo}"
    buildspec       = var.buildspec_file
  }

  artifacts {
    type = "NO_ARTIFACTS"
  }

  environment {
    type                = "LINUX_CONTAINER"
    image               = "aws/codebuild/amazonlinux2-x86_64-standard:3.0"
    compute_type        = "BUILD_GENERAL1_SMALL"
  }

  tags = {
    Environment = "dev"
    Project     = var.codebuild_project_name
  }
}
```

