**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-east-1"
  version = "~> 5.75"
}

resource "aws_iam_role" "lex_bot_role" {
  name = "lex-bot-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "lex.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "lex_bot_role_policy" {
  role       = aws_iam_role.lex_bot_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSLexFullAccess"
}

resource "aws_lex_bot" "example_bot" {
  name        = "example-bot"
