**Description of the Terraform Program:**

This Terraform configuration creates an AWS Lex bot designed to handle pizza ordering interactions. The bot includes intents such as "OrderPizza" and "ConfirmOrder," along with slots to capture user input like pizza type, size, and toppings. A Lambda function is also created to handle the fulfillment of the bot's intents, which can be used to process the order data and perform actions like saving the order to a database or sending a confirmation email. The configuration includes IAM roles for the Lambda function and the Lex bot, and it is set up to run in the `us-east-1` region.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "lambda_role" {
  name = "lambda_lex_fulfillment_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "lambda.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_lambda_function" "pizza_order_fulfillment" {
  function_name    = "PizzaOrderFulfillment"
  role             = aws_iam_role.lambda_role.arn
  handler          = "index.handler"
  runtime          = "nodejs18.x"
  filename         = "lambda_function.zip"
  source_code_hash = filebase64sha256("lambda_function.zip")

  timeout = 30
  memory_size = 128

  environment {
    variables = {
      ORDER_PROCESSING_URL = "https://example.com/order"
    }
  }
}

resource "aws_lex_bot" "pizza_order_bot" {
  name                     = "PizzaOrderBot"
  description              = "A bot for ordering pizzas"
  locale                   = "en-US"
  child_directed           = false
  voice_id                 = "Joanna"
  idle_session_ttl_in_seconds = 300

  intents {
    intent_name = "OrderPizza"
    slots {
      name        = "PizzaType"
      slot_type   = "AMAZON.Food"
      value_elicitation_prompt {
        message {
          content = "What type of pizza would you like?"
          content_type = "PlainText"
        }
      }
    }
    slots {
      name        = "Size"
      slot_type   = "AMAZON.Food"
      value_elicitation_prompt {
        message {
          content = "What size would you like?"
          content_type = "PlainText"
        }
      }
    }
    slots {
      name        = "Toppings"
      slot_type   = "AMAZON.Food"
      value_elicitation_prompt {
        message {
          content = "What toppings would you like?"
          content_type = "PlainText"
        }
      }
    }
    fulfillment_activity {
      type = "CodeHook"
      code_hook {
        lambda_arn = aws_lambda_function.pizza_order_fulfillment.arn
      }
    }
  }

  intents {
    intent_name = "ConfirmOrder"
    slots {
      name        = "Confirm"
      slot_type   = "AMAZON.YesNo"
      value_elicitation_prompt {
        message {
          content = "Would you like to confirm your order?"
          content_type = "PlainText"
        }
      }
    }
    fulfillment_activity {
      type = "None"
    }
  }

  clarification_prompt {
    message {
      content = "I'm not sure I understand. Can you please rephrase?"
      content_type = "PlainText"
    }
    max_attempts = 2
  }

  abort_statement {
    message {
      content = "Okay, I can't help with that. Have a great day!"
      content_type = "PlainText"
    }
  }
}
```

---

**Note:**  
- The `filename` and `source_code_hash` in the `aws_lambda_function` resource are placeholders. You must replace `"lambda_function.zip"` with the actual Lambda deployment package and compute the SHA256 hash of the file.
- This configuration assumes you have a Node.js Lambda function that handles the fulfillment logic. You can generate the Lambda code separately and package it into a ZIP file for deployment.

