**Description of the Terraform Program:**

This Terraform configuration creates an AWS Kinesis Firehose Delivery Stream with an S3 destination that includes dynamic partitioning. Dynamic partitioning allows Firehose to automatically partition data based on timestamp fields in the data records, which improves query performance and organization in S3. The configuration includes the necessary IAM role and policies to allow Firehose to write to S3 and process data.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "firehose_role" {
  name = "firehose_delivery_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "firehose.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "firehose_s3_access" {
  role       = aws_iam_role.firehose_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3FullAccess"
}

resource "aws_iam_role_policy_attachment" "firehose_cloudwatch_logs" {
  role       = aws_iam_role.firehose_role.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchLogsFullAccess"
}

resource "aws_kinesis_firehose_delivery_stream" "example_firehose" {
  name        = "example-firehose"
  type        = "direct_PUT"
  destination = "s3"

  s3_destination_configuration {
    role_arn       = aws_iam_role.firehose_role.arn
    bucket_arn     = "arn:aws:s3:::example-bucket"
    prefix         = "firehose-data/"
    error_output_prefix = "firehose-errors/"

    dynamic_partitioning_configuration {
      enabled = true
    }

    buffering_interval = 300
    buffering_size     = 5
    compression_format = "GZIP"
    cloudwatch_logging_options {
      enabled = true
      log_group_name = "/aws/kinesisfirehose/example-firehose"
      log_stream_name = "firehose-log-stream"
    }
  }
}
```

---

**Notes:**

- Replace `"example-bucket"` with the actual name of your S3 bucket.
- The `prefix` and `error_output_prefix` can be customized based on your data organization needs.
- The IAM role is created with the necessary permissions to write to S3 and log to CloudWatch.
- Dynamic partitioning is enabled via the `dynamic_partitioning_configuration` block.

