This Terraform configuration creates a Kinesis Firehose Delivery Stream that sends data to an Elasticsearch destination. It includes the necessary IAM role and policy to allow Firehose to write to Elasticsearch. Additionally, it provisions an S3 bucket to serve as a backup destination in case of failures or for data retention. The configuration ensures that all required resources are defined and properly referenced.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "firehose_backup" {
  bucket = "firehose-backup-bucket-${random_string.suffix.result}"
  acl    = "private"

  tags = {
    Name = "firehose-backup-bucket"
  }
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}

resource "aws_iam_role" "firehose_role" {
  name = "firehose_delivery_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "firehose.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "firehose_s3_access" {
  role       = aws_iam_role.firehose_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3FullAccess"
}

resource "aws_iam_role_policy_attachment" "firehose_elasticsearch_access" {
  role       = aws_iam_role.firehose_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonESFullAccess"
}

resource "aws_kinesis_firehose_delivery_stream" "firehose_stream" {
  name        = "firehose-delivery-stream"
  destination = "elasticsearch"

  elasticsearch_destination_configuration {
    domain_arn = "arn:aws:es:us-west-2:123456789012:domain/my-elasticsearch-domain"
    role_arn   = aws_iam_role.firehose_role.arn
    index_name = "firehose-index"
    type_name  = "firehose-type"
  }

  s3_configuration {
    role_arn       = aws_iam_role.firehose_role.arn
    bucket_arn     = aws_s3_bucket.firehose_backup.arn
    buffer_size    = 5
    buffer_interval = 300
  }

  tags = {
    Environment = "dev"
  }
}
```

---

**Notes:**

- Replace `"arn:aws:es:us-west-2:123456789012:domain/my-elasticsearch-domain"` with the actual ARN of your Elasticsearch domain.
- This configuration assumes that you already have an Elasticsearch domain set up in AWS.
- The `random_string` resource is used to generate a unique suffix for the S3 bucket name to avoid naming conflicts.
- The IAM role is granted access to both S3 and Elasticsearch to ensure the Firehose stream can deliver data and back it up.

