**Description of the Terraform Program:**

This Terraform configuration creates a Kinesis Firehose Delivery Stream that sends data to an OpenSearch domain. The configuration includes:

- A Kinesis Firehose Delivery Stream with a buffer size and interval.
- An OpenSearch domain (using AWS Elasticsearch Service, as OpenSearch is compatible with it).
- An IAM role and policy that allows Firehose to write to the OpenSearch domain.
- A provider configuration for AWS in the `us-east-1` region.

---

**Terraform HCL Code:**

```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM Role for Kinesis Firehose
resource "aws_iam_role" "firehose_role" {
  name = "firehose_opensearch_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "firehose.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

# IAM Policy for Kinesis Firehose to write to OpenSearch
resource "aws_iam_role_policy" "firehose_opensearch_policy" {
  name = "firehose_opensearch_policy"
  role = aws_iam_role.firehose_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "es:ESHttpPut",
        "es:ESHttpPost"
      ]
      Resource = "*"
    }]
  })
}

# OpenSearch Domain (using Elasticsearch Service)
resource "aws_elasticsearch_domain" "opensearch_domain" {
  domain_name = "opensearch-firehose-domain"

  elasticsearch_version = "7.10"

  cluster_config {
    instance_type = "t3.small.elasticsearch"
    instance_count = 1
  }

  access_policies = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { AWS = "arn:aws:iam::${aws_caller_identity.current.account_id}:role/firehose_opensearch_role" }
      Action = [
        "es:ESHttpPut",
        "es:ESHttpPost"
      ]
      Resource = "*"
    }]
  })

  ebs_options {
    ebs_enabled = true
    volume_type = "gp2"
    volume_size = 10
  }

  tags = {
    Name = "opensearch-firehose-domain"
  }
}

# Kinesis Firehose Delivery Stream
resource "aws_kinesis_firehose_delivery_stream" "firehose_stream" {
  name        = "firehose-to-opensearch"
  destination = "elasticsearch"

  elasticsearch_destination_configuration {
    domain_arn = aws_elasticsearch_domain.opensearch_domain.arn
    role_arn   = aws_iam_role.firehose_role.arn
    index_name = "firehose-index"
    type_name  = "firehose-type"
  }

  buffer_size = 5
  buffer_interval = 300
}
```

---

**Notes:**

- This configuration assumes you are using AWS Elasticsearch Service, which is compatible with OpenSearch.
- The OpenSearch domain is created with a single instance for simplicity; you can scale it as needed.
- The IAM role and policy are created to allow Firehose to write to the OpenSearch domain.
- The Firehose delivery stream is configured to send data to the OpenSearch domain with a buffer size of 5 MB and interval of 300 seconds.

