**Description of the Terraform Program:**

This Terraform configuration creates a Kinesis Firehose Delivery Stream that sends data to a Splunk destination. The configuration includes:

- A Kinesis Firehose Delivery Stream with a Splunk destination.
- An IAM role and policy that allows the Firehose stream to send data to Splunk.
- A provider configuration for AWS in the `us-east-1` region.

The configuration assumes that the Splunk endpoint and token are provided as variables, with default values for testing purposes.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "splunk_hec_endpoint" {
  description = "Splunk HTTP Event Collector endpoint URL"
  default     = "https://splunk.example.com:8088/services/collector"
}

variable "splunk_hec_token" {
  description = "Splunk HTTP Event Collector token"
  default     = "your_splunk_hec_token"
}

resource "aws_iam_role" "firehose_splunk_role" {
  name = "firehose-splunk-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "firehose.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "firehose_splunk_policy" {
  role       = aws_iam_role.firehose_splunk_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSFirehoseFullAccess"
}

resource "aws_kinesis_firehose_delivery_stream" "splunk_delivery_stream" {
  name        = "splunk-delivery-stream"
  destination = "splunk_hec"

  splunk_hec_configuration {
    endpoint_configuration {
      endpoint = var.splunk_hec_endpoint
      token    = var.splunk_hec_token
    }

    retry_options {
      dot_count = 3
    }

    processing_configuration {
      enabled = true
      processors {
        type = "Lambda"
        parameters {
          parameter_name  = "LambdaArn"
          parameter_value = "arn:aws:lambda:us-east-1:123456789012:function:firehose-processor"
        }
      }
    }

    cloudwatch_logging_options {
      enabled = true
      log_group_name = "/aws/kinesisfirehose/splunk-delivery-stream"
      log_stream_name = "firehose-logs"
    }
  }
}
```

---

**Note:** This configuration assumes that you have a Lambda function (`firehose-processor`) already created and configured to process records before sending them to Splunk. If you need a Lambda function as part of the configuration, let me know, and I can extend the setup accordingly.

