**Description of the Terraform Program:**

This Terraform configuration creates a Kinesis Firehose Delivery Stream that sends data to an OpenSearch Serverless collection. The configuration includes:

- A Kinesis Firehose Delivery Stream with a buffering interval and size.
- An OpenSearch Serverless collection with a dedicated access policy.
- An IAM role that allows Firehose to write to the OpenSearch Serverless collection.
- A policy that grants the Firehose role the necessary permissions to interact with OpenSearch Serverless.

The configuration is designed to be deployed in the `us-east-1` region, which is required for OpenSearch Serverless.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "firehose_opensearch_role" {
  name = "firehose_opensearch_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "firehose.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "firehose_opensearch" {
  role       = aws_iam_role.firehose_opensearch_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSFirehoseOpenSearchServerlessFullAccess"
}

resource "aws_opensearchserverless_collection" "example_collection" {
  name = "example-collection"
  type = "TENANT"

  access_policies = jsonencode([
    {
      "Rules" = [{
        "Resource" = "collection/example-collection",
        "Permission" = "aoss:CreateIndex",
        "Principal" = "arn:aws:iam::${aws_iam_role.firehose_opensearch_role.arn}:role/firehose_opensearch_role"
      }]
    }
  ])
}

resource "aws_kinesis_firehose_delivery_stream" "example_firehose" {
  name        = "example-firehose"
  destination = "opensearchserverless"

  opensearchserverless_destination_configuration {
    collection_endpoint = aws_opensearchserverless_collection.example_collection.collection_endpoint
    role_arn            = aws_iam_role.firehose_opensearch_role.arn
    index_name          = "firehose-index"
    s3_configuration {
      role_arn       = aws_iam_role.firehose_opensearch_role.arn
      bucket_arn     = "arn:aws:s3:::example-bucket"
      buffer_interval = 300
      buffer_size     = 5
    }
  }

  buffer_interval = 300
  buffer_size     = 5
}
```

---

**Note:** This configuration assumes the existence of an S3 bucket (`example-bucket`) for intermediate buffering. You may need to create that bucket separately or adjust the `bucket_arn` accordingly.

