      output {
        name = "output"
        output_schema {
          record_format {
            record_format_type = "CSV"
            mapping_parameters {
              csv_mapping_parameters {
                record_column_delimiter = ","
                record_row_delimiter = "\n"
              }
            }
          }
          record_encoding = "UTF-8"
          record_columns {
            name = "id"
            sql_type = "INTEGER"
          }
          record_columns {
            name = "data"
            sql_type = "VARCHAR(256)"
          }
        }
        kinesis_firehose_output_configuration {
          resource_arn = aws_kinesis_firehose_delivery_stream.example.arn
          role_arn     = aws_iam_role.kinesis_analytics_role.arn
        }
      }

      reference_data_source {
        name = "reference"
        reference_schema {
          record_format {
            record_format_type = "CSV"
            mapping_parameters {
              csv_mapping_parameters {
                record_column_delimiter = ","
                record_row_delimiter = "\n"
              }
            }
          }
          record_encoding = "UTF-8"
          record_columns {
            name = "id"
            sql_type = "INTEGER"
          }
          record_columns {
            name = "value"
            sql_type = "VARCHAR(256)"
          }
        }
        s3_reference_data_source {
          bucket_arn = aws_s3_bucket.reference.arn
          file_key   = "reference.csv"
          reference_iam_role_arn = aws_iam_role.kinesis_analytics_role.arn
        }
      }

      sql_query = "SELECT STREAM id, data FROM input;"
    }
  }

  tags = {
    Environment = "dev"
  }
}

resource "aws_kinesis_firehose_delivery_stream" "example" {
  name = "example-output-stream"
  destination = "s3"

  s3_configuration {
    role_arn       = aws_iam_role.kinesis_analytics_role.arn
