---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "kendra_data_source_role" {
  name = "kendra-data-source-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "kendra.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "kendra_data_source_policy" {
  role       = aws_iam_role.kendra_data_source_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSKendraFullAccess"
}

resource "aws_kendra_data_source" "example" {
  name             = "example-data-source"
  index_id         = "example-index-id" # Replace with your Kendra index ID
  type             = "S3"
  role_arn         = aws_iam_role.kendra_data_source_role.arn
  schedule         = "cron(0 1 * * ? *)"
  description      = "Example Kendra data source with proxy configuration"
  inclusion_pattern = ".*\\.txt"
  exclusion_pattern = ".*\\.tmp"

  s3_configuration {
    bucket_name = "example-bucket" # Replace with your S3 bucket name
    access_key  = "example-access-key" # Replace with your AWS access key
    secret_key  = "example-secret-key" # Replace with your AWS secret key
    crawl_stubs = false
    file_type   = "PDF"
  }

  proxy_configuration {
    host     = "proxy.example.com" # Replace with your proxy host
    port     = 8080                # Replace with your proxy port
    username = "proxy-user"       # Replace with your proxy username
    password = "proxy-password"   # Replace with your proxy password
  }
}
```

---

**Notes:**

- Replace placeholder values such as `example-index-id`, `example-bucket`, `example-access-key`, `example-secret-key`, and proxy credentials with actual values from your environment.
- Ensure that the Kendra index exists before deploying this configuration.
- The `aws_kendra_data_source` resource is only available in certain AWS regions. Ensure that your AWS account has Kendra enabled in the selected region (`us-east-1` in this case).

