**Description of the Terraform Program:**

This Terraform configuration creates a basic Amazon Kendra index with user group resolution enabled. The Kendra index is configured with a default name and a specified region. User group resolution is enabled by specifying an IAM role that allows Kendra to access user group information from your directory service (e.g., Active Directory). The IAM role is created with the necessary permissions to enable user group resolution.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "kendra_user_group_resolution_role" {
  name = "kendra-user-group-resolution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "kendra.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "kendra_user_group_resolution" {
  role       = aws_iam_role.kendra_user_group_resolution_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonKendraUserGroupResolution"
}

resource "aws_kendra_index" "example" {
