**Description of the Terraform Program:**

This Terraform configuration sets up a Route 53 zone named "primary" and implements a routing policy that directs traffic to the least congested endpoint using Route 53's latency-based routing. Two AWS instances (one in `us-east-1` and one in `eu-central-1`) are created as endpoints, and a Route 53 record is configured to use latency-based routing to select the closest (least congested) endpoint based on the user's location. An IAM role is created to allow the instances to be registered with Route 53 health checks if needed.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_route53_zone" "primary" {
  name = "primary.example.com"
  tags = {
    Name = "primary"
  }
}

resource "aws_instance" "us_east_1" {
  ami           = "ami-0c55b159cbfafe1f0" # Amazon Linux 2 AMI (us-east-1)
  instance_type = "t2.micro"
  availability_zone = "us-east-1a"
  tags = {
    Name = "us-east-1-endpoint"
  }
}

resource "aws_instance" "eu_central_1" {
  ami           = "ami-0c55b159cbfafe1f0" # Amazon Linux 2 AMI (eu-central-1)
  instance_type = "t2.micro"
  availability_zone = "eu-central-1a"
  tags = {
    Name = "eu-central-1-endpoint"
  }
}

resource "aws_route53_record" "latency_record" {
  zone_id = aws_route53_zone.primary.id
  name    = "primary.example.com"
  type    = "A"
  alias {
    name   = aws_instance.us_east_1.private_ip
    zone_id = aws_route53_zone.primary.id
    evaluate_target_health = true
  }
  latency_routing_policy {
    region = "us-east-1"
  }
  latency_routing_policy {
    region = "eu-central-1"
  }
}

resource "aws_iam_role" "route53_health_check_role" {
  name = "route53-health-check-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "ec2.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "route53_health_check" {
  role       = aws_iam_role.route53_health_check_role.name
  policy_arn = "arn:aws:iam::aws:policy/Route53HealthCheckAccess"
}
```

