**Description of the Terraform Program:**

This Terraform configuration creates an IAM role named `eks-cluster-1` that allows the EKS service (`eks.amazonaws.com`) to assume the role. The role is then associated with the `AmazonEKSClusterPolicy` managed policy, granting it the necessary permissions to manage an EKS cluster. The configuration also defines an EKS cluster using a variable for the cluster name and version, and associates it with the IAM role. The EKS cluster is configured with a specified VPC and subnet IDs, including both private and public subnets, in a given AWS region.

---

**Terraform HCL Code:**

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "cluster_name" {
  description = "Name of the EKS cluster"
  default     = "my-eks-cluster"
}

variable "cluster_version" {
  description = "Version of the EKS cluster"
  default     = "1.28"
}

variable "vpc_id" {
  description = "ID of the VPC to use for the EKS cluster"
  default     = "vpc-12345678"
}

variable "private_subnets" {
  description = "List of private subnet IDs"
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "public_subnets" {
  description = "List of public subnet IDs"
  default     = ["subnet-22334455", "subnet-55443322"]
}

resource "aws_iam_role" "eks_cluster_role" {
  name = "eks-cluster-1"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "eks.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_eks_cluster" "main" {
  name     = var.cluster_name
  version  = var.cluster_version
  role_arn = aws_iam_role.eks_cluster_role.arn

  vpc_config {
    vpc_id          = var.vpc_id
    subnet_ids      = concat(var.private_subnets, var.public_subnets)
    endpoint_public_access = true
    endpoint_private_access = true
  }

  depends_on = [aws_iam_role_policy_attachment.eks_cluster_policy]
}
