**Description of the Terraform Program:**

This Terraform configuration sets up the AWS provider in a specified region, retrieves the current AWS caller identity, and optionally fetches the latest stable ECR image from a specified repository. It defines local variables for image tags, AWS tags, and workspace names. It then provisions an EKS cluster using a module, including configurations for cluster setup, IAM policies, instance types, and node count. After the EKS cluster is created, it retrieves cluster information and authentication data. Finally, it configures the Helm and Kubernetes providers to communicate with the EKS cluster.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  image_tag      = "stable"
  aws_tags       = {
    Environment = "dev"
    Project     = "eks-demo"
  }
  workspace_name = "eks-cluster"
}

data "aws_caller_identity" "current" {}

resource "aws_ecr_image" "latest_stable" {
  repository_name = "my-ecr-repo"
  image_tag       = local.image_tag
  depends_on      = [aws_ecr_repository.image_repo]
}

resource "aws_ecr_repository" "image_repo" {
  name                 = "my-ecr-repo"
  image_tag_mutability = "IMMUTABLE"
  image_scanning_configuration {
    scan_on_push = true
  }
}

module "eks_cluster" {
  source  = "terraform-aws-modules/eks/aws"
  version = "19.1.0"

  cluster_name    = "my-eks-cluster"
  cluster_version = "1.26"

  vpc_id = aws_vpc.main.id

  subnets = [
    aws_subnet.private1.id,
    aws_subnet.private2.id,
  ]

  max_nodes = 3
  min_nodes = 1
  desired_nodes = 2

  node_group_name = "eks-worker-group"
  node_type       = "managed"
  node_image_ami  = "arn:aws:ec2:us-west-2:amazon:image-template/eks-1.26-vpc-2023-09-15"
  node_instance_type = "t3.medium"

  node_root_disk_size = 20

  node_iam_role_additional_policies = [
    "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy",
    "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy",
    "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly",
  ]

  tags = local.aws_tags
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = local.aws_tags
}

resource "aws_subnet" "private1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  map_public_ip_on_launch = false
  availability_zone = "us-west-2a"
  tags = local.aws_tags
}

resource "aws_subnet" "private2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  map_public_ip_on_launch = false
  availability_zone = "us-west-2b"
  tags = local.aws_tags
}

data "aws_eks_cluster" "cluster" {
  name = module.eks_cluster.cluster_id
}

data "aws_eks_cluster_auth" "cluster" {
  name = module.eks_cluster.cluster_id
}

provider "kubernetes" {
  host = data.aws_eks_cluster.cluster.endpoint
  cluster_ca_certificate = base64decode(data.aws_eks_cluster.cluster.certificate_authority.0.data)
  token                   = data.aws_eks_cluster_auth.cluster.token
  exec {
    api_version = "client.authentication.k8s.io/v1beta1"
    command     = "aws"
    args = [
      "eks",
      "get-token",
      "--cluster-name",
      data.aws_eks_cluster.cluster.name,
    ]
  }
}

provider "helm" {
  kubernetes {
    host = data.aws_eks_cluster.cluster.endpoint
    cluster_ca_certificate = base64decode(data.aws_eks_cluster.cluster.certificate_authority.0.data)
    token                   = data.aws_eks_cluster_auth.cluster.token
    exec {
      api_version = "client.authentication.k8s.io/v1beta1"
      command     = "aws"
      args = [
        "eks",
        "get-token",
        "--cluster-name",
        data.aws_eks_cluster.cluster.name,
      ]
    }
  }
}
```

---

**Notes:**

- This configuration assumes the existence of a VPC and subnets. If you are not using an existing VPC, you may need to add additional resources to create one.
- The `aws_ecr_image` resource is optional and will only be created if the `aws_ecr_repository` is created.
- The `eks` module is sourced from the [Terraform AWS EKS module](https://registry.terraform.io/modules/terraform-aws-modules/eks/aws).
- The `kubernetes` and `helm` providers are configured using the EKS cluster's endpoint and authentication data.
- This configuration is compatible with Terraform version `~> 1.9.8` and AWS provider version `~> 5.75`.

