**Description of the Terraform Program:**

This Terraform configuration creates an AWS EKS cluster and associates an IAM policy named "example" with it. The policy is linked to a specific principal (user or role) using an ARN, and access is restricted to a specific namespace within the EKS cluster. The configuration includes a provider block for AWS, an EKS cluster resource, an IAM policy, and an EKS cluster policy attachment with namespace scope.

---

**Terraform HCL Code:**

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_eks_cluster" "example" {
  name     = "example-cluster"
  role_arn = aws_iam_role.eks_role.arn

  vpc_config {
    subnet_ids = ["subnet-12345678", "subnet-87654321"]
  }

  depends_on = [aws_iam_role_policy_attachment.eks_service]
}

resource "aws_iam_role" "eks_role" {
  name = "eks-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "eks.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "eks_service" {
  role       = aws_iam_role.eks_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSServicePolicy"
}

resource "aws_iam_policy" "example_policy" {
  name        = "example"
  description = "Example policy for EKS access"
  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "ecr:GetDownloadAuthorizationToken",
        "ecr:BatchCheckLayerAvailability",
        "ecr:GetRepositoryPolicy",
        "ecr:DescribeRepositories",
        "ecr:ListImages",
        "ecr:DescribeImageTags"
      ]
      Resource = "*"
    }]
  })
}

resource "aws_eks_cluster_policy_attachment" "example_attachment" {
  cluster_name = aws_eks_cluster.example.name
  policy_arn   = aws_iam_policy.example_policy.arn
  principal_arn = "arn:aws:iam::123456789012:user/example-user"
  namespace    = "example-namespace"
}
```

---

**Notes:**

- Replace `"subnet-12345678"` and `"subnet-87654321"` with actual subnet IDs from your VPC.
- Replace `"arn:aws:iam::123456789012:user/example-user"` with the actual ARN of the principal (user or role) you want to grant access to.
- The `namespace` field in `aws_eks_cluster_policy_attachment` is used to scope the policy to a specific Kubernetes namespace within the EKS cluster.
- The `aws_iam_policy` resource defines a sample policy; you can replace the `policy` block with your custom policy document if needed.

