**Description of the Terraform Program:**

This Terraform configuration sets up an AWS S3 bucket and a DynamoDB table to be used for Terraform state management. The S3 bucket is configured with versioning, server-side encryption using AES256, and preventive measures to avoid accidental deletion (such as a bucket policy that denies delete actions). Public access is restricted using a bucket policy. The DynamoDB table is created with a hash key named 'LockID' and uses the 'PAY_PER_REQUEST' billing mode to support Terraform locking.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create an S3 bucket for Terraform state
resource "aws_s3_bucket" "terraform_state" {
  bucket = "terraform-state-bucket-unique-name"
  acl    = "private"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Create a bucket policy to prevent accidental deletion and restrict public access
resource "aws_s3_bucket_policy" "terraform_state_policy" {
  bucket = aws_s3_bucket.terraform_state.bucket

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Deny"
        Principal = "*"
        Action = [
          "s3:DeleteBucket",
          "s3:DeleteBucketPolicy",
          "s3:DeleteObjectVersion",
          "s3:PutObjectVersionAcl"
        ]
        Resource = [
          aws_s3_bucket.terraform_state.arn,
          "${aws_s3_bucket.terraform_state.arn}/*"
        ]
        Condition = {
          "StringNotLike" = {
            "aws:Referer" = "https://*.terraform.io/*"
          }
        }
      },
      {
        Effect = "Deny"
        Principal = "*"
        Action = "s3:*"
        Resource = [
          aws_s3_bucket.terraform_state.arn,
          "${aws_s3_bucket.terraform_state.arn}/*"
        ]
        Condition = {
          "Bool" = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

# Create a DynamoDB table for Terraform locking
resource "aws_dynamodb_table" "terraform_lock" {
  name           = "terraform-lock-table"
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }
}
```

