**Description of the Terraform Program:**

This Terraform configuration creates two AWS S3 buckets: one for CloudGoat data storage and another for web data storage. Both buckets use dynamic names that include a variable `bucket_suffix` with a default value of "test". The CloudGoat bucket is configured with private ACLs and ownership controls for ObjectWriter access. The web data bucket is configured with public access block settings to ignore public ACLs, block public ACLs, and restrict public buckets. Additionally, a bucket policy is applied to the web data bucket to allow the `s3:PutObject` action for all principals. An object named `order_data2.csv` is uploaded to the web data bucket from a local file path.

---

**Terraform HCL Code:**

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "bucket_suffix" {
  description = "Suffix for the S3 bucket names"
  default     = "test"
}

resource "aws_s3_bucket" "cloudgoat_data" {
  bucket = "cloudgoat-data-${var.bucket_suffix}"
  acl    = "private"

  # Ownership controls for ObjectWriter
  ownership_controls {
    rule {
      object_ownership = "BucketOwnerEnforced"
    }
  }

  versioning {
    enabled = false
  }
}

resource "aws_s3_bucket" "web_data" {
  bucket = "web-data-${var.bucket_suffix}"
  acl    = "private"

  # Public access block settings
  public_access_block_configuration {
    ignore_public_acls   = true
    block_public_acls    = true
    block_public_policy  = true
    restrict_public_buckets = true
  }

  versioning {
    enabled = false
  }
}

resource "aws_s3_bucket_policy" "web_data_policy" {
  bucket = aws_s3_bucket.web_data.bucket
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = "*"
      Action = "s3:PutObject"
      Resource = "arn:aws:s3:::web-data-${var.bucket_suffix}/*"
    }]
  })
}

resource "aws_s3_object" "order_data" {
  bucket = aws_s3_bucket.web_data.bucket
  key    = "order_data2.csv"
  source = "./order_data2.csv"
  acl    = "private"
}
```

---

**Notes:**

- Ensure the file `order_data2.csv` exists in the current working directory or adjust the `source` path accordingly.
- This configuration assumes the AWS provider is properly configured with credentials and region.
- The bucket policy allows `s3:PutObject` for all principals, which is a broad permission and should be reviewed for production use.

