**Description of the Terraform Program:**

This Terraform configuration will:

1. Create an SNS topic named `s3-event-notification-topic`.
2. Create an IAM policy document that allows the `s3.amazonaws.com` service to publish to the SNS topic, but only if the source ARN matches the ARN of a specific S3 bucket.
3. Create an S3 bucket named `your-bucket-name`.
4. Configure the S3 bucket to send notifications for `s3:ObjectCreated:*` events with a filter for files ending in `.log` to the SNS topic.

The configuration ensures that only the S3 service can publish to the SNS topic, and only when the event originates from the specified S3 bucket.

---

**Terraform HCL Code:**

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_sns_topic" "s3_event_notification_topic" {
  name = "s3-event-notification-topic"
}

resource "aws_iam_policy_document" "s3_publish_to_sns" {
  statement {
    effect = "Allow"

    principals {
      type = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = ["SNS:Publish"]

    resources = [aws_sns_topic.s3_event_notification_topic.arn]

    condition {
      test     = "ArnLike"
      variable = "AWS_SourceArn"
      values   = ["arn:aws:s3:::your-bucket-name"]
    }
  }
}

resource "aws_iam_role" "s3_notification_role" {
  name = "s3-notification-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "s3.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "s3_publish_to_sns" {
  role       = aws_iam_role.s3_notification_role.name
  policy_arn = aws_iam_policy_document.s3_publish_to_sns.id
}

resource "aws_s3_bucket" "your_bucket" {
  bucket = "your-bucket-name"
  acl    = "private"

  tags = {
    Name = "your-bucket-name"
  }
}

resource "aws_s3_bucket_notification" "s3_event_notification" {
  bucket = aws_s3_bucket.your_bucket.bucket

  topic {
    topic_arn = aws_sns_topic.s3_event_notification_topic.arn
    events    = ["s3:ObjectCreated:*"]
    filter {
      suffix = ".log"
    }
  }
}
```

---

**Notes:**

- Replace `"your-bucket-name"` with the actual name of your S3 bucket if needed.
- The `aws_iam_policy_document` is used to define the policy that allows S3 to publish to the SNS topic, but only if the source ARN matches the S3 bucket.
- The `aws_s3_bucket_notification` resource is used to configure the S3 bucket to send notifications to the SNS topic with a filter for `.log` files.

