This Terraform configuration creates a custom Virtual Private Cloud (VPC) with a CIDR block of `10.0.0.0/16`. It provisions two subnets in the availability zones `us-east-1a` and `us-east-1b`. For each subnet, an EC2 instance is launched using the latest Amazon Linux 2 AMI, with a `t2.micro` instance type and a 50 GB EBS volume attached. The configuration includes a provider block for AWS, default values for variables, and ensures all resources are fully declared and deployable.

---

**Terraform HCL Code:**

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_mask" {
  description = "CIDR block mask for subnets"
  default     = 24
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "subnet_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/${var.subnet_cidr_mask}"
  availability_zone = "us-east-1a"
  map_public_ip_on_launch = true
  tags = {
    Name = "subnet-a"
  }
}

resource "aws_subnet" "subnet_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/${var.subnet_cidr_mask}"
  availability_zone = "us-east-1b"
  map_public_ip_on_launch = true
  tags = {
    Name = "subnet-b"
  }
}

resource "aws_security_group" "allow_ssh" {
  name        = "allow-ssh"
  description = "Allow SSH access"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "allow-ssh"
  }
}

resource "aws_instance" "ec2_a" {
  ami           = "ami-0aa702f6153034920" # Amazon Linux 2 (latest)
  instance_type = "t2.micro"
  subnet_id     = aws_subnet.subnet_a.id
  security_groups = [aws_security_group.allow_ssh.name]
  tags = {
    Name = "ec2-instance-a"
  }

  root_block_device {
    volume_size = 50
  }
}

resource "aws_instance" "ec2_b" {
  ami           = "ami-0aa702f6153034920" # Amazon Linux 2 (latest)
  instance_type = "t2.micro"
  subnet_id     = aws_subnet.subnet_b.id
  security_groups = [aws_security_group.allow_ssh.name]
  tags = {
    Name = "ec2-instance-b"
  }

  root_block_device {
    volume_size = 50
  }
}
