**Description of the Terraform Program:**

This Terraform configuration creates a basic VPC with a public and a private subnet. It defines a Launch Template to ensure consistent configuration of EC2 instances and uses that template to launch an EC2 Fleet consisting of 5 On-Demand and 4 Spot Instances. The fleet will use the latest Amazon Linux 2 AMI and will be deployed in the private subnet. The configuration includes a provider block for AWS, a VPC, subnets, a security group, and an IAM role for EC2 instances.

---

**Terraform HCL Code:**

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  map_public_ip_on_launch = true
  availability_zone = "us-east-1a"
  tags = {
    Name = "public-subnet"
  }
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-east-1a"
  tags = {
    Name = "private-subnet"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "main-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "public-route-table"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route" "internet_gateway" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_security_group" "allow_ssh" {
  name        = "allow-ssh"
  description = "Allow SSH access"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "allow-ssh"
  }
}

resource "aws_iam_role" "ec2_role" {
  name = "ec2-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "ec2.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "ec2_role_policy" {
  role       = aws_iam_role.ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_launch_template" "ec2_fleet_lt" {
  name_prefix = "ec2-fleet-lt"
  image_id    = data.aws_ami.amazon_linux2.id
  instance_type = "t3.medium"
  key_name    = "your-key-pair-name" # Replace with your actual key pair name
  security_group_ids = [aws_security_group.allow_ssh.id]
  iam_instance_profile {
    arn = aws_iam_role.ec2_role.arn
  }
  user_data = <<EOF
#!/bin/bash
yum update -y
EOF
}

data "aws_ami" "amazon_linux2" {
  most_recent = true
  owners      = ["amazon"]
  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-2*-*"]
  }
}

resource "aws_ec2_fleet" "ec2_fleet" {
  target_capacity_specification {
    default_target_capacity_type = "spot"
    on_demand_target_capacity    = 5
    spot_target_capacity         = 4
  }

  launch_template_config {
    launch_template {
      id = aws_launch_template.ec2_fleet_lt.id
      version = "$Latest"
    }
    instance_type_config {
      instance_type = "t3.medium"
    }
  }

  placement = {
    group_name = "ec2-fleet-group"
  }

  subnet_id = aws_subnet.private.id
}
```

---

**Notes:**

- Replace `"your-key-pair-name"` with the name of an existing EC2 key pair in your AWS account.
- This configuration assumes that you have already created a key pair and that it is available in the region specified (`us-east-1`).
- The `aws_ami` data source is used to fetch the latest Amazon Linux 2 AMI.
- The EC2 Fleet is configured to use a mix of 5 On-Demand and 4 Spot instances, all using the same Launch Template for consistency.
- The EC2 instances will be launched in the private subnet and will have access to the internet via the route table and internet gateway.

