LLM Output #0:
**Description of the Terraform Program:**

This Terraform configuration provisions a Redis instance using Amazon ElastiCache. It creates a Redis (cluster mode disabled) replication group with a single node in the specified AWS region. The configuration includes a dedicated IAM role for ElastiCache, a security group to allow access to the Redis instance, and a subnet group for the ElastiCache cluster. The Redis instance is configured with a default cache parameter group and a default cache subnet group. All resources are created in the `us-west-2` region unless otherwise specified.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for ElastiCache
resource "aws_iam_role" "elasticache_role" {
  name = "elasticache-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "elasticache.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "elasticache_role_policy" {
  role       = aws_iam_role.elasticache_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSElastiCacheRole"
}

# Security Group for ElastiCache
resource "aws_security_group" "elasticache_sg" {
  name        = "elasticache-sg"
  description = "Allow access to ElastiCache Redis instance"
  vpc_id      = aws_vpc.default.id

  ingress {
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# VPC and Subnets
resource "aws_vpc" "default" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "public" {
  count             = 2
  vpc_id            = aws_vpc.default.id
  cidr_block        = "10.0.${count.index}.0/24"
  map_public_ip_on_launch = true
  availability_zone = data.aws_availability_zones.available.names[count.index]
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.default.id
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.default.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

data "aws_availability_zones" "available" {
  state = "available"
}

# Cache Subnet Group
resource "aws_elasticache_subnet_group" "default" {
  name       = "elasticache-subnet-group"
  description = "Subnet group for ElastiCache"
  subnet_ids = aws_subnet.public[*].id
}

# Redis Instance (ElastiCache)
resource "aws_elasticache_replication_group" "redis_instance" {
  replication_group_id         = "redis-instance"
  replication_group_description = "ElastiCache Redis instance"
  node_type                    = "cache.t2.micro"
  number_cache_clusters        = 1
  port                         = 6379
  security_group_ids           = [aws_security_group.elasticache_sg.id]
  subnet_group_name            = aws_elasticache_subnet_group.default.name
  automatic_failover_enabled   = false
  cache_parameter_group_name   = "default.redis6"
  cache_subnet_group_name      = aws_elasticache_subnet_group.default.name
  iam_role_arn                 = aws_iam_role.elasticache_role.arn
}
```

---

This configuration is ready to be deployed with Terraform version `~> 1.9.8` and the AWS provider version `~> 5.75`. It assumes that the AWS credentials are configured properly and that the user has the necessary permissions to create the resources.

