**Description of the Terraform Program:**

This Terraform configuration creates a single-node Amazon Redshift cluster using the AWS provider. It includes the necessary resources such as a Redshift cluster, a VPC, a subnet group, and an IAM role for the Redshift cluster. The configuration ensures that the cluster is deployed in a secure and isolated environment within a VPC. Default values are provided for variables to ensure the configuration is deployable out of the box.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a VPC for the Redshift cluster
resource "aws_vpc" "redshift_vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "redshift-vpc"
  }
}

# Create a subnet in the VPC
resource "aws_subnet" "redshift_subnet" {
  vpc_id            = aws_vpc.redshift_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  tags = {
    Name = "redshift-subnet"
  }
}

# Create a Redshift subnet group
resource "aws_redshift_subnet_group" "redshift_subnet_group" {
  name       = "redshift-subnet-group"
  subnet_ids = [aws_subnet.redshift_subnet.id]
  description = "Subnet group for Redshift cluster"
}

# Create an IAM role for Redshift
resource "aws_iam_role" "redshift_role" {
  name = "redshift-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "redshift.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

# Attach the Redshift managed policy to the IAM role
resource "aws_iam_role_policy_attachment" "redshift_default" {
  role       = aws_iam_role.redshift_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonRedshiftReadOnlyAccess"
}

# Create a Redshift cluster
resource "aws_redshift_cluster" "redshift_cluster" {
  cluster_identifier = "redshift-cluster"
  node_type          = "dc2.large"
  cluster_type       = "single-node"
  master_username    = "admin"
  master_password    = "SecurePassword123!"
  db_name            = "mydb"
  iam_roles          = [aws_iam_role.redshift_role.arn]
  subnet_ids         = [aws_subnet.redshift_subnet.id]
  skip_final_snapshot = true
  tags = {
    Name = "redshift-cluster"
  }
}
```

---

This configuration is ready to be applied with `terraform apply` and will create a single-node Redshift cluster in the `us-west-2a` availability zone. Make sure to update the `master_password` with a secure password of your choice.

