**Description of the Terraform Program:**

This Terraform configuration will set up a highly available Amazon Redshift cluster across two Availability Zones in the `us-east-1` region: `us-east-1a` and `us-east-1b`. The configuration includes:

- A Redshift cluster with multi-AZ support.
- A Redshift subnet group that spans both Availability Zones.
- A VPC with two public and two private subnets (one in each AZ).
- An IAM role for Redshift to access AWS services (if needed).
- A security group to allow access to the Redshift cluster.
- A default provider configuration for AWS in the `us-east-1` region.

Now, here is the Terraform HCL program:

```hcl
provider "aws" {
  region = "us-east-1"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "redshift-vpc"
  }
}

# Public Subnets
resource "aws_subnet" "public_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-1a"
  map_public_ip_on_launch = true
  tags = {
    Name = "public-subnet-a"
  }
}

resource "aws_subnet" "public_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-east-1b"
  map_public_ip_on_launch = true
  tags = {
    Name = "public-subnet-b"
  }
}

# Private Subnets
resource "aws_subnet" "private_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.10.0/24"
  availability_zone = "us-east-1a"
  tags = {
    Name = "private-subnet-a"
  }
}

resource "aws_subnet" "private_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.11.0/24"
  availability_zone = "us-east-1b"
  tags = {
    Name = "private-subnet-b"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "redshift-igw"
  }
}

# Route Table for Public Subnets
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "public-route-table"
  }
}

resource "aws_route" "public" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

# Associate Public Subnets with Public Route Table
resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

# Redshift Subnet Group
resource "aws_redshift_subnet_group" "main" {
  name = "redshift-subnet-group"
  subnet_ids = [
    aws_subnet.private_a.id,
    aws_subnet.private_b.id,
  ]
  description = "Subnet group for Redshift cluster"
}

# IAM Role for Redshift
resource "aws_iam_role" "redshift_role" {
  name = "redshift-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "redshift.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

# Attach Redshift Policy to the Role
resource "aws_iam_role_policy_attachment" "redshift_default" {
  role       = aws_iam_role.redshift_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonRedshiftReadOnlyAccess"
}

# Security Group for Redshift
resource "aws_security_group" "redshift_sg" {
  name        = "redshift-sg"
  description = "Allow access to Redshift cluster"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Redshift Cluster
resource "aws_redshift_cluster" "main" {
  cluster_identifier = "redshift-cluster"
  database_name      = "mydb"
  master_username    = "admin"
  master_password    = "SecurePassword123!"
  node_type          = "dc2.large"
  cluster_type       = "multi-node"
  numberOfNodes      = 2
  cluster_subnet_group_name = aws_redshift_subnet_group.main.name
  iam_roles         = [aws_iam_role.redshift_role.arn]
  publicly_accessible = false
  depends_on = [aws_redshift_subnet_group.main]
}
```

This configuration ensures that the Redshift cluster is deployed across two Availability Zones in `us-east-1`, with a subnet group spanning both zones, and is secured with a dedicated security group. The cluster is not publicly accessible, and an IAM role is attached to allow access to AWS services if needed.

