**Description of the Terraform Program:**

This Terraform configuration will create a 2-node Amazon Redshift cluster using the `dc2.large` node type and attach a resource policy to it. The cluster will be deployed in the `us-west-2` region. A Redshift cluster requires a VPC, subnet group, and a security group. The resource policy will allow access to the Redshift cluster from a specific AWS account (you can modify the `aws_account_id` variable accordingly). The configuration includes all necessary resources and sets default values for variables to ensure it is deployable with minimal input.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "cluster_identifier" {
  description = "The unique identifier for the Redshift cluster"
  default     = "my-redshift-cluster"
}

variable "node_type" {
  description = "The type of node to use for the Redshift cluster"
  default     = "dc2.large"
}

variable "number_of_nodes" {
  description = "The number of nodes in the Redshift cluster"
  default     = 2
}

variable "aws_account_id" {
  description = "The AWS account ID to allow access to the Redshift cluster"
  default     = "123456789012"
}

variable "vpc_id" {
  description = "The ID of the VPC to deploy the Redshift cluster in"
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "List of subnet IDs to use for the Redshift cluster"
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "security_group_id" {
  description = "The ID of the security group to associate with the Redshift cluster"
  default     = "sg-12345678"
}

variable "cluster_password" {
  description = "The password for the Redshift cluster admin user"
  default     = "SecurePassword123!"
}

resource "aws_redshift_cluster" "example" {
  cluster_identifier     = var.cluster_identifier
  node_type              = var.node_type
  number_of_nodes        = var.number_of_nodes
  cluster_type           = "multi-node"
  master_username        = "admin"
  master_password        = var.cluster_password
  vpc_id                 = var.vpc_id
  subnet_ids             = var.subnet_ids
  security_group_ids     = [var.security_group_id]
  skip_final_snapshot    = true
  automated_snapshot_retention_period = 0
}

resource "aws_redshift_cluster_iam_status" "example" {
  cluster_identifier = aws_redshift_cluster.example.cluster_identifier
  allow_iam_database_authentication = true
}

resource "aws_redshift_data_share" "example" {
  data_share_arn = aws_redshift_cluster.example.arn
  database_name  = "dev"
  table_name     = "example_table"
}

resource "aws_redshift_resource_policy" "example" {
  cluster_identifier = aws_redshift_cluster.example.cluster_identifier
  policy             = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        AWS = "arn:aws:iam::${var.aws_account_id}:root"
      }
      Action = [
        "redshift:DescribeClusters",
        "redshift:GetClusterCredentials",
        "redshift:Query",
        "redshift:DescribeQuery",
        "redshift:DescribeTable"
      ]
      Resource = "*"
    }]
  })
}
```

---

**Notes:**

- Replace the default values for `vpc_id`, `subnet_ids`, `security_group_id`, and `aws_account_id` with your actual AWS resources.
- The `aws_redshift_data_share` resource is optional and can be removed if you do not need to share data with other clusters.
- The `aws_redshift_resource_policy` grants access to the specified AWS account. You can modify the `Principal` and `Action` fields as needed for your use case.

