This Terraform configuration creates an AWS Lambda function that executes a simple Python script and schedules it to run every 15 minutes using an AWS EventBridge rule. The Lambda function is granted the necessary permissions to be invoked by EventBridge, and the EventBridge rule is configured with a fixed rate schedule of 15 minutes. The configuration includes a provider block for AWS, a Lambda function with a basic handler, and an EventBridge rule with a target pointing to the Lambda function.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_lambda_function" "example_lambda" {
  function_name    = "example_lambda"
  handler          = "lambda_function.lambda_handler"
  runtime          = "python3.10"
  filename         = "lambda_function.zip"
  role             = aws_iam_role.lambda_role.arn
  source_code_hash = filebase64sha256("lambda_function.zip")

  timeout = 30
  memory_size = 128
}

resource "aws_iam_role" "lambda_role" {
  name = "lambda_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "lambda.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_eventbridge_rule" "example_rule" {
  name          = "example_rule"
  schedule_expression = "rate(15 minutes)"
  description   = "Invoke Lambda every 15 minutes"
}

resource "aws_eventbridge_rule_target" "example_target" {
