This Terraform configuration sets up an AWS Lambda function named `test_lambda` that is triggered whenever a new EC2 AMI (Amazon Machine Image) is created. The Lambda function will be invoked via an AWS EventBridge rule that listens for the `aws.ec2.image.create` event. The configuration includes the Lambda function, an IAM role for the Lambda, an EventBridge rule, and an IAM policy to allow the EventBridge rule to invoke the Lambda function.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "lambda_role" {
  name = "lambda_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "lambda.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_iam_role_policy" "eventbridge_invoke_lambda" {
  name = "eventbridge_invoke_lambda"
  role = aws_iam_role.lambda_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = "lambda:InvokeFunction"
      Resource = "*"
    }]
  })
}

resource "aws_lambda_function" "test_lambda" {
  function_name    = "test_lambda"
  role             = aws_iam_role.lambda_role.arn
  handler          = "index.handler"
  runtime          = "nodejs18.x"
  filename         = "lambda_function.zip"
  source_code_hash = filebase64sha256("lambda_function.zip")

  environment {
    variables = {
      KEY = "value"
    }
  }
}

resource "aws_cloudwatch_log_group" "lambda_logs" {
  name = "/aws/lambda/test_lambda"
}

resource "aws_eventbridge_rule" "ec2_image_create" {
  name        = "ec2_image_create_rule"
  description = "Trigger Lambda on EC2 image creation"
  event_pattern = jsonencode({
    source = ["aws.ec2"]
    detail_type = ["EC2 Image Creation"]
    detail = {
      imageId = ["*"]
    }
  })
}

resource "aws_eventbridge_rule_target" "lambda_target" {
  rule      = aws_eventbridge_rule.ec2_image_create.name
  target_id = "test_lambda"
  target_type = "lambda_function"
  arn       = aws_lambda_function.test_lambda.arn
}
```

---

**Notes:**

- The `filename` and `source_code_hash` fields in the `aws_lambda_function` resource assume that you have a ZIP file named `lambda_function.zip` in the current working directory. You will need to create this file with the Lambda function code.
- The `event_pattern` is based on the AWS EventBridge schema for EC2 image creation events.
- The `aws_eventbridge_rule_target` resource links the EventBridge rule to the Lambda function, so that the Lambda is invoked when the event occurs.

