**Description of the Terraform Program:**

This Terraform configuration creates an AWS Lambda function that executes the code from a file named `lambda.js`. It also sets up the necessary IAM role and policy to allow the Lambda function to execute in AWS. The Lambda function is configured with a basic execution role that grants it the required permissions to run in the AWS environment. The code for the Lambda function is uploaded as a ZIP file to an S3 bucket, and the Lambda function is created using the S3 bucket as the source.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "lambda_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "lambda.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_s3_bucket" "lambda_code_bucket" {
  bucket = "lambda-code-bucket-${random_string.suffix.result}"
  acl    = "private"

  tags = {
    Name = "LambdaCodeBucket"
  }
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}

resource "aws_s3_object" "lambda_code" {
  bucket = aws_s3_bucket.lambda_code_bucket.bucket
  key    = "lambda.js"
  source = "lambda.js"
}

resource "aws_lambda_function" "lambda_function" {
  function_name    = "lambda_function"
  role             = aws_iam_role.lambda_role.arn
  handler          = "lambda.handler"
  runtime          = "nodejs18.x"
  filename         = aws_s3_object.lambda_code.id
  source_code_hash = aws_s3_object.lambda_code.etag

  timeout = 30
  memory_size = 128
}
```

---

**Notes:**

- The `lambda.js` file must be present in the working directory where Terraform is executed.
- The `source_code_hash` is set using the `etag` from the S3 object to ensure Terraform knows when the code has changed.
- The `random_string` resource is used to generate a unique bucket name to avoid naming conflicts.
- The IAM role allows the Lambda function to execute and log to CloudWatch.

