This Terraform configuration creates an AWS SageMaker Domain resource. A SageMaker Domain is a centralized location where users can collaborate, build, and deploy machine learning models. The configuration includes the necessary provider setup, a VPC, a subnet, and an IAM role for SageMaker execution. The domain is configured with a default user settings and a domain name. All required resources are declared and fully specified for deployment.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_sagemaker_domain" "example" {
  domain_name           = "example-sagemaker-domain"
  auth_mode             = "SSO"
  default_user_settings {
    execution_role    = aws_iam_role.sagemaker_execution.arn
    security_groups   = [aws_security_group.sagemaker_sg.id]
    sageMakerImage    = "arn:aws:sagemaker:us-east-1:123456789012:image/sagemaker-notebook-instance"
    sageMakerImageVersion = "1"
  }
  vpc_id                = aws_vpc.example.id
  subnet_ids            = [aws_subnet.example.id]
}

resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "example-vpc"
  }
}

resource "aws_subnet" "example" {
  vpc_id     = aws_vpc.example.id
  cidr_block = "10.0.1.0/24"
  tags = {
    Name = "example-subnet"
  }
}

resource "aws_security_group" "sagemaker_sg" {
  name        = "sagemaker-sg"
  description = "Security group for SageMaker"
  vpc_id      = aws_vpc.example.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "sagemaker-sg"
  }
}

resource "aws_iam_role" "sagemaker_execution" {
  name = "sagemaker-execution-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
