This Terraform configuration creates a SageMaker Pipeline resource in AWS. The pipeline is defined using a JSON structure that specifies the steps, parameters, and execution settings. The configuration includes a provider block for AWS, a SageMaker pipeline resource, and a default AWS region. It also includes a variable for the pipeline name, with a default value provided for convenience.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "pipeline_name" {
  description = "Name of the SageMaker pipeline"
  default     = "my-sagemaker-pipeline"
}

resource "aws_sagemaker_pipeline" "example" {
  name          = var.pipeline_name
  pipeline_definition = jsonencode({
    "pipelineSteps" = [
      {
        "Name" = "ProcessingStep",
        "Type" = "Processing",
        "ProcessingJobDefinition" = {
          "AppSpecification" = {
            "ImageUri" = "123456789012.dkr.ecr.us-east-1.amazonaws.com/processing-image:latest"
          },
          "ProcessingInputs" = [
            {
              "InputName" = "training-data",
              "S3Input" = {
                "S3Uri" = "s3://my-bucket/training-data",
                "LocalPath" = "/opt/ml/processing/input",
                "S3DataDistributionType" = "FullyReplicated"
              }
            }
          ],
          "ProcessingOutputConfig" = {
            "Outputs" = [
              {
                "OutputName" = "model-output",
                "S3Output" = {
                  "S3Uri" = "s3://my-bucket/model-output",
                  "LocalPath" = "/opt/ml/processing/output"
                }
              }
            ]
          },
          "RoleArn" = aws_iam_role.sagemaker_role.arn
        }
      }
    ],
    "parameters" = {
      "ProcessingInstanceType" = "ml.c4.xlarge"
    }
  })
  role_arn = aws_iam_role.sagemaker_role.arn
}

resource "aws_iam_role" "sagemaker_role" {
  name = "sagemaker-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "sagemaker_role_policy" {
  role       = aws_iam_role.sagemaker_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSageMakerFullAccess"
}
```

---

This configuration will create a SageMaker pipeline with a single processing step, using a specified image and input/output locations. It also creates an IAM role with the necessary permissions for SageMaker to execute the pipeline.

