**Description of the Terraform Program:**

This Terraform configuration will create a VPC with a public and a private subnet. It will then define an EC2 Fleet that consists of 5 On-Demand and 4 Spot Instances using the latest Amazon Linux 2 AMI. The instances will be launched using a launch template that specifies the AMI, instance type, and subnet. An IAM role will be created to allow the EC2 Fleet to use Spot Instances, and the provider configuration will be set to the `us-east-1` region.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  map_public_ip_on_launch = true
  availability_zone = "us-east-1a"
  tags = {
    Name = "public-subnet"
  }
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-east-1a"
  tags = {
    Name = "private-subnet"
  }
}

resource "aws_security_group" "allow_all" {
  name        = "allow-all"
  description = "Allow all inbound and outbound traffic"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "allow-all"
  }
}

resource "aws_iam_role" "spot_instance_role" {
  name = "spot-instance-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "ec2.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "spot_instance" {
  role       = aws_iam_role.spot_instance_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2SpotFleetRole"
}

resource "aws_launch_template" "ec2_fleet_lt" {
  name_prefix = "ec2-fleet-lt"
  image_id    = data.aws_ami.amazon_linux2.id
  instance_type = "t3.medium"
  vpc_security_group_ids = [aws_security_group.allow_all.id]
  subnet_id = aws_subnet.private.id
  iam_instance_profile {
    arn = aws_iam_role.spot_instance_role.arn
  }
}

data "aws_ami" "amazon_linux2" {
  most_recent = true
  owners      = ["amazon"]
  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-2*-*_x86_64-gp2"]
  }
}

resource "aws_spot_fleet_request" "ec2_fleet" {
  iam_fleet_role = aws_iam_role.spot_instance_role.arn
  target_capacity = 9
  on_demand_target = 5
  spot_target = 4
  launch_template_config {
    launch_template {
      id = aws_launch_template.ec2_fleet_lt.id
      version = "$Latest"
    }
  }
}
```

