    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "efs-sg"
  }
}

resource "aws_efs_file_system" "shared" {
  creation_token = "shared-efs"
  tags = {
    Name = "shared-efs"
  }
}

resource "aws_efs_mount_target" "private" {
  file_system_id = aws_efs_file_system.shared.id
  subnet_id      = aws_subnet.private.id
  security_groups = [aws_security_group.efs_sg.id]
}

resource "aws_iam_role" "efs_role" {
  name = "efs-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "ec2.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "efs_role" {
  role       = aws_iam_role.efs_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEFSReadOnlyAccess"
}

resource "aws_iam_role" "ec2_role" {
  name = "ec2-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "ec2.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "ec2_role" {
  role       = aws_iam_role.ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_instance" "app" {
  count = 2
  ami = var.ami_id
  instance_type = var.instance_type
  subnet_id = aws_subnet.private.id
  vpc_security_group_ids = [aws_security_group.efs_sg.id]
  iam_instance_profile = aws_iam_role.ec2_role.name
  tags = {
    Name = "app-instance-${count.index + 1}"
  }

  user_data = <<-EOF
              #!/bin/bash
              yum update -y
              yum install -y amazon-efs-utils
              mkdir /efs
              mount -t efs ${aws_efs_file_system.shared.id}:/ /efs
              echo "/efs  $(aws efs describe-file-systems --file-system-id ${aws_efs_file_system.shared.id} --query 'FileSystems[0].FileSystemId' --output text):/  efs defaults 0 0" >> /etc/fstab
              EOF
}
```

---

**Notes:**

- This configuration assumes that the AWS region is `us-east-1` and that the latest Amazon Linux 2 AMI is used.
- The EFS file system is mounted on both instances using the `user_data` script.
- The EFS mount target is created in the same private subnet as the EC2 instances.
- The EC2 instances are assigned the `ec2-role` IAM role, which allows them to use AWS Systems Manager (SSM) and access the EFS file system.

You can apply this configuration using `terraform apply` after initializing the Terraform working directory.

