**Description of the Terraform Program:**

This Terraform configuration creates an Amazon ElastiCache Redis cluster and sets up an IAM user with the necessary permissions to authenticate and interact with the Redis instance. The IAM user is granted permissions to connect to the ElastiCache cluster using Redis commands. The configuration includes a Redis cluster, an IAM user, and an IAM policy that allows the user to access the ElastiCache cluster.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_elasticache_cluster" "redis_cluster" {
  cluster_id           = "my-redis-cluster"
  engine               = "redis"
  engine_version       = "6.x"
  node_type            = "cache.t2.micro"
  num_cache_nodes      = 1
  parameter_group_name = "default.redis6"
  port                 = 6379
  subnet_group_name    = "default"
  security_group_ids   = [aws_security_group.redis_sg.id]
}

resource "aws_security_group" "redis_sg" {
  name        = "redis-sg"
  description = "Allow access to Redis cluster"
  vpc_id      = "vpc-12345678" # Replace with your actual VPC ID

  ingress {
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"] # For demo purposes; restrict in production
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_user" "redis_user" {
  name = "redis-access-user"
}

resource "aws_iam_policy" "redis_access_policy" {
  name        = "redis-access-policy"
  description = "Allows access to ElastiCache Redis cluster"
  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "elasticache:DescribeCacheClusters",
          "elasticache:DescribeCacheParameters",
          "elasticache:DescribeCacheSecurityGroups",
          "elasticache:DescribeCacheSubnetGroups",
          "elasticache:DescribeReplicationGroups",
          "elasticache:DescribeSnapshots",
          "elasticache:DescribeTags",
          "elasticache:DescribeUserGroups",
          "elasticache:DescribeUsers",
          "elasticache:ListTagsForResource"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "elasticache:CreateUser",
          "elasticache:DeleteUser",
          "elasticache:UpdateUser"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_user_policy_attachment" "redis_access_attachment" {
  user       = aws_iam_user.redis_user.name
  policy_arn = aws_iam_policy.redis_access_policy.arn
}

output "redis_endpoint" {
  value = aws_elasticache_cluster.redis_cluster.redis_endpoint
}
```

---

**Notes:**

- Replace `"vpc-12345678"` with your actual VPC ID.
- The IAM user is granted permissions to manage ElastiCache users and describe cluster details. For actual Redis authentication, you may need to create a Redis user using the `aws_elasticache_user` resource and assign it to a user group.
- This configuration assumes you are using a default VPC and subnet group. If not, you may need to create a custom subnet group and VPC.

Let me know if you'd like to include Redis user authentication and access control as well.

