---

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_dax_cluster" "example" {
  cluster_name           = "example-dax-cluster"
  node_type              = "dax.r4.large"
  replication_factor     = 1
  parameter_group_name   = "default.dax.1.0"
  subnet_group_name      = aws_dax_subnet_group.example.name
  security_group_ids     = [aws_security_group.example.id]
  iam_role_arn         = aws_iam_role.example.arn
}

resource "aws_dax_subnet_group" "example" {
  name       = "example-dax-subnet-group"
  subnet_ids = [aws_subnet.example1.id, aws_subnet.example2.id]
}

resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "example1" {
  vpc_id            = aws_vpc.example.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "example2" {
  vpc_id            = aws_vpc.example.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_security_group" "example" {
  name        = "example-dax-sg"
  description = "Allow DAX cluster traffic"
  vpc_id      = aws_vpc.example.id

  ingress {
    from_port   = 8111
    to_port     = 8111
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "example" {
  name = "example-dax-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "dax.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "example" {
  role       = aws_iam_role.example.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonDAXRole"
}
