LLM Output #0:
**Description of the Terraform Program:**

This Terraform configuration will create an Amazon Managed Streaming for Apache Kafka (MSK) cluster with 3 broker nodes. The cluster will be deployed in the `us-east-1` region using the `aws` provider. The configuration includes a VPC, subnets, security groups, and an IAM role for MSK. The MSK cluster will be configured with a single Kafka version, and the broker nodes will be spread across three Availability Zones for high availability. Default values are provided for all variables to ensure the configuration is deployable out of the box.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "msk_cluster_name" {
  description = "Name of the MSK cluster"
  default     = "msk-cluster"
}

variable "msk_broker_node_count" {
  description = "Number of broker nodes"
  default     = 3
}

variable "msk_kafka_version" {
  description = "Kafka version for the MSK cluster"
  default     = "3.3"
}

variable "msk_vpc_id" {
  description = "ID of the VPC where the MSK cluster will be deployed"
  default     = "vpc-12345678"
}

variable "msk_subnets" {
  description = "List of subnet IDs for the MSK cluster"
  default     = ["subnet-12345678", "subnet-87654321", "subnet-11223344"]
}

variable "msk_security_group_id" {
  description = "ID of the security group for the MSK cluster"
  default     = "sg-12345678"
}

variable "msk_iam_role_arn" {
  description = "ARN of the IAM role for MSK"
  default     = "arn:aws:iam::123456789012:role/msk-role"
}

resource "aws_msk_cluster" "example" {
  cluster_name           = var.msk_cluster_name
  kafka_version          = var.msk_kafka_version
  number_of_broker_nodes = var.msk_broker_node_count
  broker_node_group_info {
    client_subnets         = var.msk_subnets
    instance_type          = "kafka.m5.large"
    security_groups        = [var.msk_security_group_id]
    storage_volume_size    = 100
    storage_type           = "EBS"
    zookeeper_connectivity = "VPC"
    broker_connectivity    = "VPC"
  }

  encryption_info {
    encryption_in_transit {
      in_cluster = true
      client_broker = "TLS"
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs_enabled = true
      firehose_enabled        = false
      s3_enabled              = false
    }
  }

  tags = {
    Environment = "dev"
  }
}
```

