**Description of the Terraform Program:**

This Terraform configuration creates a managed Amazon MSK (Managed Streaming for Apache Kafka) cluster in the `us-east-1` region with 3 broker nodes. The configuration includes the necessary AWS provider setup, a VPC with a subnet group, and an IAM role for MSK. The MSK cluster is configured with a single Kafka version, a default number of partitions, and a replication factor. All required resources are declared and fully specified for deployment.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_vpc" "msk_vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "msk-vpc"
  }
}

resource "aws_subnet" "msk_subnets" {
  count = 3
  vpc_id = aws_vpc.msk_vpc.id
  cidr_block = "10.0.${count.index + 1}.0/24"
  map_public_ip_on_launch = false
  tags = {
    Name = "msk-subnet-${count.index + 1}"
  }
}

resource "aws_iam_role" "msk_role" {
  name = "msk-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "kafka.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "msk_kafka" {
  role       = aws_iam_role.msk_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSKafkaFullAccess"
}

resource "aws_msk_cluster" "example" {
  cluster_name           = "example-cluster"
  kafka_version        = "3.3"
  number_of_broker_nodes = 3
  broker_node_group_info {
    instance_type = "kafka.m5.large"
    client_subnets = aws_subnet.msk_subnets[*].id
    security_groups = [aws_security_group.msk_sg.id]
    storage_volume_size = 100
  }
  zookeeper_connectivity {
    vpc_connectivity = {}
  }
  kafka_connectivity {
    vpc_connectivity = {}
  }
  tags = {
    Environment = "dev"
  }
}

resource "aws_security_group" "msk_sg" {
  name        = "msk-sg"
  description = "Security group for MSK cluster"
  vpc_id      = aws_vpc.msk_vpc.id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "msk-sg"
  }
}
```

