**Description of the Terraform Program:**

This Terraform configuration will create an Amazon Managed Streaming for Apache Kafka (MSK) cluster in the `us-east-2` region with 3 broker nodes. The configuration includes a dedicated VPC with a public and private subnet, a security group for the MSK cluster, and an IAM role for the MSK service. The MSK cluster will be configured with a single Kafka topic and will use a default configuration for simplicity. All necessary resources are declared and fully specified for deployment.

---

```hcl
provider "aws" {
  region = "us-east-2"
}

resource "aws_vpc" "msk_vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "msk-vpc"
  }
}

resource "aws_subnet" "public_subnet" {
  vpc_id            = aws_vpc.msk_vpc.id
  cidr_block        = "10.0.1.0/24"
  map_public_ip_on_launch = true
  availability_zone = "us-east-2a"
  tags = {
    Name = "msk-public-subnet"
  }
}

resource "aws_subnet" "private_subnet" {
  vpc_id            = aws_vpc.msk_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-east-2a"
  tags = {
    Name = "msk-private-subnet"
  }
}

resource "aws_security_group" "msk_security_group" {
  name        = "msk-sg"
  description = "Security group for MSK cluster"
  vpc_id      = aws_vpc.msk_vpc.id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "msk-sg"
  }
}

resource "aws_iam_role" "msk_role" {
  name = "msk-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "kafka.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "msk_kafka_access" {
  role       = aws_iam_role.msk_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSKafkaFullAccess"
}

resource "aws_msk_cluster" "example" {
  cluster_name           = "example-cluster"
  kafka_version        = "3.3"
  number_of_broker_nodes = 3
  broker_node_group_info {
    instance_type = "kafka.m5.large"
    client_subnets  = [aws_subnet.public_subnet.id, aws_subnet.private_subnet.id]
    security_groups = [aws_security_group.msk_security_group.id]
    storage_volume_type = "ebs"
    storage_volume_size = 100
  }

  encryption_info {
    encryption_in_transit {
      in_cluster = true
      client_broker = "TLS"
    }
  }

  zookeeper_connectivity {
    vpc_connectivity {}
  }

  kafka_connect {
    version = "2.8.1"
  }

  tags = {
    Environment = "dev"
  }
}
```

