  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.75"
    }
  }

  required_version = "~> 1.9.8"
}

provider "aws" {
  region = "us-east-1"
  profile = "admin-1"

  assume_role {
    role_arn = "arn:aws:iam::590184057477:role/yicun-iac"
  }
}

resource "aws_vpc" "vpc" {
    cidr_block = "192.168.0.0/22"
}

data "aws_availability_zones" "azs" {
    state = "available"
}

resource "aws_subnet" "subnet_az1" {
    availability_zone = data.aws_availability_zones.azs.names[0]
    cidr_block = "192.168.0.0/24"
    vpc_id = aws_vpc.vpc.id
    map_public_ip_on_launch = true
}

resource "aws_subnet" "subnet_az2" {
    availability_zone = data.aws_availability_zones.azs.names[1]
    cidr_block = "192.168.1.0/24"
    vpc_id = aws_vpc.vpc.id
    map_public_ip_on_launch = true
}

resource "aws_subnet" "subnet_az3" {
    availability_zone = data.aws_availability_zones.azs.names[2]
    cidr_block = "192.168.2.0/24"
    vpc_id = aws_vpc.vpc.id
    map_public_ip_on_launch = true
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.vpc.id
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
}

resource "aws_route_table_association" "first" {
  subnet_id      = aws_subnet.subnet_az1.id
  route_table_id = aws_route_table.main.id
}

resource "aws_route_table_association" "second" {
  subnet_id      = aws_subnet.subnet_az2.id
  route_table_id = aws_route_table.main.id
}

resource "aws_route_table_association" "third" {
  subnet_id      = aws_subnet.subnet_az3.id
  route_table_id = aws_route_table.main.id
}

resource "aws_security_group" "sg" {
    vpc_id = aws_vpc.vpc.id
}

resource "aws_vpc_security_group_ingress_rule" "ingress1" {
  security_group_id = aws_security_group.sg.id
  cidr_ipv4 = "0.0.0.0/0"
  ip_protocol = "-1"
}

resource "aws_vpc_security_group_egress_rule" "egress1" {
  security_group_id = aws_security_group.sg.id
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "-1"
}

resource "aws_cloudwatch_log_group" "test" {
    name = "msk_broker_logs"
}

resource "aws_msk_cluster" "example" {
    cluster_name = "example"
    kafka_version = "3.2.0"
    number_of_broker_nodes = 3

    broker_node_group_info {
        instance_type = "kafka.t3.small"
        client_subnets = [
            aws_subnet.subnet_az1.id,
            aws_subnet.subnet_az2.id,
            aws_subnet.subnet_az3.id,
        ]

        storage_info {
            ebs_storage_info {
                volume_size = 1000
            }
        }

        security_groups = [aws_security_group.sg.id]
    }

    open_monitoring {
        prometheus {
            jmx_exporter {
                enabled_in_broker = true
            }
            node_exporter {
                enabled_in_broker = true
            }
        }
    }

    logging_info {
        broker_logs {
            cloudwatch_logs {
                enabled = true
                log_group = aws_cloudwatch_log_group.test.name
            }
            firehose {
                enabled = false
            }
            s3 {
                enabled = false
            }
        }
    }
}

output "zookeeper_connect_string" {
    value = aws_msk_cluster.example.zookeeper_connect_string
}

output "bootstrap_brokers_tls" {
    description = "TLS connection host:port pairs"
    value = aws_msk_cluster.example.bootstrap_brokers_tls
}

LLM Output #0:
**Description of the Terraform Program:**

This Terraform configuration will create a managed Amazon MSK (Managed Streaming for Apache Kafka) cluster in the `us-east-1` region. The cluster will be configured to log its operations to a CloudWatch Logs group. The configuration includes the necessary AWS provider setup, IAM roles for MSK, a CloudWatch Logs group, and the MSK cluster itself with logging enabled.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-east-1"
}

# Create a CloudWatch Logs group for MSK logs
resource "aws_cloudwatch_log_group" "msk_logs" {
  name = "msk-cluster-logs"
}

# Create an IAM role for MSK to use for logging
resource "aws_iam_role" "msk_logging_role" {
  name = "msk-logging-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "logs.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

# Attach the CloudWatch Logs policy to the IAM role
resource "aws_iam_role_policy_attachment" "msk_logging_attachment" {
  role       = aws_iam_role.msk_logging_role.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchLogsFullAccess"
}

# Create the MSK cluster
resource "aws_msk_cluster" "example" {
  cluster_name           = "example-cluster"
  kafka_version        = "3.3"
  number_of_brokers    = 3
  broker_node_group_info {
    instance_type = "kafka.m5.large"
    client_subnets  = ["subnet-12345678", "subnet-87654321"] # Replace with your subnets
    security_groups = ["sg-12345678"] # Replace with your security group
    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled = true
        log_group = aws_cloudwatch_log_group.msk_logs.name
      }
    }
  }

  # Optional: Add encryption in transit and at rest
  encryption_in_transit {
    client_broker = "TLS_PLAINTEXT"
    in_cluster  = true
  }

  # Optional: Add encryption at rest
  encryption_at_rest {
    data_volume_kms_key_id = "arn:aws:kms:us-east-1:123456789012:key/abcd1234-a123-4567-8abc-def123456789"
  }

  # Optional: Add a VPC and other configurations
  vpc_config {
    vpc_id = "vpc-12345678" # Replace with your VPC ID
  }

  # Optional: Add tags
  tags = {
    Environment = "dev"
  }
}
```

---

**Notes:**

- Replace placeholder values like subnets, security groups, VPC ID, and KMS key ID with actual values from your AWS environment.
- Ensure that the AWS provider version is set to `~> 1.9.8` and the `aws` provider plugin version is `~> 5.75` in your `terraform` and `provider` blocks, respectively.
- This configuration assumes you have already created the necessary VPC, subnets, and security groups. If not, you may need to add additional resources to create them.

