LLM Output #0:
**Description of the Terraform Program:**

This Terraform configuration creates a managed Amazon MSK (Managed Streaming for Apache Kafka) cluster in the `us-east-1` region. The cluster is configured to log its data to an S3 bucket. The configuration includes:

- An AWS S3 bucket to store the logs.
- An IAM role and policy that allows the MSK cluster to write logs to the S3 bucket.
- A managed MSK cluster with a single broker node (for simplicity), configured with logging enabled and pointing to the S3 bucket.

The configuration uses default values for variables where appropriate and ensures that all resources are fully declared and deployable with Terraform 1.9.8 and the AWS provider 5.75.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-east-1"
}

# Create an S3 bucket for MSK logs
resource "aws_s3_bucket" "msk_logs" {
  bucket = "msk-logs-${random_string.bucket_suffix.result}"
  acl    = "private"

  tags = {
    Name = "msk-logs-bucket"
  }
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}

# Create an IAM role for MSK logging
resource "aws_iam_role" "msk_logging_role" {
  name = "msk-logging-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "kafka.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

# Create an IAM policy for S3 logging access
resource "aws_iam_policy" "msk_s3_logging_policy" {
  name        = "msk-s3-logging-policy"
  description = "Allows MSK to write logs to S3"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "s3:PutObject",
        "s3:GetObject",
        "s3:ListBucket"
      ]
      Resource = [
        aws_s3_bucket.msk_logs.arn,
        "${aws_s3_bucket.msk_logs.arn}/*"
      ]
    }]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "msk_s3_logging_attachment" {
  role       = aws_iam_role.msk_logging_role.name
  policy_arn = aws_iam_policy.msk_s3_logging_policy.arn
}

# Create the MSK cluster
resource "aws_msk_cluster" "example" {
  cluster_name           = "msk-cluster-example"
  kafka_version        = "3.3"
  number_of_brokers    = 1
  broker_node_group_info {
    instance_type = "kafka.m5.large"
    client_subnets  = ["us-east-1a", "us-east-1b"]
    security_groups = [aws_security_group.msk_sg.id]
    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled = false
      }
      firehose {
        enabled = false
      }
      s3 {
        enabled = true
        bucket = aws_s3_bucket.msk_logs.bucket
        prefix = "msk-logs/"
      }
    }
  }

  encryption_info {
    encryption_in_transit {
      client_broker = "TLS"
    }
  }

  zookeeper_connectivity {
    vpc_connectivity {}
  }

  open_monitoring {
    prometheus {
      jmx_exporter_enabled = true
    }
  }

  tags = {
    Environment = "dev"
  }
}

# Create a security group for MSK
resource "aws_security_group" "msk_sg" {
  name        = "msk-sg"
  description = "Security group for MSK cluster"
  vpc_id      = aws_vpc.default.id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "msk-sg"
  }
}

# Create a default VPC (if not already present)
resource "aws_vpc" "default" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "default-vpc"
  }
}
```

---

**Note:** This configuration assumes that the default VPC is not already present. If you are using an existing VPC, replace `aws_vpc.default.id` with the ID of your existing VPC. Also, ensure that the subnets used in `client_subnets` exist in your VPC.

