**Description of the Terraform Program:**

This Terraform configuration will create a managed Amazon MSK (Managed Streaming for Apache Kafka) cluster in the `us-east-1` region. The MSK cluster will be configured to log its data to an Amazon Kinesis Firehose delivery stream. The Firehose will be set up to deliver logs to an Amazon S3 bucket. The configuration includes:

- An AWS MSK cluster with a single broker node (for simplicity).
- A Kinesis Firehose delivery stream that sends logs to an S3 bucket.
- An IAM role for the MSK cluster to allow logging to Firehose.
- An IAM role for the Firehose delivery stream to write logs to S3.
- An S3 bucket to store the logs.

All resources are defined with default values and are deployable with Terraform 1.9.8 and the AWS provider version 5.75.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

# S3 bucket for storing logs
resource "aws_s3_bucket" "msk_logs" {
  bucket = "msk-logs-${random_string.suffix.result}"
  acl    = "private"

  tags = {
    Name = "msk-logs-bucket"
  }
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}

# IAM role for MSK to write logs to Firehose
resource "aws_iam_role" "msk_firehose_role" {
  name = "msk-firehose-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "kafka.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "msk_firehose_role_firehose" {
  role       = aws_iam_role.msk_firehose_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonKinesisFirehoseFullAccess"
}

# Kinesis Firehose delivery stream
resource "aws_kinesis_firehose_delivery_stream" "msk_logs_firehose" {
  name        = "msk-logs-firehose"
  destination = "s3"

  s3_destination_configuration {
    role_arn       = aws_iam_role.msk_firehose_role.arn
    bucket_arn     = aws_s3_bucket.msk_logs.arn
    prefix         = "msk-logs/"
    error_output_prefix = "msk-logs/error/"
  }

  tags = {
    Name = "msk-logs-firehose"
  }
}

# MSK cluster
resource "aws_msk_cluster" "example" {
  cluster_name           = "msk-cluster"
  kafka_version        = "3.3"
  number_of_broker_nodes = 1
  broker_node_group_info {
    instance_type = "kafka.m5.large"
    client_subnets = ["us-east-1a", "us-east-1b"]
    security_groups = [aws_security_group.msk_sg.id]
    storage_volume_size = 100
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled = true
      }
      firehose {
        delivery_stream = aws_kinesis_firehose_delivery_stream.msk_logs_firehose.name
        enabled         = true
      }
    }
  }

  tags = {
    Name = "msk-cluster"
  }
}

# Security group for MSK
resource "aws_security_group" "msk_sg" {
  name        = "msk-sg"
  description = "Security group for MSK cluster"
  vpc_id      = "vpc-12345678" # Replace with your actual VPC ID

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "msk-sg"
  }
}
```

---

**Note:** Replace `"vpc-12345678"` with the actual VPC ID in your AWS account. This configuration assumes that the VPC and subnets are already created. If not, you may need to add additional resources to create a VPC and subnets. Let me know if you'd like that included as well.

