LLM Output #0:
**Description of the Terraform Program:**

This Terraform configuration creates a managed Amazon MSK (Managed Streaming for Apache Kafka) cluster with encryption at rest enabled. The configuration includes:

- A dedicated VPC with public and private subnets.
- An Internet Gateway for public access.
- A security group to control access to the MSK cluster.
- An IAM role for MSK to allow it to interact with AWS services.
- A managed MSK cluster with encryption at rest using AWS KMS.
- A default KMS key is used for encryption if none is specified.

The configuration is designed to be deployed in the `us-east-1` region and uses default values for variables where applicable.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnets" {
  description = "List of CIDR blocks for public subnets"
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnets" {
  description = "List of CIDR blocks for private subnets"
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "msk_cluster_name" {
  description = "Name of the MSK cluster"
  default     = "msk-cluster"
}

variable "kafka_version" {
  description = "Kafka version for the MSK cluster"
  default     = "3.3"
}

variable "number_of_brokers" {
  description = "Number of brokers in the MSK cluster"
  default     = 3
}

variable "broker_node_group" {
  description = "Broker node group configuration"
  default = {
    instance_type = "kafka.m5.large"
    ebs_volume_size = 100
    client_authentication = "TLS"
    encryption_in_transit = "TLS"
  }
}

resource "aws_vpc" "msk_vpc" {
  cidr_block = var.vpc_cidr
  tags = {
    Name = "msk-vpc"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.msk_vpc.id
  tags = {
    Name = "msk-igw"
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnets)
  vpc_id = aws_vpc.msk_vpc.id
  cidr_block = var.public_subnets[count.index]
  map_public_ip_on_launch = true
  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnets)
  vpc_id = aws_vpc.msk_vpc.id
  cidr_block = var.private_subnets[count.index]
  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

resource "aws_security_group" "msk_sg" {
  name        = "msk-sg"
  description = "Security group for MSK cluster"
  vpc_id      = aws_vpc.msk_vpc.id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0/0"]
  }

  tags = {
    Name = "msk-sg"
  }
}

resource "aws_iam_role" "msk_role" {
  name = "msk-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "kafka.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "msk_kms" {
  role       = aws_iam_role.msk_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSKeyManagementServicePowerUser"
}

resource "aws_kms_key" "msk_encryption_key" {
  description = "KMS key for MSK encryption at rest"
  enable_key_rotation = true
  tags = {
    Name = "msk-encryption-key"
  }
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = var.msk_cluster_name
  kafka_version          = var.kafka_version
  number_of_brokers      = var.number_of_brokers
  broker_node_group {
    instance_type = var.broker_node_group.instance_type
    ebs_volume_size = var.broker_node_group.ebs_volume_size
    client_authentication = var.broker_node_group.client_authentication
    encryption_in_transit = var.broker_node_group.encryption_in_transit
  }
  encryption_info {
    encryption_at_rest {
      data_volume_kms_key_id = aws_kms_key.msk_encryption_key.arn
    }
  }
  vpc_config {
    vpc_id = aws_vpc.msk_vpc.id
    security_groups = [aws_security_group.msk_sg.id]
    subnets = [
      aws_subnet.public[0].id,
      aws_subnet.public[1].id,
      aws_subnet.private[0].id,
      aws_subnet.private[1].id,
    ]
  }
  tags = {
    Name = var.msk_cluster_name
  }
}
```

