**Description of the Terraform Program:**

This Terraform configuration creates a serverless Apache Kafka cluster using Amazon Managed Streaming for Apache Kafka (MSK) with 3 broker nodes. The configuration includes the MSK cluster, a VPC with public and private subnets, an internet gateway, and a route table to ensure the cluster is accessible. It also creates an IAM role for the MSK cluster and sets up a default security group to allow necessary traffic. The configuration uses default values for variables where applicable and ensures the provider is configured for the `us-east-1` region.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "msk_cluster_name" {
  description = "Name of the MSK cluster"
  default     = "serverless-msk-cluster"
}

variable "number_of_brokers" {
  description = "Number of broker nodes"
  default     = 3
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet"
  default     = "10.0.1.0/24"
}

variable "private_subnet_cidr" {
  description = "CIDR block for the private subnet"
  default     = "10.0.2.0/24"
}

resource "aws_vpc" "msk_vpc" {
  cidr_block = var.vpc_cidr
  tags = {
    Name = "msk-vpc"
  }
}

resource "aws_internet_gateway" "msk_igw" {
  vpc_id = aws_vpc.msk_vpc.id
  tags = {
    Name = "msk-igw"
  }
}

resource "aws_subnet" "public_subnet" {
  vpc_id            = aws_vpc.msk_vpc.id
  cidr_block        = var.public_subnet_cidr
  map_public_ip_on_launch = true
  availability_zone = "us-east-1a"
  tags = {
    Name = "msk-public-subnet"
  }
}

resource "aws_subnet" "private_subnet" {
  vpc_id            = aws_vpc.msk_vpc.id
  cidr_block        = var.private_subnet_cidr
  availability_zone = "us-east-1a"
  tags = {
    Name = "msk-private-subnet"
  }
}

resource "aws_route_table" "public_route_table" {
  vpc_id = aws_vpc.msk_vpc.id
  tags = {
    Name = "msk-public-route-table"
  }
}

resource "aws_route_table_association" "public_subnet_association" {
  subnet_id      = aws_subnet.public_subnet.id
  route_table_id = aws_route_table.public_route_table.id
}

resource "aws_route" "internet_gateway_route" {
  route_table_id         = aws_route_table.public_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.msk_igw.id
}

resource "aws_security_group" "msk_security_group" {
  name        = "msk-sg"
  description = "Security group for MSK cluster"
  vpc_id      = aws_vpc.msk_vpc.id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "msk-sg"
  }
}

resource "aws_iam_role" "msk_role" {
  name = "msk-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "kafka.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "msk_kafka_access" {
  role       = aws_iam_role.msk_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSKafkaFullAccess"
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = var.msk_cluster_name
  kafka_version        = "3.3"
  number_of_broker_nodes = var.number_of_brokers
  broker_node_group_info {
    instance_type = "kafka.m5.large"
    client_subnets = [
      aws_subnet.public_subnet.id,
      aws_subnet.private_subnet.id
    ]
    security_groups = [aws_security_group.msk_security_group.id]
    storage_info {
      volume_size = 100
    }
  }
  encryption_info {
    encryption_in_transit {
      in_cluster = true
      client_broker = "TLS"
    }
  }
  zookeeper_connectivity {
    vpc_connectivity {}
  }
  kafka_connectivity {
    vpc_connectivity {}
  }
  tags = {
    Name = var.msk_cluster_name
  }
}
