  }
  zookeeper_node_group_info {
    instance_type      = "kafka.m5.large"
    client_subnets     = ["subnet-12345678", "subnet-87654321", "subnet-11223344"]
    security_groups    = ["sg-12345678"]
  }
  encryption_in_transit {
    client_broker = "TLS"
    inter_broker = "TLS"
  }
  logging {
    broker_logs {
      access_logs = true
      audit_logs  = true
      error_logs  = true
    }
  }
  tags = {
    Environment = "dev"
  }
}

resource "aws_iam_role" "msk_role" {
  name = "msk-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "msk.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "msk_kafka" {
  role       = aws_iam_role.msk_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWS_MSK_FullAccess"
}

resource "aws_kafka_topic" "example" {
  name           = "example-topic"
  kafka_cluster {
    cluster_arn = aws_msk_cluster.example.arn
    topic_arn   = aws_kafka_topic.example.arn
  }
  partitions = 1
  replication_factor = 3
}
```

---

**Notes:**

- Replace the `client_subnets`, `security_groups`, and other placeholder values with actual values from your AWS environment.
- The `aws_kafka_topic` resource is optional and can be omitted if you do not need to create a topic immediately.
- Ensure that the AWS provider version is set to `~> 5.75` and Terraform version is `~> 1.9.8` for compatibility.

