**Description of the Terraform Program:**

This Terraform configuration will create an Amazon Managed Streaming for Apache Kafka (MSK) cluster with 3 broker nodes. The MSK cluster will be configured with encryption at rest, open monitoring enabled, and will have logging configured to output to a CloudWatch log group, an S3 bucket, and a Kinesis Firehose delivery stream. The configuration includes the necessary IAM roles and policies to ensure proper permissions for logging and data delivery.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create an S3 bucket for MSK logs
resource "aws_s3_bucket" "msk_logs_bucket" {
  bucket = "msk-logs-bucket-${random_string.suffix.result}"
  acl    = "private"

  tags = {
    Name = "MSKLogsBucket"
  }
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}

# Create a CloudWatch log group for MSK
resource "aws_cloudwatch_log_group" "msk_logs" {
  name = "/aws/msk/logs"
}

# Create a Kinesis Firehose delivery stream
resource "aws_kinesis_firehose_delivery_stream" "msk_firehose" {
  name        = "msk-firehose-${random_string.suffix.result}"
  destination = "s3"

  s3_destination_configuration {
    role_arn       = aws_iam_role.firehose_role.arn
    bucket_arn     = aws_s3_bucket.msk_logs_bucket.arn
    prefix         = "firehose-logs/"
    error_output_prefix = "firehose-errors/"
  }

  tags = {
    Name = "MSKFirehoseStream"
  }
}

# Create an IAM role for Kinesis Firehose
resource "aws_iam_role" "firehose_role" {
  name = "firehose-role-${random_string.suffix.result}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "firehose.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "firehose_s3" {
  role       = aws_iam_role.firehose_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3FullAccess"
}

# Create an IAM role for MSK
resource "aws_iam_role" "msk_role" {
  name = "msk-role-${random_string.suffix.result}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "kafka.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "msk_s3" {
  role       = aws_iam_role.msk_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3FullAccess"
}

resource "aws_iam_role_policy_attachment" "msk_cloudwatch" {
  role       = aws_iam_role.msk_role.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchFullAccess"
}

resource "aws_iam_role_policy_attachment" "msk_firehose" {
  role       = aws_iam_role.msk_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonKinesisFirehoseFullAccess"
}

# Create the MSK cluster
resource "aws_msk_cluster" "example" {
  cluster_name           = "msk-cluster-${random_string.suffix.result}"
  kafka_version        = "3.3"
  number_of_broker_nodes = 3
  broker_node_group_info {
    instance_type = "kafka.m5.large"
    client_subnets = ["subnet-12345678", "subnet-87654321", "subnet-11223344"]
    security_groups = ["sg-12345678"]
    storage_info {
      encryption_in_transit {
        in_broker = true
      }
      encryption_at_rest {
        data_volume_kms_key_id = aws_kms_key.msk_key.arn
      }
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled = true
        log_group = aws_cloudwatch_log_group.msk_logs.name
      }
      s3 {
        enabled = true
        bucket = aws_s3_bucket.msk_logs_bucket.bucket
        prefix = "msk-logs/"
      }
      firehose {
        enabled = true
        delivery_stream = aws_kinesis_firehose_delivery_stream.msk_firehose.name
      }
    }
  }

  open_monitoring {
    prometheus {
      jmx_exporter_enabled = true
    }
  }

  encryption_info {
    encryption_in_transit {
      client_broker = "TLS"
    }
    encryption_at_rest {
      data_volume_kms_key_id = aws_kms_key.msk_key.arn
    }
  }

  tags = {
    Environment = "dev"
  }
}

# Create a KMS key for encryption at rest
resource "aws_kms_key" "msk_key" {
  description             = "MSK encryption at rest key"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}
```

---

**Notes:**

- Replace the `client_subnets`, `security_groups`, and other placeholder values with actual values from your AWS environment.
- Ensure that the AWS region (`us-west-2`) matches your deployment needs.
- The KMS key is used for encryption at rest for the MSK cluster.
- The MSK cluster is configured with open monitoring (Prometheus) and logging to CloudWatch, S3, and Kinesis Firehose.

