**Description of the Terraform Program:**

This Terraform configuration creates an Amazon Aurora PostgreSQL cluster using the AWS provider. The configuration includes:

- A VPC with a public and private subnet.
- An internet gateway for the public subnet.
- A route table for the public subnet.
- A security group to allow PostgreSQL traffic.
- An RDS cluster with a master username and password.
- An RDS cluster instance.
- A database parameter group for PostgreSQL customization.
- A database subnet group to define the subnets for the Aurora cluster.

The configuration uses default values for variables where possible and ensures that the provider is configured with a valid region.

---

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet"
  default     = "10.0.1.0/24"
}

variable "private_subnet_cidr" {
  description = "CIDR block for the private subnet"
  default     = "10.0.2.0/24"
}

variable "db_name" {
  description = "Name of the Aurora PostgreSQL database"
  default     = "mydb"
}

variable "db_username" {
  description = "Username for the Aurora PostgreSQL database"
  default     = "admin"
}

variable "db_password" {
  description = "Password for the Aurora PostgreSQL database"
  default     = "SecureP@ssw0rd"
}

variable "db_instance_class" {
  description = "Instance class for the Aurora PostgreSQL cluster"
  default     = "db.t3.medium"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  tags = {
    Name = "AuroraVPC"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "AuroraIGW"
  }
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.public_subnet_cidr
  map_public_ip_on_launch = true
  availability_zone = "us-west-2a"
  tags = {
    Name = "AuroraPublicSubnet"
  }
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidr
  availability_zone = "us-west-2a"
  tags = {
    Name = "AuroraPrivateSubnet"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "AuroraPublicRouteTable"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route" "internet_gateway" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_security_group" "db" {
  name        = "AuroraDBSecurityGroup"
  description = "Allow PostgreSQL traffic"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "AuroraDBSecurityGroup"
  }
}

resource "aws_db_subnet_group" "aurora" {
  name       = "aurora-subnet-group"
  subnet_ids = [aws_subnet.private.id]
  tags = {
    Name = "AuroraSubnetGroup"
  }
}

resource "aws_db_parameter_group" "aurora" {
  name        = "aurora-parameter-group"
  family      = "aurora-postgresql14"
  description = "Aurora PostgreSQL parameter group"
  parameters  = {
    log_statement = "all"
  }
  tags = {
    Name = "AuroraParameterGroup"
  }
}

resource "aws_rds_cluster" "aurora" {
  cluster_identifier      = "aurora-cluster"
  engine                  = "aurora-postgresql"
  engine_version          = "14.4"
  database_name           = var.db_name
  master_username         = var.db_username
  master_user_password    = var.db_password
  db_subnet_group_name    = aws_db_subnet_group.aurora.name
  vpc_security_group_ids  = [aws_security_group.db.id]
  backup_retention_period = 5
  preferred_backup_window = "07:00-09:00"
  parameter_group_name    = aws_db_parameter_group.aurora.name
  tags = {
    Name = "AuroraCluster"
  }
}

resource "aws_rds_cluster_instance" "aurora" {
  cluster_identifier      = aws_rds_cluster.aurora.id
  instance_class          = var.db_instance_class
  engine                  = "aurora-postgresql"
  engine_version          = "14.4"
  db_subnet_group_name    = aws_db_subnet_group.aurora.name
  vpc_security_group_ids  = [aws_security_group.db.id]
  tags = {
    Name = "AuroraInstance"
  }
}
