    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "mydb-sg"
  }
}

resource "aws_iam_role" "rds_role" {
  name = "mydb-rds-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "rds.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "rds_role" {
  role       = aws_iam_role.rds_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonRDSFullAccess"
}

resource "aws_db_subnet_group" "mydb_subnet_group" {
  name       = "mydb-subnet-group"
  subnet_ids = [aws_subnet.az1.id, aws_subnet.az2.id, aws_subnet.az3.id]
  tags = {
    Name = "mydb-subnet-group"
  }
}

resource "aws_db_instance" "mydb" {
  identifier             = "mydb-instance"
  engine                 = "mysql"
  engine_version         = "8.0.33"
  instance_class         = var.db_instance_class
  allocated_storage      = var.db_allocated_storage
  db_name                = var.db_name
  username               = var.db_username
  password               = var.db_password
  db_subnet_group_name   = aws_db_subnet_group.mydb_subnet_group.name
  vpc_security_group_ids = [aws_security_group.db.id]
  skip_final_snapshot    = true
  availability_zone      = "us-east-1a"
  tags = {
    Name = "mydb-instance"
  }
}

resource "aws_db_instance" "mydb_replica1" {
  identifier             = "mydb-replica1"
  engine                 = "mysql"
  engine_version         = "8.0.33"
  instance_class         = var.db_instance_class
  allocated_storage      = var.db_allocated_storage
  db_name                = var.db_name
  username               = var.db_username
  password               = var.db_password
  db_subnet_group_name   = aws_db_subnet_group.mydb_subnet_group.name
  vpc_security_group_ids = [aws_security_group.db.id]
  skip_final_snapshot    = true
  availability_zone      = "us-east-1b"
  tags = {
    Name = "mydb-replica1"
  }
}

resource "aws_db_instance" "mydb_replica2" {
  identifier             = "mydb-replica2"
  engine                 = "mysql"
  engine_version         = "8.0.33"
  instance_class         = var.db_instance_class
  allocated_storage      = var.db_allocated_storage
