**Description of the Terraform Program:**

This Terraform configuration will create two AWS Chime Voice Connectors, each with encryption enabled. The Voice Connectors will be grouped together using a Chime Voice Connector Group. The configuration includes the necessary provider setup, IAM roles for Chime, and ensures that all resources are fully declared and deployable with Terraform 1.9.8 and the AWS provider version 5.75.

---

**Terraform HCL Code:**

```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM Role for Chime Voice Connectors
resource "aws_iam_role" "chime_voice_connector_role" {
  name = "chime-voice-connector-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "chime.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "chime_voice_connector" {
  role       = aws_iam_role.chime_voice_connector_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonChimeVoiceConnectorFullAccess"
}

# First Chime Voice Connector
resource "aws_chime_voice_connector" "vc1" {
  name                = "vc1"
  outbound_calling_name = "vc1-outbound"
  require_encryption  = true
  role_arn            = aws_iam_role.chime_voice_connector_role.arn
}

# Second Chime Voice Connector
resource "aws_chime_voice_connector" "vc2" {
  name                = "vc2"
  outbound_calling_name = "vc2-outbound"
  require_encryption  = true
  role_arn            = aws_iam_role.chime_voice_connector_role.arn
}

# Chime Voice Connector Group
resource "aws_chime_voice_connector_group" "vc_group" {
  name = "vc-group"

  voice_connector_items {
    voice_connector_id = aws_chime_voice_connector.vc1.id
    priority           = 1
  }

  voice_connector_items {
    voice_connector_id = aws_chime_voice_connector.vc2.id
    priority           = 2
  }
}
```

---

This configuration will deploy two encrypted AWS Chime Voice Connectors and group them in a single Voice Connector Group, ready for use in a Chime Voice routing setup.

