**Description of the Terraform Program:**

This Terraform configuration will create an AWS Chime Voice Connector and set up a configuration to stream media to Amazon Kinesis. The Voice Connector will be configured with a media streaming endpoint that directs media traffic to a Kinesis Data Streams stream. The configuration includes necessary IAM roles and policies to ensure proper permissions for the Chime Voice Connector to interact with Kinesis.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-east-1"
}

# Create an IAM role for the Chime Voice Connector
resource "aws_iam_role" "chime_voice_connector_role" {
  name = "chime-voice-connector-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "chime.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

# Attach the necessary policy to the IAM role
resource "aws_iam_role_policy_attachment" "kinesis_access" {
  role       = aws_iam_role.chime_voice_connector_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSKinesisFullAccess"
}

# Create a Kinesis Data Stream
resource "aws_kinesis_stream" "media_stream" {
  name             = "chime-media-stream"
  shard_count      = 1
  retention_period = 24
}

# Create the Chime Voice Connector
resource "aws_chime_voice_connector" "main" {
  name                  = "chime-voice-connector"
  outbound_calling_name = "MyVoiceConnector"
  require_encryption    = true
  enable_logging        = true
  logging_configuration {
    enable_s3_backup = true
    s3_backup_bucket = aws_s3_bucket.chime_logs.bucket
    s3_backup_prefix = "chime-logs"
  }
  media_streaming_configuration {
    media_streaming_type = "kinesis"
    kinesis_config {
      stream_arn = aws_kinesis_stream.media_stream.arn
    }
  }
  role_arn = aws_iam_role.chime_voice_connector_role.arn
}

# Create an S3 bucket for logging (optional, but required for logging in Chime)
resource "aws_s3_bucket" "chime_logs" {
  bucket = "chime-logs-bucket"
  acl    = "private"
}
```

---

**Notes:**

- This configuration assumes that you are using the `us-east-1` region, which is required for Chime Voice Connectors.
- The IAM role allows the Chime Voice Connector to access Kinesis and S3 for logging.
- The Kinesis stream is created with one shard and a 24-hour retention period.
- The Chime Voice Connector is configured to stream media to the Kinesis stream.
- An S3 bucket is created to store logs if logging is enabled.

