This Terraform configuration creates an AWS VPC with two subnets (one in each of two availability zones). It then groups these subnets into an AWS Redshift subnet group. Using this subnet group, a basic Redshift cluster is created, and an endpoint access is configured to allow secure access to the cluster.

The configuration includes:
- A VPC with a CIDR block.
- Two private subnets in different availability zones.
- A Redshift subnet group referencing the subnets.
- A Redshift cluster using the subnet group.
- A Redshift endpoint access (classic) to allow access to the cluster.

---

**Terraform HCL Code:**

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "example_vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "example-vpc"
  }
}

resource "aws_subnet" "private_subnet_1" {
  vpc_id            = aws_vpc.example_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  map_public_ip_on_launch = false
  tags = {
    Name = "private-subnet-1"
  }
}

resource "aws_subnet" "private_subnet_2" {
  vpc_id            = aws_vpc.example_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
  map_public_ip_on_launch = false
  tags = {
    Name = "private-subnet-2"
  }
}

resource "aws_redshift_subnet_group" "example_subnet_group" {
  name = "example-redshift-subnet-group"
  subnet_ids = [
    aws_subnet.private_subnet_1.id,
    aws_subnet.private_subnet_2.id,
  ]
  description = "Subnet group for Redshift cluster"
}

resource "aws_redshift_cluster" "example_cluster" {
  cluster_identifier = "example-redshift-cluster"
  database_name      = "exampledb"
  master_username    = "admin"
  master_password    = "SecurePassword123!"
  node_type          = "dc2.large"
  cluster_type       = "single-node"
  skip_final_snapshot = true
  subnet_ids         = aws_redshift_subnet_group.example_subnet_group.subnet_ids
  tags = {
    Name = "example-redshift-cluster"
  }
}

resource "aws_redshift_endpoint_access" "example_endpoint" {
  cluster_identifier = aws_redshift_cluster.example_cluster.id
  db_name            = aws_redshift_cluster.example_cluster.database_name
  endpoint_name      = "example-redshift-endpoint"
  resource_policy    = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": "*",
      "Action": "redshift:Connect",
      "Resource": "arn:aws:redshift:${aws_region}:${aws_caller_identity.account_id}:cluster:${aws_redshift_cluster.example_cluster.cluster_identifier}"
    }
  ]
}
EOF
  vpc_id             = aws_vpc.example_vpc.id
  tags = {
    Name = "example-redshift-endpoint"
  }
}
```

