**Description of the Terraform Program:**

This Terraform configuration creates an AWS Redshift cluster and configures it to be accessible from two subnets within a VPC. It provisions a VPC with two private subnets, a Redshift cluster, and a security group that allows access to the Redshift cluster from those subnets. The Redshift cluster is configured with a default database and user, and the necessary IAM roles are created to allow Redshift to interact with other AWS services if needed.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a VPC
resource "aws_vpc" "redshift_vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "redshift-vpc"
  }
}

# Create two private subnets
resource "aws_subnet" "redshift_subnet1" {
  vpc_id            = aws_vpc.redshift_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  map_public_ip_on_launch = false
  tags = {
    Name = "redshift-subnet1"
  }
}

resource "aws_subnet" "redshift_subnet2" {
  vpc_id            = aws_vpc.redshift_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
  map_public_ip_on_launch = false
  tags = {
    Name = "redshift-subnet2"
  }
}

# Create an internet gateway (optional, not used for private subnets)
resource "aws_internet_gateway" "redshift_igw" {
  vpc_id = aws_vpc.redshift_vpc.id
  tags = {
    Name = "redshift-igw"
  }
}

# Create a route table for the VPC
resource "aws_route_table" "redshift_route_table" {
  vpc_id = aws_vpc.redshift_vpc.id
  tags = {
    Name = "redshift-route-table"
  }
}

# Associate subnets with the route table
resource "aws_route_table_association" "redshift_subnet1_assoc" {
  subnet_id      = aws_subnet.redshift_subnet1.id
  route_table_id = aws_route_table.redshift_route_table.id
}

resource "aws_route_table_association" "redshift_subnet2_assoc" {
  subnet_id      = aws_subnet.redshift_subnet2.id
  route_table_id = aws_route_table.redshift_route_table.id
}

# Create a security group to allow access to Redshift
resource "aws_security_group" "redshift_sg" {
  name        = "redshift-sg"
  description = "Allow access to Redshift cluster from subnets"
  vpc_id      = aws_vpc.redshift_vpc.id

  ingress {
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [aws_subnet.redshift_subnet1.cidr_block, aws_subnet.redshift_subnet2.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "redshift-sg"
  }
}

# Create an IAM role for Redshift
resource "aws_iam_role" "redshift_role" {
  name = "redshift-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "redshift.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

# Attach the AmazonRedshiftReadOnlyAccess policy to the role
resource "aws_iam_role_policy_attachment" "redshift_default" {
  role       = aws_iam_role.redshift_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonRedshiftReadOnlyAccess"
}

# Create the Redshift cluster
resource "aws_redshift_cluster" "redshift_cluster" {
  cluster_identifier = "redshift-cluster"
  database_name      = "mydb"
  master_username    = "admin"
  master_password    = "SecurePassword123!"
  node_type          = "dc2.large"
  cluster_type       = "single-node"
  skip_final_snapshot = true
  iam_roles          = [aws_iam_role.redshift_role.arn]
  subnet_ids         = [aws_subnet.redshift_subnet1.id, aws_subnet.redshift_subnet2.id]
  security_group_ids = [aws_security_group.redshift_sg.id]
}
```

---

This configuration is ready to be applied with `terraform apply` and will create a fully functional Redshift cluster with access from two private subnets. Make sure to replace the `master_password` with a secure password of your choice.

