**Description of the Terraform Program:**

This Terraform configuration creates an AWS Redshift cluster, an associated Redshift parameter group, and an event subscription that sends events related to the parameter group to an AWS SNS topic. The configuration includes the necessary AWS provider setup, IAM roles for Redshift, and ensures all resources are fully declared and deployable.

---

**Terraform HCL Code:**

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create an SNS topic to receive Redshift events
resource "aws_sns_topic" "redshift_events" {
  name = "redshift-parameter-group-events"
}

# Create an IAM role for Redshift
resource "aws_iam_role" "redshift_role" {
  name = "redshift-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "redshift.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

# Attach the AWS managed Redshift policies to the IAM role
resource "aws_iam_role_policy_attachment" "redshift_default" {
  role       = aws_iam_role.redshift_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonRedshiftReadOnlyAccess"
}

# Create a Redshift parameter group
resource "aws_redshift_parameter_group" "example" {
  name         = "redshift-param-group"
  family       = "redshift-1.0"
  description  = "Example Redshift parameter group"
  parameters {
    name  = "query_timeout"
    value = "60"
  }
}

# Create a Redshift cluster
resource "aws_redshift_cluster" "example" {
  cluster_identifier      = "redshift-cluster"
  database_name           = "exampledb"
  master_username         = "admin"
  master_password         = "SecurePassword123!"
  node_type               = "dc2.large"
  cluster_type            = "single-node"
  iam_roles               = [aws_iam_role.redshift_role.arn]
  parameter_group_name    = aws_redshift_parameter_group.example.name
  skip_final_snapshot     = true
}

# Create a Redshift event subscription
resource "aws_redshift_event_subscription" "example" {
  name             = "redshift-event-subscription"
  sns_topic_arn    = aws_sns_topic.redshift_events.arn
  source_type      = "parameter-group"
  source_ids       = [aws_redshift_parameter_group.example.name]
  event_categories = ["parameter-group"]
}
```

