**Description of the Terraform Program:**

This Terraform configuration creates two S3 buckets: one for general use and another to store server access logs. The configuration includes the necessary IAM policies and roles to allow the first bucket to write logs to the second bucket. The provider is configured for the AWS region `us-east-1`, and all resources are fully specified with default values for any variables used.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-east-1"
}

# Variable for the name of the main S3 bucket
variable "main_bucket_name" {
  description = "Name of the main S3 bucket"
  default     = "my-main-bucket"
}

# Variable for the name of the logging S3 bucket
variable "logging_bucket_name" {
  description = "Name of the S3 bucket to store server access logs"
  default     = "my-logging-bucket"
}

# Create the main S3 bucket
resource "aws_s3_bucket" "main" {
  bucket = var.main_bucket_name
  acl    = "private"

  # Enable server access logging
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  logging {
    target_bucket = aws_s3_bucket.logging.bucket
    target_prefix = "logs/"
  }
}

# Create the logging S3 bucket
resource "aws_s3_bucket" "logging" {
  bucket = var.logging_bucket_name
  acl    = "private"
}

# IAM policy to allow the main bucket to write logs to the logging bucket
resource "aws_iam_role" "s3_logging_role" {
  name = "s3-logging-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "s3.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "s3_logging" {
  role       = aws_iam_role.s3_logging_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3FullAccess"
}

# Attach the logging role to the main bucket
resource "aws_s3_bucket_ownership_controls" "main" {
  bucket = aws_s3_bucket.main.bucket
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_policy" "logging_policy" {
  bucket = aws_s3_bucket.logging.bucket

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { AWS = aws_iam_role.s3_logging_role.arn }
      Action = ["s3:PutObject", "s3:GetObject"]
      Resource = [
        "${aws_s3_bucket.logging.arn}/*",
        "${aws_s3_bucket.logging.arn}"
      ]
    }]
  })
}
```

---

This configuration is ready to be deployed with Terraform version `~> 1.9.8` and the AWS provider version `~> 5.75`. It ensures that the main bucket logs its server access logs to the logging bucket, and the necessary IAM permissions are in place to allow this.

