This Terraform configuration sets up an AWS CodeBuild project that will act as an autograder for a CS class. The project will pull code from a GitHub repository, execute the build process (which can include running tests or grading scripts), and store the results in an S3 bucket. The configuration includes:

- An AWS S3 bucket to store the build logs and results.
- An IAM role for CodeBuild with permissions to access the S3 bucket and GitHub.
- A CodeBuild project that is configured to use the GitHub repository and the IAM role.
- A GitHub OAuth token (as a Terraform variable) to allow CodeBuild to access the private GitHub repository.

The configuration is designed to be deployed in the `us-east-1` region and uses default values for variables where possible.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "github_token" {
  description = "GitHub personal access token for CodeBuild to access the repository"
  type        = string
  default     = "your_github_token_here"
}

variable "github_repo" {
  description = "GitHub repository in the format 'owner/repo'"
  type        = string
  default     = "cs-class/autograder"
}

variable "github_branch" {
  description = "Branch of the GitHub repository to build"
  type        = string
  default     = "main"
}

variable "s3_bucket_name" {
  description = "Name of the S3 bucket to store build logs and results"
  type        = string
  default     = "autograder-build-logs"
}

resource "aws_s3_bucket" "build_logs" {
  bucket = var.s3_bucket_name
  acl    = "private"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }
}

resource "aws_iam_role" "codebuild_role" {
  name = "codebuild-autograder-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "codebuild.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "codebuild_s3_access" {
