  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMReadOnlyAccess"
}

resource "aws_codebuild_project" "autograder" {
  name          = "autograder-project"
  description   = "CodeBuild project for autograding student submissions"
  source {
    type            = "GITHUB"
    location        = "https://github.com/${var.github_repo}.git"
    branch          = var.github_branch
    auth {
      type = "OAUTH"
      resource = "github.com"
    }
  }

  artifacts {
    type = "CODEPIPELINE"
  }

  environment {
    type                = "LINUX_CONTAINER"
