**Description of the Terraform Program:**

This Terraform configuration sets up the infrastructure for an autograder system for a CS class. It uses AWS S3 to store student code and grading results, and AWS CodeBuild to run the autograding process. The system includes:

- An S3 bucket to store student code and grading results.
- A CodeBuild project that triggers on new code commits to the S3 bucket.
- An IAM role for CodeBuild to access the S3 bucket and log results.
- A CloudWatch Logs group to store CodeBuild logs for debugging and monitoring.
- A CodeBuild buildspec file that defines the steps to run the autograder.

The configuration is designed to be self-contained and deployable with Terraform 1.9.8 and the AWS provider 5.75.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "student_code" {
  bucket = "cs-class-autograder-code-${random_string.suffix.result}"
  acl    = "private"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  tags = {
    Name = "StudentCodeBucket"
  }
}

resource "aws_s3_bucket" "grading_results" {
  bucket = "cs-class-autograder-results-${random_string.suffix.result}"
  acl    = "private"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  tags = {
    Name = "GradingResultsBucket"
  }
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}

resource "aws_iam_role" "codebuild_role" {
  name = "CodeBuildAutograderRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "codebuild.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "codebuild_s3_access" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess"
}

resource "aws_iam_role_policy_attachment" "codebuild_logs_access" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchLogsFullAccess"
}

resource "aws_codebuild_project" "autograder" {
  name          = "cs-class-autograder-${random_string.suffix.result}"
  description   = "Autograder for CS class assignments"
  source {
    type            = "S3"
    location        = aws_s3_bucket.student_code.bucket
    buildspec       = file("buildspec.yml")
    insecure_ssl  = false
  }

  artifacts {
    type = "S3"
    location = aws_s3_bucket.grading_results.bucket
  }

  environment {
    type                = "LINUX_CONTAINER"
    image               = "aws/codebuild/amazonlinux2-x86_64-standard:3.0"
    compute_type        = "BUILD_GENERAL1_SMALL"
    environment_variables = {
      GRADING_SCRIPT = "autograde.sh"
    }
  }

  service_role = aws_iam_role.codebuild_role.arn

  logs_config {
    cloudwatch_logs {
      status = "ENABLED"
    }
  }

  tags = {
    Name = "AutograderProject"
  }
}

resource "aws_cloudwatch_log_group" "codebuild_logs" {
  name = "/aws/codebuild/cs-class-autograder-${random_string.suffix.result}"
}
```

---

**Note:** You will need a `buildspec.yml` file in your working directory with the following content (or adjust it to match your grading logic):

```yaml
version: 0.2

phases:
  install:
    runtime-versions:
      python: 3.8
    commands:
      - echo "Installing dependencies..."
      - pip install -r requirements.txt
  build:
    commands:
      - echo "Running autograder..."
      - ./autograde.sh
artifacts:
  type: "s3"
  files:
    - "results/*.json"
  discard-paths: "yes"
```

This setup will allow you to store student code in the S3 bucket, trigger the CodeBuild project, and store the grading results in another S3 bucket.

