### Description of the Terraform Program

This Terraform configuration sets up an infrastructure for an autograder for a CS class using AWS CodeBuild and AWS VPC. The infrastructure includes:

- A **private VPC** with **private and public subnets** to isolate the autograder environment.
- A **private subnet** where the **CodeBuild project** will run, ensuring that the student code cannot reach the internet.
- A **NAT Gateway** in the public subnet to allow outbound internet access for the VPC (if needed for updates or dependencies).
- A **CodeBuild project** that pulls student code from a GitHub repository, runs it in an isolated environment, and stores the results in an **S3 bucket**.
- An **IAM role** for CodeBuild with permissions to access the GitHub repository and write to the S3 bucket.
- A **GitHub OAuth token** (as a variable) to allow CodeBuild to access the GitHub repository securely.
- A **private S3 bucket** to store the autograder results.

This setup ensures that the student code runs in a secure, isolated environment and cannot access the internet, preventing potential security risks.

---

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "github_oauth_token" {
  description = "GitHub OAuth token for CodeBuild to access the repository"
  type        = string
}

variable "github_repo" {
  description = "GitHub repository in the format 'owner/repo'"
  type        = string
  default     = "cs-class/autograde"
}

variable "github_branch" {
  description = "Branch of the GitHub repository to build"
  type        = string
  default     = "main"
}

variable "s3_bucket_name" {
  description = "Name of the S3 bucket to store autograder results"
  type        = string
  default     = "autograde-results-bucket"
}

resource "aws_vpc" "autograde_vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "autograde-vpc"
  }
}

resource "aws_subnet" "private_subnet" {
  vpc_id            = aws_vpc.autograde_vpc.id
  cidr_block        = "10.0.1.0/24"
  map_public_ip_on_launch = false
  availability_zone = "us-east-1a"
  tags = {
    Name = "autograde-private-subnet"
  }
}

resource "aws_subnet" "public_subnet" {
  vpc_id            = aws_vpc.autograde_vpc.id
  cidr_block        = "10.0.0.0/24"
  map_public_ip_on_launch = true
  availability_zone = "us-east-1a"
  tags = {
    Name = "autograde-public-subnet"
  }
}

resource "aws_internet_gateway" "autograde_igw" {
  vpc_id = aws_vpc.autograde_vpc.id
  tags = {
    Name = "autograde-igw"
  }
}

resource "aws_route_table" "public_route_table" {
  vpc_id = aws_vpc.autograde_vpc.id
  tags = {
    Name = "autograde-public-route-table"
  }
}

resource "aws_route_table_association" "public_subnet_association" {
  subnet_id      = aws_subnet.public_subnet.id
  route_table_id = aws_route_table.public_route_table.id
}

resource "aws_route" "internet_gateway_route" {
  route_table_id         = aws_route_table.public_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.autograde_igw.id
}

resource "aws_nat_gateway" "autograde_nat" {
  subnet_id = aws_subnet.public_subnet.id
  allocation_id = aws_eip.autograde_eip.id
  tags = {
    Name = "autograde-nat"
  }
}

resource "aws_eip" "autograde_eip" {
  tags = {
    Name = "autograde-eip"
  }
}

resource "aws_route_table" "private_route_table" {
  vpc_id = aws_vpc.autograde_vpc.id
  tags = {
    Name = "autograde-private-route-table"
  }
}

resource "aws_route_table_association" "private_subnet_association" {
  subnet_id      = aws_subnet.private_subnet.id
  route_table_id = aws_route_table.private_route_table.id
}

resource "aws_route" "nat_route" {
  route_table_id         = aws_route_table.private_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.autograde_nat.id
}

resource "aws_s3_bucket" "autograde_results" {
  bucket = var.s3_bucket_name
  acl    = "private"
  tags = {
    Name = "autograde-results"
  }
}

resource "aws_iam_role" "codebuild_role" {
  name = "autograde-codebuild-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "codebuild.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "codebuild_basic" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSCodeBuildAdminAccess"
}

resource "aws_iam_role_policy" "codebuild_github_access" {
  name = "codebuild-github-access"
  role = aws_iam_role.codebuild_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "github:Read",
        "github:Write"
      ]
      Resource = "arn:aws:github:::*"
    }]
  })
}

resource "aws_iam_role_policy" "codebuild_s3_access" {
  name = "codebuild-s3-access"
  role = aws_iam_role.codebuild_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "s3:PutObject",
        "s3:GetObject"
      ]
      Resource = "arn:aws:s3:::${var.s3_bucket_name}/*"
    }]
  })
}

resource "aws_codebuild_project" "autograde" {
  name          = "autograde-codebuild"
  description   = "Autograder for CS class"
  source {
    type            = "GITHUB"
    location        = "https://github.com/${var.github_repo}"
    branch          = var.github_branch
    auth = {
      type = "OAUTH"
      resource = "github.com"
      token = var.github_oauth_token
    }
  }
  environment {
    type                = "LINUX_CONTAINER"
    image               = "aws/codebuild/amazonlinux2-x86_64-standard:3.0"
    compute_type        = "BUILD_GENERAL1_SMALL"
    environment_variables = {
      GITHUB_OAUTH_TOKEN = var.github_oauth_token
    }
  }
  service_role = aws_iam_role.codebuild_role.arn
  artifacts {
    type = "S3"
    s3_location {
      bucket_name = aws_s3_bucket.autograde_results.bucket
      encryption_enabled = true
    }
  }
  tags = {
    Name = "autograde-codebuild"
  }
}
```

