### Description of the Terraform Program

This Terraform configuration sets up an infrastructure for an autograder for a CS class. The infrastructure includes:

- **AWS VPC**: A private VPC with a private subnet to isolate the autograder environment from the internet.
- **AWS S3**: An S3 bucket to store student code and autograding results.
- **AWS CodeBuild**: A CodeBuild project that runs the autograder in the isolated VPC environment.
- **IAM Roles**: Necessary IAM roles for CodeBuild to access S3 and run in the VPC.
- **Security Groups and Network ACLs**: Configured to prevent the CodeBuild instance from reaching the internet.
- **EC2 Instance (Optional)**: If needed, an EC2 instance can be used to run the autograder, but CodeBuild is used as the main execution environment.

The setup ensures that student code is executed in a secure, isolated environment and that results are stored in S3.

---

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# VPC and Subnet
resource "aws_vpc" "autograder_vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "autograder-vpc"
  }
}

resource "aws_subnet" "autograder_subnet" {
  vpc_id            = aws_vpc.autograder_vpc.id
  cidr_block        = "10.0.1.0/24"
  map_public_ip_on_launch = false
  availability_zone = "us-east-1a"
  tags = {
    Name = "autograder-subnet"
  }
}

resource "aws_internet_gateway" "autograder_igw" {
  vpc_id = aws_vpc.autograder_vpc.id
  tags = {
    Name = "autograder-igw"
  }
}

resource "aws_route_table" "autograder_route_table" {
  vpc_id = aws_vpc.autograder_vpc.id
  tags = {
    Name = "autograder-route-table"
  }
}

resource "aws_route_table_association" "autograder_subnet_association" {
  subnet_id      = aws_subnet.autograder_subnet.id
  route_table_id = aws_route_table.autograder_route_table.id
}

# Security Group to block internet access
resource "aws_security_group" "autograder_sg" {
  name        = "autograder-sg"
  description = "Block all internet access"
  vpc_id      = aws_vpc.autograder_vpc.id

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["10.0.0.0/16"]  # Allow internal VPC traffic
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["10.0.0.0/16"]  # Block internet access
  }

  tags = {
    Name = "autograder-sg"
  }
}

# S3 bucket for storing student code and results
resource "aws_s3_bucket" "autograder_bucket" {
  bucket = "autograder-student-code"
  acl    = "private"
  tags = {
    Name = "autograder-bucket"
  }

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }
}

# IAM role for CodeBuild
resource "aws_iam_role" "codebuild_role" {
  name = "autograder-codebuild-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "codebuild.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "codebuild_s3_access" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess"
}

resource "aws_iam_role_policy_attachment" "codebuild_vpc_access" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeBuildVpcAccess"
}

# CodeBuild project
resource "aws_codebuild_project" "autograder_project" {
  name          = "autograder-codebuild"
  description   = "Autograder for CS class"
  source {
    type                = "GITHUB"
    location            = "https://github.com/your-organization/autograder-code.git"
    branch              = "main"
    auth {
      type = "OAUTH"
    }
  }

  artifacts {
    type = "CODEPIPELINE"
  }

  environment {
    type                = "LINUX_CONTAINER"
    image               = "aws/codebuild/amazonlinux2-x86_64-standard:3.0"
    compute_type        = "BUILD_GENERAL1_SMALL"
    environment_variables = {
      S3_BUCKET = aws_s3_bucket.autograder_bucket.bucket
    }
    vpc_config {
      vpc_id      = aws_vpc.autograder_vpc.id
      subnets     = [aws_subnet.autograder_subnet.id]
      security_groups = [aws_security_group.autograder_sg.id]
    }
  }

  service_role = aws_iam_role.codebuild_role.arn

  tags = {
    Name = "autograder-codebuild"
  }
}
```

---

### Notes

- Replace `"https://github.com/your-organization/autograder-code.git"` with the actual GitHub repository URL for the autograder code.
- The CodeBuild environment is configured to run in the isolated VPC and cannot access the internet.
- The S3 bucket is used to store student code and grading results.
- The IAM role allows CodeBuild to access S3 and run in the VPC.

