**Description of the Terraform Program:**

This Terraform configuration sets up a secure infrastructure for an autograder used in a CS class. The infrastructure includes:

- An **AWS VPC** with a **private subnet** to isolate the autograder environment.
- A **Security Group** that restricts network access to prevent the autograder from reaching the internet.
- An **AWS S3 Bucket** to store the results of the autograding process.
- An **AWS CodeBuild Project** that pulls student code from a GitHub repository, runs it in an isolated environment, and stores the results in the S3 bucket.

The setup ensures that the students' code runs in a secure, isolated environment with no access to the internet, preventing potential security risks or unintended network behavior.

---

**Terraform HCL Code:**

```hcl
provider "aws" {
  region = "us-east-1"
}

# VPC for the autograder
resource "aws_vpc" "autograder_vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "autograder-vpc"
  }
}

# Private subnet for the autograder
resource "aws_subnet" "autograder_subnet" {
  vpc_id            = aws_vpc.autograder_vpc.id
  cidr_block        = "10.0.1.0/24"
  map_public_ip_on_launch = false
  availability_zone = "us-east-1a"
  tags = {
    Name = "autograder-subnet"
  }
}

# Security Group to isolate the autograder
resource "aws_security_group" "autograder_sg" {
  name        = "autograder-sg"
  description = "Security group for autograder to prevent internet access"
  vpc_id      = aws_vpc.autograder_vpc.id

  # Allow SSH access for debugging (optional, can be removed if not needed)
  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  # Deny all outbound traffic
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["127.0.0.1/32"]  # Only allow loopback
  }

  tags = {
    Name = "autograder-sg"
  }
}

# S3 bucket to store autograding results
resource "aws_s3_bucket" "autograder_results" {
  bucket = "autograder-results-${random_string.bucket_suffix.result}"
  acl    = "private"

  tags = {
    Name = "autograder-results"
  }

  # Enable versioning for better result management
  versioning {
    enabled = true
  }

  # Enable logging to track access
  logging {
    target_bucket = aws_s3_bucket.autograder_results.bucket
    target_prefix = "logs/"
  }
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}

# IAM role for CodeBuild to access S3
resource "aws_iam_role" "codebuild_role" {
  name = "autograder-codebuild-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "codebuild.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "codebuild_s3_access" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3FullAccess"
}

# CodeBuild project to run the autograder
resource "aws_codebuild_project" "autograder" {
  name          = "autograder-project"
  description   = "Autograder for CS class"
  source {
    type            = "GITHUB"
    location        = "https://github.com/your-organization/your-autograder-repo.git"
    branch          = "main"
    auth            = {
      type = "OAUTH"
    }
  }

  environment {
    type                = "LINUX_CONTAINER"
    image               = "aws/codebuild/amazonlinux2-x86_64-standard:3.0"
    compute_type        = "BUILD_GENERAL1_SMALL"
    environment_variables = {
      GITHUB_TOKEN = {
        type  = "PLAINTEXT"
        value = "your-github-token"  # Replace with a real GitHub token
      }
    }
  }

  service_role = aws_iam_role.codebuild_role.arn

  artifacts {
    type = "S3"
    s3_location {
      bucket_name = aws_s3_bucket.autograder_results.bucket
      path        = "results/"
    }
  }

  tags = {
    Name = "autograder-codebuild"
  }
}
```

---

**Notes:**

- Replace `"https://github.com/your-organization/your-autograder-repo.git"` with the actual GitHub repository URL.
- Replace `"your-github-token"` with a valid GitHub Personal Access Token (PAT) with `repo` scope.
- This setup assumes that the CodeBuild project will run the autograding logic from the GitHub repo. You may need to customize the buildspec.yml file in the repo accordingly.
- The Security Group blocks all outbound traffic except for the loopback interface, ensuring that the CodeBuild environment cannot reach the internet.

