**Description of the Terraform Program:**

This Terraform configuration creates the following AWS infrastructure:

1. An **S3 bucket** to store code build output.
2. A **VPC** with a CIDR block of `10.0.0.0/16`.
3. A **VPC subnet** with a CIDR block of `10.0.0.0/24`.
4. A **Security Group** associated with the VPC that blocks all internet ingress and egress traffic.
5. An **AWS CodeBuild project** that:
   - Uses the `S3` type for artifacts and points to the created S3 bucket.
   - Uses the `BUILD_GENERAL1_SMALL` computer type.
   - Uses the `alpine` image with `LINUX_CONTAINER` type.
   - Sources code from GitHub at `github.com/source-location` with a git clone depth of 1.
   - Is configured to use the created VPC and Security Group.

---

**Terraform HCL Code:**

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "codebuild_artifacts" {
  bucket = "codebuild-artifacts-bucket-12345"
  acl    = "private"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "main" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.0.0/24"
}

resource "aws_security_group" "no_internet_access" {
  name        = "no-internet-access"
  description = "Block all internet traffic"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["127.0.0.1/32"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["127.0.0.1/32"]
  }
}

resource "aws_codebuild_project" "codebuild_project" {
  name          = "codebuild-project"
  description   = "CodeBuild project for student code"
  artifacts {
    type = "S3"
    s3 {
      location = aws_s3_bucket.codebuild_artifacts.bucket
    }
  }

  environment {
    compute_type  = "BUILD_GENERAL1_SMALL"
    image         = "alpine"
    type          = "LINUX_CONTAINER"
  }

  source {
    type            = "GITHUB"
    git_clone_depth = 1
    location        = "github.com/source-location"
  }

  vpc_config {
    vpc_id      = aws_vpc.main.id
    subnets     = [aws_subnet.main.id]
    security_groups = [aws_security_group.no_internet_access.id]
  }
}
