    role_arn = "arn:aws:iam::590184057477:role/yicun-iac"
  }
}

resource "aws_dynamodb_table" "caas" {
  name           = "cat_names"
  hash_key       = "name"
  billing_mode   = "PAY_PER_REQUEST"

  attribute {
    name = "name"
    type = "S"
  }
}

resource "aws_s3_bucket" "caas" {
  bucket_prefix = "cat-image"
}

resource "aws_iam_role" "lambda_role" {
  name = "lambda_api_gateway_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "lambda_policy" {
  name   = "lambda_policy"
  role   = aws_iam_role.lambda_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Effect   = "Allow"
        Resource = "${aws_s3_bucket.caas.arn}/*"
      },
      {
        Action = [
          "dynamodb:PutItem"
        ]
        Effect   = "Allow"
        Resource = aws_dynamodb_table.caas.arn
      }
    ]
  })
}

resource "aws_api_gateway_rest_api" "caas" {
  name = "caas"
}

resource "aws_api_gateway_resource" "caas_cat" {
  rest_api_id = aws_api_gateway_rest_api.caas.id
  parent_id   = aws_api_gateway_rest_api.caas.root_resource_id
  path_part   = "cat"
}

resource "aws_api_gateway_method" "caas_cat_get" {
  rest_api_id   = aws_api_gateway_rest_api.caas.id
  resource_id   = aws_api_gateway_resource.caas_cat.id
  http_method   = "GET"
  authorization = "NONE"
}

resource "aws_api_gateway_method" "caas_cat_put" {
  rest_api_id   = aws_api_gateway_rest_api.caas.id
  resource_id   = aws_api_gateway_resource.caas_cat.id
  http_method   = "PUT"
  authorization = "NONE"
}

data "archive_file" "caas_cat" {
  type        = "zip"
  source_file = "./supplement/caas_cat.py"
  output_path = "./supplement/caas_cat.zip"
}

resource "aws_lambda_function" "caas_cat" {
  function_name = "caas_cat"
  role          = aws_iam_role.lambda_role.arn
  filename      = data.archive_file.caas_cat.output_path
  source_code_hash = data.archive_file.caas_cat.output_base64sha256
  handler       = "caas_cat.handler"
  runtime       = "python3.12"

  environment {
    variables = {
      CAAS_S3_BUCKET = "${aws_s3_bucket.caas.id}"
      DYNAMODB_TABLE_NAME = "${aws_dynamodb_table.caas.id}"
    }
  }
}

resource "aws_api_gateway_integration" "caas_cat_get" {
  rest_api_id             = aws_api_gateway_rest_api.caas.id
  resource_id             = aws_api_gateway_resource.caas_cat.id
  http_method             = aws_api_gateway_method.caas_cat_get.http_method
  type                    = "AWS_PROXY"
  integration_http_method = "GET"
  uri                     = aws_lambda_function.caas_cat.invoke_arn
}

resource "aws_api_gateway_integration" "caas_cat_put" {
  rest_api_id             = aws_api_gateway_rest_api.caas.id
  resource_id             = aws_api_gateway_resource.caas_cat.id
  http_method             = aws_api_gateway_method.caas_cat_put.http_method
  type                    = "AWS_PROXY"
  integration_http_method = "PUT"
  uri                     = aws_lambda_function.caas_cat.invoke_arn
}

resource "aws_lambda_permission" "caas_cat" {
  action        = "lambda:InvokeFunction"
  principal     = "apigateway.amazonaws.com"
  function_name = aws_lambda_function.caas_cat.function_name

  source_arn = "${aws_api_gateway_rest_api.caas.execution_arn}/*/*"
}

resource "aws_api_gateway_deployment" "api_deployment" {
  rest_api_id = aws_api_gateway_rest_api.caas.id
  depends_on  = [aws_api_gateway_integration.caas_cat_get, 
                 aws_api_gateway_integration.caas_cat_put]
}

resource "aws_api_gateway_stage" "api_stage" {
  deployment_id = aws_api_gateway_deployment.api_deployment.id
  rest_api_id   = aws_api_gateway_rest_api.caas.id
  stage_name    = "dev"
}

output "api_id" {
  value = aws_api_gateway_rest_api.caas.id
  description = "The API Gateway ID"
}

LLM Output #0:
**Description of the Terraform Program:**

This Terraform configuration sets up an AWS infrastructure that allows users to upload cat pictures and retrieve random cat pictures on demand. The architecture includes:

- An **S3 bucket** to store the uploaded cat pictures.
- An **IAM role and policy** to allow secure access to the S3 bucket for uploads and reads.
- An **API Gateway** (REST API) with two endpoints:
  - One for uploading cat pictures (POST method).
  - One for retrieving a random cat picture (GET method).
- A **Lambda function** (optional, but can be used for processing or validation) that could be integrated with API Gateway if needed.
- A **CloudFront distribution** (optional, for performance and caching of cat picture retrieval).
- A **CORS configuration** on the S3 bucket to allow web clients to upload and retrieve images.

The configuration is designed to be secure, scalable, and deployable with minimal effort.

---

**Terraform HCL Code:**

```hcl
provider "aws" {
  region = "us-east-1"
}

# Variables
variable "bucket_name" {
  default = "cat-picture-bucket-12345"
}

variable "api_name" {
  default = "CatPictureAPI"
}

# S3 Bucket for storing cat pictures
resource "aws_s3_bucket" "cat_pictures" {
  bucket = var.bucket_name
  acl    = "private"

  cors_rule {
    allowed_headers = ["*"]
    allowed_methods = ["GET", "PUT", "POST", "DELETE"]
    allowed_origins = ["*"]
    expose_headers  = ["ETag"]
    max_age_seconds = 3000
  }

  versioning {
    enabled = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

# IAM Policy for S3 access
resource "aws_iam_policy" "s3_access" {
  name        = "s3-access-policy"
  description = "Allows access to the cat picture S3 bucket"
  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.cat_pictures.arn,
          "${aws_s3_bucket.cat_pictures.arn}/*"
        ]
      }
    ]
  })
}

# IAM Role for API Gateway to access S3
resource "aws_iam_role" "api_gateway_s3_role" {
  name = "api-gateway-s3-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = { Service = "apigateway.amazonaws.com" }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "api_gateway_s3_attachment" {
  role       = aws_iam_role.api_gateway_s3_role.name
  policy_arn = aws_iam_policy.s3_access.arn
}

# API Gateway REST API
resource "aws_api_gateway_rest_api" "cat_picture_api" {
  name        = var.api_name
  description = "API for uploading and retrieving cat pictures"
  minimum_compression_size = 1024
}

# Root resource
resource "aws_api_gateway_resource" "root" {
  rest_api_id = aws_api_gateway_rest_api.cat_picture_api.id
  parent_id   = aws_api_gateway_rest_api.cat_picture_api.root_resource_id
  path_part   = "cat"
}

# Upload resource
resource "aws_api_gateway_resource" "upload" {
  rest_api_id = aws_api_gateway_rest_api.cat_picture_api.id
  parent_id   = aws_api_gateway_resource.root.id
  path_part   = "upload"
}

# Get random cat resource
resource "aws_api_gateway_resource" "get_random" {
  rest_api_id = aws_api_gateway_rest_api.cat_picture_api.id
  parent_id   = aws_api_gateway_resource.root.id
  path_part   = "random"
}

# Upload method (POST)
resource "aws_api_gateway_method" "upload_post" {
  rest_api_id   = aws_api_gateway_rest_api.cat_picture_api.id
  resource_id   = aws_api_gateway_resource.upload.id
  http_method   = "POST"
  authorization = "NONE"
}

# Get random method (GET)
resource "aws_api_gateway_method" "get_random_get" {
  rest_api_id   = aws_api_gateway_rest_api.cat_picture_api.id
  resource_id   = aws_api_gateway_resource.get_random.id
  http_method   = "GET"
  authorization = "NONE"
}

# Integration for upload method (S3 Put)
resource "aws_api_gateway_integration" "upload_integration" {
  rest_api_id = aws_api_gateway_rest_api.cat_picture_api.id
  resource_id = aws_api_gateway_resource.upload.id
  http_method = aws_api_gateway_method.upload_post.http_method
  type        = "AWS_PROXY"
  integration_http_method = "POST"
  uri         = aws_s3_bucket.cat_pictures.arn
  credentials = aws_iam_role.api_gateway_s3_role.arn
}

# Integration for get random method (S3 Get)
resource "aws_api_gateway_integration" "get_random_integration" {
  rest_api_id = aws_api_gateway_rest_api.cat_picture_api.id
  resource_id = aws_api_gateway_resource.get_random.id
  http_method = aws_api_gateway_method.get_random_get.http_method
  type        = "AWS_PROXY"
  integration_http_method = "GET"
  uri         = aws_s3_bucket.cat_pictures.arn
  credentials = aws_iam_role.api_gateway_s3_role.arn
}

# Deploy API Gateway
resource "aws_api_gateway_deployment" "cat_picture_deployment" {
  rest_api_id = aws_api_gateway_rest_api.cat_picture_api.id
  stage_name  = "prod"
  description = "Production deployment of Cat Picture API"
  depends_on  = [aws_api_gateway_integration.upload_integration, aws_api_gateway_integration.get_random_integration]
}
```

