**Description of the Terraform Program:**

This Terraform configuration provisions an EC2 instance in AWS and sets up an automated daily backup using AWS Backup. The backup is scheduled to run every day at midnight. The configuration includes:

- An AWS provider block with a specified region.
- A VPC and subnet for the EC2 instance.
- An IAM role for the EC2 instance with necessary permissions.
- The EC2 instance itself with a basic AMI and SSH access.
- An AWS Backup vault to store backups.
- A backup plan that schedules daily backups at midnight.
- A backup selection that includes the EC2 instance.

---

**Terraform HCL Code:**

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "main" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  map_public_ip_on_launch = true
  availability_zone = "us-west-2a"
  tags = {
    Name = "main-subnet"
  }
}

resource "aws_security_group" "allow_ssh" {
  name        = "allow-ssh"
  description = "Allow SSH access"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "allow-ssh"
  }
}

resource "aws_iam_role" "ec2_role" {
  name = "ec2-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "ec2.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "ec2_role_policy" {
  role       = aws_iam_role.ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_instance" "example" {
  ami           = "ami-0c55b159cbfafe1f0" # Amazon Linux 2 AMI (us-west-2)
  instance_type = "t2.micro"
  subnet_id     = aws_subnet.main.id
  security_groups = [aws_security_group.allow_ssh.name]
  iam_instance_profile = aws_iam_role.ec2_role.name
  tags = {
    Name = "example-ec2"
  }
}

resource "aws_backup_vault" "example" {
  name        = "example-backup-vault"
  tags = {
    Name = "example-backup-vault"
  }
}

resource "aws_backup_selection" "example" {
  name        = "example-backup-selection"
  iam_role_arn = aws_iam_role.ec2_role.arn
  resources   = [aws_instance.example.arn]
  selection_tags = {
    Name = "example-ec2"
  }
}

resource "aws_backup_plan" "example" {
  name = "example-backup-plan"

  rule {
    rule_name         = "daily-backup"
    target_backup_vault_name = aws_backup_vault.example.name
    schedule          = "0 0 * * ? *" # Every day at midnight
    start_window_minutes = 60
    completion_window_minutes = 120
    selection_id      = aws_backup_selection.example.id
  }
}
```

---

This configuration is ready to be applied with `terraform apply` and will create the necessary infrastructure and backup plan in AWS. Make sure you have the correct AWS credentials configured in your environment.

