**Description of the Terraform Program:**

This Terraform configuration sets up an AWS EventBridge rule that triggers a Lambda function every day at 7:00 UTC. The Lambda function is created with a basic handler that logs a message to CloudWatch. The EventBridge rule is configured with a schedule expression using the `rate` format to run daily at the specified time. An IAM role is created for the Lambda function to allow it to execute and log to CloudWatch.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_lambda_function" "daily_code_runner" {
  function_name    = "daily_code_runner"
  handler          = "index.handler"
  runtime          = "nodejs18.x"
  filename         = "lambda_function.zip"
  role             = aws_iam_role.lambda_role.arn
  source_code_hash = filebase64sha256("lambda_function.zip")

  timeout = 30
  memory_size = 128
}

resource "aws_iam_role" "lambda_role" {
  name = "lambda_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "lambda.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_eventbridge_rule" "daily_code_runner_rule" {
  name        = "daily_code_runner_rule"
  description = "Triggers the daily code runner Lambda function at 7:00 UTC every day"
  schedule_expression = "rate(1 day)"
  state       = "ENABLED"
}

resource "aws_eventbridge_rule_target" "lambda_target" {
  rule      = aws_eventbridge_rule.daily_code_runner_rule.name
  target_id = "daily_code_runner_lambda"
  arn       = aws_lambda_function.daily_code_runner.arn
  input_transformer {
    input_template = "{\"key1\": \"value1\", \"key2\": \"value2\"}"
  }
}
```

---

**Note:**  
- The `filename` and `source_code_hash` fields in the `aws_lambda_function` resource assume that you have a ZIP file named `lambda_function.zip` with the Lambda code. You will need to create this file separately and ensure it contains a valid Node.js Lambda handler.
- The `input_transformer` is optional and can be removed or modified based on your specific use case.
- This configuration assumes the use of Node.js 18.x runtime. You can change it to another supported runtime if needed.

