**Description of the Terraform Program:**

This Terraform configuration sets up the infrastructure for a video streaming site that distributes video content globally. It includes the following components:

- **AWS Route53 Zone**: To manage the domain name for the video streaming site.
- **AWS S3 Bucket**: To store the video content, with appropriate permissions and policies.
- **AWS S3 Bucket Policy**: To allow access to the S3 bucket from CloudFront.
- **AWS CloudFront Origin Access Control (OAC)**: To secure the S3 bucket by allowing only CloudFront to access it.
- **AWS CloudFront Distribution**: To distribute the video content globally with the S3 bucket as the origin.
- **AWS Route53 Record**: To point the domain name to the CloudFront distribution.

All resources are configured in the `us-east-1` region, and default values are provided for any variables used.

---

**Terraform HCL Code:**

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "domain_name" {
  description = "The domain name for the video streaming site"
  default     = "example.com"
}

variable "bucket_name" {
  description = "The name of the S3 bucket to store video content"
  default     = "video-streaming-bucket"
}

resource "aws_route53_zone" "main" {
  name = var.domain_name
}

resource "aws_s3_bucket" "video_content" {
  bucket = var.bucket_name
  acl    = "private"

  tags = {
    Name = "video-streaming-bucket"
  }
}

resource "aws_s3_bucket_policy" "allow_cloudfront_access" {
  bucket = aws_s3_bucket.video_content.bucket

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Sid     = "AllowCloudFrontAccess"
      Effect  = "Allow"
      Principal = {
        Service = "cloudfront.amazonaws.com"
      }
      Action   = "s3:GetObject"
      Resource = "arn:aws:s3:::${aws_s3_bucket.video_content.bucket}/*"
      Condition = {
        StringEquals = {
          "AWS:SourceArn" = aws_cloudfront_distribution.main.arn
        }
      }
    }]
  })
}

resource "aws_cloudfront_origin_access_control" "s3_oac" {
  name   = "s3-video-origin-oac"
  origin_type = "s3"

  comment = "Origin Access Control for S3 bucket"
}

resource "aws_cloudfront_distribution" "main" {
  origin {
    domain_name = aws_s3_bucket.video_content.bucket_domain_name
    origin_id   = "S3-Origin-${aws_s3_bucket.video_content.bucket}"

    origin_access_control_id = aws_cloudfront_origin_access_control.s3_oac.id
  }

  enabled = true

  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "S3-Origin-${aws_s3_bucket.video_content.bucket}"
    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }
    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400
  }

  viewer_certificate {
    acm_certificate_arn = aws_acm_certificate.main.arn
    ssl_support_method  = "sni-only"
    minimum_protocol_version = "TLSv1.2_2021"
  }

  aliases = [var.domain_name]

  tags = {
    Name = "video-streaming-distribution"
  }
}

resource "aws_acm_certificate" "main" {
  domain_name       = var.domain_name
  validation_method = "DNS"

  subject_alternative_names = [
    var.domain_name
  ]
}

resource "aws_acm_certificate_validation" "main" {
  certificate_arn         = aws_acm_certificate.main.arn
  validation_record_fqdns = [aws_route53_record.main.fqdn]
}

resource "aws_route53_record" "main" {
  zone_id = aws_route53_zone.main.id
  name    = var.domain_name
  type    = "A"
  alias {
    name   = aws_cloudfront_distribution.main.domain_name
    type   = "A"
    evaluate_target_health = false
  }
}
