### Description of the Terraform Program

This Terraform configuration sets up the following AWS infrastructure:

1. **CloudFront Origin Access Control (OAC)**: A resource that allows CloudFront to securely access an S3 bucket using signed requests.
2. **CloudFront Distribution**: A content delivery network (CDN) that serves content from an S3 bucket. It includes:
   - An origin pointing to an S3 bucket using the OAC.
   - A default cache behavior that allows only `GET` and `HEAD` methods.
   - A price class of `PriceClass_200`.
   - Geographical restrictions to allow traffic only from the US, Canada, UK, and Germany.
   - A viewer certificate using the default CloudFront certificate.
3. **Route53 Hosted Zone**: A DNS zone for `netflix.com`.
4. **Route53 Records**: Two A records that point to the CloudFront distribution's domain name.

All resources are configured with default values where necessary and are fully self-contained and deployable.

---

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_cloudfront_origin_access_control" "s3_video_content_oac" {
  name                      = "s3-video-content-oac"
  origin_access_control_origin_type = "s3"
  signing_behavior          = "always"
  signing_protocol          = "sigv4"
}

resource "aws_s3_bucket" "video_content_bucket" {
  bucket = "netflix-video-content-bucket"
  acl    = "private"
}

resource "aws_s3_bucket_ownership_controls" "video_content_ownership" {
  bucket = aws_s3_bucket.video_content_bucket.bucket
  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_policy" "video_content_policy" {
  bucket = aws_s3_bucket.video_content_bucket.bucket

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Sid     = "AllowCloudFrontAccess"
      Effect  = "Allow"
      Principal = {
        AWS = "arn:aws:iam::cloudfront::cloudfront-origin-access-identity/cloudfront/${aws_cloudfront_origin_access_control.s3_video_content_oac.id}"
      }
      Action = [
        "s3:GetObject"
      ]
      Resource = "arn:aws:s3:::${aws_s3_bucket.video_content_bucket.bucket}/*"
    }]
  })
}

resource "aws_cloudfront_distribution" "video_content_distribution" {
  origin {
    domain_name           = aws_s3_bucket.video_content_bucket.bucket_domain_name
    origin_access_control_id = aws_cloudfront_origin_access_control.s3_video_content_oac.id
    origin_id             = "s3_video_content_origin"
  }

  default_cache_behavior {
    allowed_methods   = ["GET", "HEAD"]
    cached_methods    = ["GET", "HEAD"]
    target_origin_id  = "s3_video_content_origin"
    viewer_protocol_policy = "allow-all"
  }

  price_class = "PriceClass_200"

  restrictions {
    geo_restriction {
      restriction_type = "whitelist"
      locations        = ["US", "CA", "GB", "DE"]
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }

  enabled = true
}

resource "aws_route53_zone" "netflix_com" {
  name = "netflix.com"
}

resource "aws_route53_record" "netflix_a_record" {
  zone_id = aws_route53_zone.netflix_com.id
  name    = "netflix.com"
  type    = "A"
  alias {
    name                   = aws_cloudfront_distribution.video_content_distribution.domain_name
    zone_id                = aws_cloudfront_distribution.video_content_distribution.hosted_zone_id
    evaluate_target_health = false
  }
}

resource "aws_route53_record" "netflix_cname_record" {
