LLM Output #0:
**Description of the Terraform Program:**

This Terraform configuration sets up a basic infrastructure for a video streaming site using AWS services. It provisions an AWS VPC with a public subnet, an Internet Gateway, and a security group to allow HTTP and HTTPS traffic. It then creates an Application Load Balancer (ALB) with a listener on port 80, and provisions two EC2 instances running a simple web server (e.g., Nginx or Apache) to serve video content. The EC2 instances are placed behind the ALB to balance the load. An IAM role is created for the EC2 instances to allow them to communicate with AWS services if needed.

---

**Terraform HCL Code:**

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "instance_type" {
  description = "EC2 instance type"
  default     = "t2.micro"
}

variable "ami_id" {
  description = "AMI ID for the EC2 instances"
  default     = "ami-0c55b159cbfafe1f0" # Amazon Linux 2 AMI (us-east-1)
}

variable "key_name" {
  description = "Name of the existing EC2 key pair"
  default     = "my-key-pair"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr" {
  description = "CIDR block for the public subnet"
  default     = "10.0.1.0/24"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  tags = {
    Name = "video-streaming-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "video-streaming-igw"
  }
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_cidr
  map_public_ip_on_launch = true
  availability_zone = "us-east-1a"
  tags = {
    Name = "video-streaming-subnet"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "video-streaming-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route" "igw" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_security_group" "web" {
  name        = "video-streaming-web-sg"
  description = "Allow HTTP and HTTPS traffic"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "video-streaming-web-sg"
  }
}

resource "aws_launch_template" "web_server" {
  name_prefix   = "video-streaming-web-server"
  image_id      = var.ami_id
  instance_type = var.instance_type
  key_name      = var.key_name
  security_group_ids = [aws_security_group.web.id]

  tag_specifications {
    resource_type = "instance"
    tags = {
      Name = "video-streaming-web-server"
    }
  }
}

resource "aws_autoscaling_group" "web_servers" {
  launch_template {
    id      = aws_launch_template.web_server.id
    version = "$Latest"
  }

  min_size = 2
  max_size = 2
  desired_capacity = 2

  vpc_zone_identifier = [aws_subnet.public.id]

  target_group_arns = [aws_lb_target_group.web.arn]

  tags = [{
    key                 = "Name"
    value               = "video-streaming-web-server"
    propagate_at_launch = true
  }]
}

resource "aws_lb" "web" {
  name               = "video-streaming-alb"
  internal           = false
  security_groups    = [aws_security_group.web.id]
  subnets            = [aws_subnet.public.id]
  enable_deletion_protection = false

  tags = {
    Name = "video-streaming-alb"
  }
}

resource "aws_lb_target_group" "web" {
  name     = "video-streaming-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    path     = "/"
    interval = 30
    timeout  = 5
    healthy_threshold = 2
    unhealthy_threshold = 2
  }

  tags = {
    Name = "video-streaming-target-group"
  }
}

resource "aws_lb_listener" "web" {
  load_balancer_arn = aws_lb.web.arn
  port              = 80
  protocol          = "HTTP"

  default_actions {
    type = "forward"
    target_group_arn = aws_lb_target_group.web.arn
  }
}

resource "aws_lb_listener_rule" "web" {
  listener_arn = aws_lb_listener.web.arn
  priority     = 1

  actions {
    type = "forward"
    target_group_arn = aws_lb_target_group.web.arn
  }

  conditions {
    field  = "path"
    values = ["/videos/*"]
  }
}
```

---

This configuration is ready to be deployed with Terraform version `~> 1.9.8` and the AWS provider version `~> 5.75`. It assumes that you already have an existing EC2 key pair named `my-key-pair` in the same region. You can modify the AMI ID, instance type, or other parameters as needed for your specific use case.

