LLM Output #0:
**Description of the Terraform Program:**

This Terraform configuration sets up a scalable and secure video streaming infrastructure on AWS. It includes the following components:

- **AWS VPC**: A virtual private cloud to isolate the infrastructure.
- **AWS EC2 Instances**: Multiple EC2 instances running a video streaming service, configured with a security group to allow HTTP and HTTPS traffic.
- **AWS Load Balancer (Application Load Balancer - ALB)**: Distributes incoming traffic across the EC2 instances for load balancing.
- **AWS Route53**: A domain name service to route traffic to the ALB using a public DNS record.
- **IAM Roles**: Necessary IAM roles for EC2 instances to allow secure communication with other AWS services.

The configuration is designed to be deployed in the `us-east-1` region and includes default values for variables to ensure it is ready to use out of the box.

---

**Terraform HCL Code:**

```hcl
provider "aws" {
  region = "us-east-1"
}

# Variables
variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnets" {
  description = "List of public subnet CIDR blocks"
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnets" {
  description = "List of private subnet CIDR blocks"
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "instance_type" {
  description = "EC2 instance type"
  default     = "t2.micro"
}

variable "ami_id" {
  description = "AMI ID for the EC2 instances"
  default     = "ami-0c55b159cbfafe1f0"
}

variable "domain_name" {
  description = "Domain name for Route53"
  default     = "example.com"
}

variable "zone_id" {
  description = "Hosted Zone ID for Route53"
  default     = "Z1234567890ABCDEF"
}

# VPC Module
module "vpc" {
  source = "terraform-aws-modules/vpc/aws"

  name = "video-streaming-vpc"
  cidr = var.vpc_cidr

  public_subnets = var.public_subnets
  private_subnets = var.private_subnets

  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Environment = "production"
  }
}

# EC2 Instances
resource "aws_instance" "streaming_server" {
  count         = 2
  ami           = var.ami_id
  instance_type = var.instance_type
  subnet_id     = module.vpc.private_subnets[0]

  vpc_security_group_ids = [aws_security_group.streaming_server.id]

  tags = {
    Name = "streaming-server-${count.index}"
  }
}

# Security Group for EC2 Instances
resource "aws_security_group" "streaming_server" {
  name        = "streaming-server-sg"
  description = "Allow HTTP and HTTPS traffic to the streaming servers"
  vpc_id      = module.vpc.vpc_id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "streaming-server-sg"
  }
}

# Application Load Balancer
resource "aws_lb" "streaming_alb" {
  name               = "streaming-alb"
  internal           = false
  security_groups    = [aws_security_group.lb_sg.id]
  subnets            = module.vpc.public_subnets
  enable_deletion_protection = false

  tags = {
    Name = "streaming-alb"
  }
}

resource "aws_security_group" "lb_sg" {
  name        = "lb-sg"
  description = "Allow HTTP and HTTPS traffic to the load balancer"
  vpc_id      = module.vpc.vpc_id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "lb-sg"
  }
}

# Target Group for ALB
resource "aws_lb_target_group" "streaming_target_group" {
  name     = "streaming-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = module.vpc.vpc_id

  health_check {
    path     = "/"
    interval = 30
    timeout  = 5
    healthy_threshold = 2
    unhealthy_threshold = 2
  }

  tags = {
    Name = "streaming-target-group"
  }
}

# Listener for ALB
resource "aws_lb_listener" "streaming_listener" {
  load_balancer_arn = aws_lb.streaming_alb.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.streaming_target_group.arn
  }
}

# Register EC2 instances with the target group
resource "aws_lb_target_group_attachment" "streaming_attachment" {
  count            = 2
  target_group_arn = aws_lb_target_group.streaming_target_group.arn
  target_id        = aws_instance.streaming_server[count.index].id
  port             = 80
}

# Route53 Record
resource "aws_route53_record" "streaming_a_record" {
  zone_id = var.zone_id
  name    = "www.${var.domain_name}"
  type    = "A"
  alias {
    name                   = aws_lb.streaming_alb.dns_name
    zone_id                = aws_lb.streaming_alb.zone_id
    evaluate_target_health = true
  }
}
```

---

**Notes:**

- Replace `var.zone_id` with the actual hosted zone ID from your Route53 setup.
- Ensure that the AMI ID used is valid for the region (`us-east-1`).
- This configuration assumes that the Route53 hosted zone already exists. If not, you may need to create it separately.
- You can scale the number of EC2 instances by changing the `count` parameter in the `aws_instance` resource.

