LLM Output #0:
**Description of the Terraform Program:**

This Terraform configuration sets up a scalable and secure video streaming site infrastructure on AWS. It includes a VPC with public and private subnets, a security group to control access, EC2 instances to host the video streaming service, an Application Load Balancer (ALB) to distribute traffic across the EC2 instances, a target group to register the instances with the ALB, a Route53 zone to manage DNS, and a Route53 record to point the domain to the ALB. The configuration ensures that the infrastructure is secure, scalable, and ready for deployment.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-east-1"
}

# VPC Module
module "vpc" {
  source = "terraform-aws-modules/vpc/aws"

  name = "video-streaming-vpc"
  cidr = "10.0.0.0/16"

  azs             = ["us-east-1a", "us-east-1b"]
  private_subnets = ["10.0.1.0/24", "10.0.2.0/24"]
  public_subnets  = ["10.0.0.0/24", "10.0.3.0/24"]

  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Environment = "production"
  }
}

# Security Group for EC2 instances
resource "aws_security_group" "ec2_sg" {
  name        = "video-streaming-ec2-sg"
  description = "Allow HTTP and SSH traffic to EC2 instances"
  vpc_id      = module.vpc.vpc_id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "video-streaming-ec2-sg"
  }
}

# EC2 Instances
resource "aws_instance" "video_streaming" {
  count         = 2
  ami           = "ami-0c55b159cbfafe1f0" # Amazon Linux 2 AMI (us-east-1)
  instance_type = "t2.micro"
  subnet_id     = module.vpc.private_subnets[0]
  vpc_security_group_ids = [aws_security_group.ec2_sg.id]

  tags = {
    Name = "video-streaming-instance-${count.index + 1}"
  }

  user_data = <<-EOF
              #!/bin/bash
              echo "Hello, World!" > /tmp/hello.txt
              EOF
}

# Target Group for ALB
resource "aws_lb_target_group" "video_streaming_tg" {
  name     = "video-streaming-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = module.vpc.vpc_id

  health_check {
    path     = "/health"
    interval = 30
    timeout  = 5
    healthy_threshold = 2
    unhealthy_threshold = 2
  }

  target_type = "instance"
}

# Register EC2 instances with Target Group
resource "aws_lb_target_group_attachment" "video_streaming_attachment" {
  count            = 2
  target_group_arn = aws_lb_target_group.video_streaming_tg.arn
  target_id        = aws_instance.video_streaming[count.index].id
  port             = 80
}

# Application Load Balancer
resource "aws_lb" "video_streaming_alb" {
  name               = "video-streaming-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.ec2_sg.id]
  subnets            = module.vpc.public_subnets

  tags = {
    Name = "video-streaming-alb"
  }
}

# Listener for ALB
resource "aws_lb_listener" "video_streaming_listener" {
  load_balancer_arn = aws_lb.video_streaming_alb.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.video_streaming_tg.arn
  }
}

# Route53 Zone
resource "aws_route53_zone "video_streaming_zone" {
  name = "example.com"
  tags = {
    Name = "video-streaming-zone"
  }
}

# Route53 Record
resource "aws_route53_record" "video_streaming_record" {
  zone_id = aws_route53_zone.video_streaming_zone.id
  name    = "www.example.com"
  type    = "A"
  alias {
    name                   = aws_lb.video_streaming_alb.dns_name
    zone_id                = aws_lb.video_streaming_alb.zone_id
    evaluate_target_health = true
  }
}
```

---

**Notes:**

- This configuration assumes you have a domain (`example.com`) already registered and that you have permissions to create Route53 zones.
- The EC2 instances are set up with a basic `user_data` script for demonstration purposes. You can replace this with a script that installs and configures your video streaming service.
- The VPC module is sourced from the official Terraform AWS module for VPCs. You can replace it with a custom VPC if needed.
- The AMI ID used is for Amazon Linux 2 in the `us-east-1` region. You may need to adjust it for other regions or OS versions.

