**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet"
  default     = "10.0.1.0/24"
}

variable "db_subnet_cidr" {
  description = "CIDR block for the database subnet"
  default     = "10.0.2.0/24"
}

variable "db_security_group_description" {
  description = "Description for the database security group"
  default     = "Allow access to PostgreSQL database"
}

variable "db_instance_class" {
  description = "Instance class for the PostgreSQL database"
  default     = "db.t3.micro"
}

variable "db_engine_version" {
  description = "PostgreSQL engine version"
  default     = "14.7"
}

variable "db_name" {
  description = "Name of the PostgreSQL database"
  default     = "mydb"
}

variable "db_username" {
  description = "Username for the PostgreSQL database"
  default     = "admin"
}

variable "db_password" {
  description = "Password for the PostgreSQL database"
  default     = "SecurePassword123!"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.public_subnet_cidr
  map_public_ip_on_launch = true
  availability_zone = "us-west-2a"
  tags = {
    Name = "public-subnet"
  }
}

resource "aws_subnet" "db" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.db_subnet_cidr
  availability_zone = "us-west-2a"
  tags = {
    Name = "db-subnet"
  }
}

resource "aws_security_group" "db" {
  name        = "db-sg"
  description = var.db_security_group_description
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["10.0.1.0/24"]  # Allow access from public subnet
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "db-sg"
  }
}

resource "aws_db_instance" "postgres" {
  allocated_storage      = 20
  db_name                = var.db_name
  engine                 = "postgres"
  engine_version         = var.db_engine_version
  instance_class         = var.db_instance_class
  username               = var.db_username
  password               = var.db_password
  vpc_security_group_ids = [aws_security_group.db.id]
  db_subnet_group_name   = aws_db_subnet_group.postgres.name
  skip_final_snapshot    = true
  tags = {
    Name = "postgres-db"
  }
}

resource "aws_db_subnet_group" "postgres" {
  name       = "postgres-subnet-group"
  subnet_ids = [aws_subnet.db.id]
  tags = {
    Name = "postgres-subnet-group"
  }
}
```

