**Description of the Terraform Program:**

This Terraform configuration provisions a secure PostgreSQL 15 database instance on AWS RDS within a specified VPC. It includes the creation of a custom parameter group for PostgreSQL settings, a security group to control access, and a KMS key for encryption. The RDS instance is configured with 50GB of storage, multi-AZ deployment for high availability, and encryption at rest using the KMS key. The configuration assumes the VPC and subnets are already defined or can be created as part of the setup.

---

**Terraform HCL Code:**

```hcl
provider "aws" {
  region = "us-west-2"
}

# Define variables with defaults
variable "vpc_id" {
  description = "The ID of the VPC where the RDS instance will be deployed."
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "List of subnet IDs for the RDS instance."
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "db_name" {
  description = "Name of the PostgreSQL database."
  default     = "secure_db"
}

variable "db_username" {
  description = "Username for the PostgreSQL database."
  default     = "admin"
}

variable "db_password" {
  description = "Password for the PostgreSQL database."
  default     = "SecurePassword123!"
}

variable "kms_key_arn" {
  description = "ARN of the KMS key to use for encryption."
  default     = "arn:aws:kms:us-west-2:123456789012:key/abcd1234-a123-4567-8abc-def123456789"
}

# Create a KMS key if not provided
resource "aws_kms_key" "db_encryption_key" {
  description             = "KMS key for encrypting the PostgreSQL database"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

# Create a custom parameter group for PostgreSQL
resource "aws_db_parameter_group" "postgres_custom" {
  name         = "postgres15-custom"
  family       = "postgres15"
  description  = "Custom parameter group for PostgreSQL 15"

  parameter {
    name  = "log_statement"
    value = "all"
  }

  parameter {
    name  = "shared_preload_libraries"
    value = "pg_stat_statements"
  }
}

# Create a security group for the RDS instance
resource "aws_security_group" "rds_sg" {
  name        = "rds-sg"
  description = "Security group for PostgreSQL RDS instance"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]  # Adjust based on your network
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create the PostgreSQL RDS instance
resource "aws_db_instance" "postgres_db" {
  identifier             = "secure-postgres-db"
  engine                 = "postgres"
  engine_version         = "15"
  db_name                = var.db_name
  username               = var.db_username
  password               = var.db_password
  allocated_storage      = 50
  storage_type           = "gp2"
  instance_class         = "db.t3.medium"
  vpc_security_group_ids = [aws_security_group.rds_sg.id]
  db_subnet_group_name   = "default"
  multi_az               = true
  parameter_group_name   = aws_db_parameter_group.postgres_custom.name
  storage_encrypted      = true
  kms_key_id             = var.kms_key_arn != "" ? var.kms_key_arn : aws_kms_key.db_encryption_key.arn
  skip_final_snapshot    = true
}
```

---

**Notes:**

- This configuration assumes that the VPC and subnets are already created. If not, you can add `aws_vpc` and `aws_subnet` resources.
- The `kms_key_arn` variable is optional and defaults to a newly created KMS key if not provided.
- The security group allows access from `10.0.0.0/16` — adjust this to your actual network CIDR.
- The `db_subnet_group_name` is set to `"default"`; if you need a custom subnet group, you can create one with `aws_db_subnet_group`.

