**Description of the Terraform Program:**

This Terraform configuration provisions a secure PostgreSQL database instance on AWS RDS within a specified VPC. It creates a custom parameter group for PostgreSQL settings, a security group to control access, and a KMS key for encryption. The RDS instance is configured with multi-AZ deployment for high availability, a specified storage size, and an engine version. The final snapshot identifier is set to "pgsnapshot" to ensure a consistent backup strategy. All resources are created within a defined AWS region, and IAM roles are appropriately configured for secure access.

---

**Terraform HCL Code:**

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_id" {
  description = "The ID of the VPC where the RDS instance will be deployed."
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "List of subnet IDs for the RDS instance."
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "db_name" {
  description = "Name of the PostgreSQL database."
  default     = "mydb"
}

variable "db_username" {
  description = "Username for the PostgreSQL database."
  default     = "admin"
}

variable "db_password" {
  description = "Password for the PostgreSQL database."
  default     = "SecurePassword123!"
}

variable "db_instance_class" {
  description = "Instance class for the RDS PostgreSQL instance."
  default     = "db.t3.medium"
}

variable "db_engine_version" {
  description = "PostgreSQL engine version."
  default     = "14.7"
}

variable "db_storage_size" {
  description = "Storage size in GB for the RDS instance."
  default     = 20
}

variable "kms_key_arn" {
  description = "ARN of the KMS key to use for encryption."
  default     = "arn:aws:kms:us-west-2:123456789012:key/abcd1234-a123-4567-8abc-def123456789"
}

resource "aws_db_parameter_group" "postgres_custom" {
  name         = "postgres-custom"
  family       = "postgres14"
  description  = "Custom parameter group for PostgreSQL"

  parameter {
    name         = "log_statement"
    value        = "all"
    apply_method = "pending-reboot"
  }

  parameter {
    name         = "shared_buffers"
    value        = "256MB"
    apply_method = "pending-reboot"
  }
}

resource "aws_security_group" "rds_sg" {
  name        = "rds-sg"
  description = "Security group for RDS PostgreSQL instance"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]  # Adjust based on your network
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_kms_key" "db_encryption_key" {
  description             = "KMS key for encrypting RDS database"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_db_instance" "postgres" {
  identifier             = "postgres-instance"
  engine                 = "postgres"
  engine_version         = var.db_engine_version
  instance_class         = var.db_instance_class
  db_name                = var.db_name
  username               = var.db_username
  password               = var.db_password
  allocated_storage      = var.db_storage_size
  vpc_security_group_ids = [aws_security_group.rds_sg.id]
  db_subnet_group_name   = aws_db_subnet_group.postgres_subnet_group.name
  parameter_group_name   = aws_db_parameter_group.postgres_custom.name
  storage_encrypted      = true
  kms_key_id             = var.kms_key_arn
  multi_az               = true
  final_snapshot_identifier = "pgsnapshot"
  skip_final_snapshot      = false
}

resource "aws_db_subnet_group" "postgres_subnet_group" {
  name       = "postgres-subnet-group"
  subnet_ids = var.subnet_ids
  description = "Subnet group for PostgreSQL RDS instance"
}
```

---

**Notes:**

- Replace the default values (e.g., `vpc_id`, `subnet_ids`, `kms_key_arn`) with your actual AWS environment values.
- Ensure that the KMS key has the appropriate permissions for RDS to use it for encryption.
- The security group allows access from a specific CIDR range; adjust this to match your network requirements.
- The `skip_final_snapshot` is set to `false` to ensure a final snapshot is created with the identifier `pgsnapshot`.

