**Description of the Terraform Program:**

This Terraform configuration will set up a PostgreSQL 15 instance on AWS RDS within specific public subnets. The RDS instance will be configured with managed settings to ensure low maintenance, including automated backups, monitoring, and patching. The instance will be deployed in a public subnet, allowing for easy access and testing of Airbyte connectors. The configuration includes a VPC, public subnets, an RDS instance, and an IAM role for the RDS instance to ensure secure and efficient operation.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr_1" {
  description = "CIDR block for the first public subnet"
  default     = "10.0.1.0/24"
}

variable "public_subnet_cidr_2" {
  description = "CIDR block for the second public subnet"
  default     = "10.0.2.0/24"
}

variable "rds_instance_type" {
  description = "Instance type for RDS"
  default     = "db.t3.medium"
}

variable "rds_db_name" {
  description = "Name of the RDS database"
  default     = "airbyte_test_db"
}

variable "rds_username" {
  description = "Username for the RDS database"
  default     = "airbyte_user"
}

variable "rds_password" {
  description = "Password for the RDS database"
  default     = "SecurePassword123!"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  tags = {
    Name = "airbyte-test-vpc"
  }
}

resource "aws_subnet" "public_1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.public_subnet_cidr_1
  map_public_ip_on_launch = true
  availability_zone = "us-east-1a"
  tags = {
    Name = "airbyte-test-public-subnet-1"
  }
}

resource "aws_subnet" "public_2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.public_subnet_cidr_2
  map_public_ip_on_launch = true
  availability_zone = "us-east-1b"
  tags = {
    Name = "airbyte-test-public-subnet-2"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "airbyte-test-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "airbyte-test-public-rt"
  }
}

resource "aws_route_table_association" "public_1" {
  subnet_id      = aws_subnet.public_1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_2" {
  subnet_id      = aws_subnet.public_2.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route" "internet_gateway" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_db_instance" "airbyte_test_db" {
  allocated_storage      = 20
  db_name                = var.rds_db_name
  engine                 = "postgres"
  engine_version         = "15"
  instance_class         = var.rds_instance_type
  username               = var.rds_username
  password               = var.rds_password
  db_subnet_group_name   = aws_db_subnet_group.airbyte_test_group.name
  vpc_security_group_ids = [aws_security_group.rds_access.id]
  skip_final_snapshot    = true
  backup_retention_period = 7
  monitoring_interval     = 60
  tags = {
    Name = "airbyte-test-db"
  }
}

resource "aws_db_subnet_group" "airbyte_test_group" {
  name       = "airbyte-test-subnet-group"
  subnet_ids = [aws_subnet.public_1.id, aws_subnet.public_2.id]
  tags = {
    Name = "airbyte-test-subnet-group"
  }
}

resource "aws_security_group" "rds_access" {
  name        = "airbyte-test-rds-sg"
  description = "Allow access to RDS instance for Airbyte testing"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "airbyte-test-rds-sg"
  }
}
```

---

This configuration will create a VPC with two public subnets, an internet gateway, and a route table to allow internet access. It will also create a PostgreSQL 15 RDS instance in the public subnets, with a security group allowing access to port 5432. The RDS instance is configured with automated backups and monitoring for low-maintenance operation.

