**Description of the Terraform Program:**

This Terraform configuration sets up an AWS RDS PostgreSQL 15 instance optimized for running Airbyte connector test cases. The database is deployed in a specific public subnet, configured for low maintenance using managed settings. The configuration ensures that the final snapshot is skipped and that any changes to the database are applied immediately without requiring a reboot. The setup includes a VPC, public subnets, a security group, and an RDS instance with appropriate IAM roles and parameters.

---

**Terraform HCL Code:**

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr_1" {
  description = "CIDR block for the first public subnet"
  default     = "10.0.1.0/24"
}

variable "public_subnet_cidr_2" {
  description = "CIDR block for the second public subnet"
  default     = "10.0.2.0/24"
}

variable "db_instance_class" {
  description = "Instance class for the RDS PostgreSQL instance"
  default     = "db.t3.medium"
}

variable "db_name" {
  description = "Name of the PostgreSQL database"
  default     = "airbyte_test_db"
}

variable "db_username" {
  description = "Username for the PostgreSQL database"
  default     = "airbyte_user"
}

variable "db_password" {
  description = "Password for the PostgreSQL database"
  default     = "SecurePassword123!"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  tags = {
    Name = "airbyte-test-vpc"
  }
}

resource "aws_subnet" "public_1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.public_subnet_cidr_1
  map_public_ip_on_launch = true
  availability_zone = "us-east-1a"
  tags = {
    Name = "airbyte-test-subnet-1"
  }
}

resource "aws_subnet" "public_2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.public_subnet_cidr_2
  map_public_ip_on_launch = true
  availability_zone = "us-east-1b"
  tags = {
    Name = "airbyte-test-subnet-2"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "airbyte-test-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "airbyte-test-public-rt"
  }
}

resource "aws_route_table_association" "public_1" {
  subnet_id      = aws_subnet.public_1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_2" {
  subnet_id      = aws_subnet.public_2.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route" "internet_gateway" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_security_group" "rds" {
  name        = "airbyte-test-rds-sg"
  description = "Allow access to RDS PostgreSQL instance"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "airbyte-test-rds-sg"
  }
}

resource "aws_db_instance" "airbyte_test_db" {
  allocated_storage      = 20
  db_name                = var.db_name
  engine                 = "postgres"
  engine_version         = "15"
  instance_class         = var.db_instance_class
  master_username        = var.db_username
  master_user_password   = var.db_password
  db_subnet_group_name   = aws_db_subnet_group.airbyte_test.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  skip_final_snapshot    = true
  apply_immediately      = true
  tags = {
    Name = "airbyte-test-db"
  }
}

resource "aws_db_subnet_group" "airbyte_test" {
  name       = "airbyte-test-subnet-group"
  subnet_ids = [aws_subnet.public_1.id, aws_subnet.public_2.id]
  tags = {
    Name = "airbyte-test-subnet-group"
  }
}
```

---

**Notes:**

- This configuration assumes that you are using the `us-east-1` region. You can change it by modifying the `region` parameter in the provider block.
- The RDS instance is configured to skip the final snapshot and apply changes immediately.
- The database is set up in a public subnet with internet access, which is suitable for testing purposes.
- The security group allows access to port 5432 from anywhere (`0.0.0.0/0`). In a production environment, you should restrict this to specific IP ranges or VPCs.

