**Description of the Terraform Program:**

This Terraform configuration will set up a PostgreSQL 15 instance on AWS RDS with 500GB of storage. The RDS instance will be deployed within specific public subnets, making it accessible over the internet. The configuration will use managed settings to ensure low maintenance, including automated backups, monitoring, and patching. An IAM role will be created to allow the RDS instance to interact with other AWS services if needed. The provider configuration will be set to the `us-east-1` region by default, and all necessary resources will be fully declared and configured.

---

**Terraform HCL Code:**

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_id" {
  description = "The ID of the VPC where the RDS instance will be deployed."
  default     = "vpc-12345678"
}

variable "public_subnet_ids" {
  description = "List of public subnet IDs where the RDS instance will be deployed."
  type        = list(string)
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "db_name" {
  description = "The name of the PostgreSQL database."
  default     = "airbyte_db"
}

variable "db_username" {
  description = "The username for the PostgreSQL database."
  default     = "airbyte_user"
}

variable "db_password" {
  description = "The password for the PostgreSQL database."
  default     = "SecurePassword123!"
}

resource "aws_db_instance" "airbyte_postgres" {
  identifier             = "airbyte-postgres"
  engine                 = "postgres"
  engine_version         = "15"
  db_name                = var.db_name
  username               = var.db_username
  password               = var.db_password
  allocated_storage      = 500
  instance_class         = "db.t3.medium"
  vpc_security_group_ids = []
  db_subnet_group_name   = aws_db_subnet_group.airbyte_postgres.name
  publicly_accessible    = true
  skip_final_snapshot    = true
  backup_retention_period = 7
  monitoring_interval     = 60
  apply_immediately       = true
  tags = {
    Name = "Airbyte-PostgreSQL"
  }
}

resource "aws_db_subnet_group" "airbyte_postgres" {
  name       = "airbyte-postgres-subnet-group"
  subnet_ids = var.public_subnet_ids
  db_subnet_group_description = "Subnet group for Airbyte PostgreSQL instance"
  tags = {
    Name = "Airbyte-PostgreSQL-Subnet-Group"
  }
}

resource "aws_iam_role" "rds_role" {
  name = "airbyte-rds-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "rds.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "rds_role_policy" {
  role       = aws_iam_role.rds_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonRDSFullAccess"
}
