**Description of the Terraform Program:**

This Terraform configuration sets up a PostgreSQL database instance on AWS using Amazon RDS. It provisions a custom VPC with two private subnets, a security group to control access to the database, and an RDS instance with the specified PostgreSQL engine version, instance size, storage, backup retention period, and backup window. The configuration ensures that the RDS instance is deployed within the custom VPC and subnet, and includes a provider block with a valid AWS region.

---

**Terraform HCL Code:**

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "main-vpc"
  }
}

# Create two private subnets
resource "aws_subnet" "private" {
  count = 2
  vpc_id = aws_vpc.main.id
  cidr_block = "10.0.${count.index + 1}.0/24"
  map_public_ip_on_launch = false
  availability_zone = data.aws_availability_zones.available.names[count.index]
  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

# Get availability zones
data "aws_availability_zones" "available" {
  state = "available"
}

# Create an internet gateway (optional, not used in this case)
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "main-igw"
  }
}

# Create a route table for the VPC
resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "main-route-table"
  }
}

# Associate route table with subnets
resource "aws_route_table_association" "private" {
  count = 2
  subnet_id = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.main.id
}

# Create a security group for the RDS instance
