**Description of the Terraform Program:**

This Terraform configuration sets up a PostgreSQL database instance on AWS using Amazon RDS. It provisions a custom VPC with two private subnets, a security group that restricts access to the database, and an RDS instance with specific engine version, instance size, and storage parameters. The RDS instance is configured to allow major version upgrades, automatically apply minor version upgrades, and is not publicly accessible. All resources are created within a specified AWS region.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a VPC
resource "aws_vpc" "db_vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "db-vpc"
  }
}

# Create two private subnets
resource "aws_subnet" "private_subnet1" {
  vpc_id            = aws_vpc.db_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  map_public_ip_on_launch = false
  tags = {
    Name = "private-subnet-1"
  }
}

resource "aws_subnet" "private_subnet2" {
  vpc_id            = aws_vpc.db_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
  map_public_ip_on_launch = false
  tags = {
    Name = "private-subnet-2"
  }
}

# Create an internet gateway (not used for private subnets, but required for VPC)
resource "aws_internet_gateway" "db_igw" {
  vpc_id = aws_vpc.db_vpc.id
  tags = {
    Name = "db-igw"
  }
}

# Create a route table for the VPC
resource "aws_route_table" "db_route_table" {
  vpc_id = aws_vpc.db_vpc.id
  tags = {
    Name = "db-route-table"
  }
}

# Associate subnets with the route table
resource "aws_route_table_association" "private_subnet1_assoc" {
  subnet_id      = aws_subnet.private_subnet1.id
  route_table_id = aws_route_table.db_route_table.id
}

resource "aws_route_table_association" "private_subnet2_assoc" {
  subnet_id      = aws_subnet.private_subnet2.id
  route_table_id = aws_route_table.db_route_table.id
}

# Create a security group for the RDS instance
resource "aws_security_group" "db_sg" {
  name        = "db-sg"
  description = "Security group for RDS instance"
  vpc_id      = aws_vpc.db_vpc.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]  # Allow access from within the VPC
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "db-sg"
  }
}

# Create an RDS PostgreSQL instance
resource "aws_db_instance" "postgres_db" {
  allocated_storage      = 20
  engine                 = "postgres"
  engine_version         = "14.7"
  instance_class         = "db.t3.medium"
  db_name                = "mydb"
  username               = "admin"
  password               = "SecurePassword123!"
  skip_final_snapshot    = true
  vpc_security_group_ids = [aws_security_group.db_sg.id]
  db_subnet_group_name   = aws_db_subnet_group.db_subnet_group.name
  allow_major_version_upgrade = true
  auto_minor_version_upgrade  = true
  publicly_accessible         = false
  tags = {
    Name = "postgres-db"
  }
}

# Create a DB subnet group
resource "aws_db_subnet_group" "db_subnet_group" {
  name       = "db-subnet-group"
  subnet_ids = [aws_subnet.private_subnet1.id, aws_subnet.private_subnet2.id]
  tags = {
    Name = "db-subnet-group"
  }
}
```

---

**Notes:**

- The RDS instance is configured with PostgreSQL 14.7, and it allows major version upgrades and auto-minor version upgrades.
- The database is not publicly accessible and is placed in a private subnet within a custom VPC.
- A security group is used to restrict access to the database to only within the VPC.
- The password is hardcoded for simplicity, but in a real-world scenario, it should be sourced from a secure secret management system.

