**Description of the Terraform Program:**

This Terraform configuration sets up an AWS RDS Aurora MySQL cluster with an associated RDS Proxy for enhanced connection management. It provisions a VPC with public and private subnets, a security group for the RDS cluster and proxy, an IAM role for the RDS instance, and integrates AWS Secrets Manager for secure credential storage. The configuration ensures that the RDS cluster and proxy are deployed in a secure and isolated network environment, with appropriate access controls and secret management.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-west-2"
}

# Define variables with defaults
variable "vpc_cidr" {
  default = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  default = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
}

variable "db_name" {
  default = "mydb"
}

variable "db_username" {
  default = "admin"
}

variable "db_password" {
  default = "SecurePassword123!"
}

variable "db_instance_class" {
  default = "db.r5.large"
}

variable "db_engine" {
  default = "aurora-mysql"
}

variable "db_engine_version" {
  default = "5.7.mysql_aurora.2.11.2"
}

variable "db_cluster_identifier" {
  default = "aurora-cluster-1"
}

variable "db_proxy_name" {
  default = "aurora-proxy-1"
}

variable "db_proxy_instance_count" {
  default = 2
}

variable "db_proxy_auth" {
  default = {
    username = "admin"
    auth_type = "SECRETS_MANAGER"
  }
}

# Create VPC
resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  tags = {
    Name = "aurora-vpc"
  }
}

# Create public and private subnets
resource "aws_subnet" "private" {
  count = 2
  vpc_id = aws_vpc.main.id
  cidr_block = var.subnet_cidr_blocks[count.index]
  map_public_ip_on_launch = false
  availability_zone = data.aws_availability_zones.available.names[count.index]
  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "public" {
  count = 1
  vpc_id = aws_vpc.main.id
  cidr_block = var.subnet_cidr_blocks[2]
  map_public_ip_on_launch = true
  availability_zone = data.aws_availability_zones.available.names[2]
  tags = {
    Name = "public-subnet-1"
  }
}

# Create internet gateway and route table for public subnet
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "aurora-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "public-route-table"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route" "internet_gateway" {
  route_table_id = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id = aws_internet_gateway.main.id
}

# Create security group for RDS and proxy
resource "aws_security_group" "rds" {
  name        = "rds-sg"
  description = "Allow access to RDS cluster and proxy"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "rds-sg"
  }
}

# Create IAM role for RDS
resource "aws_iam_role" "rds_role" {
  name = "rds-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "rds.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "rds_secrets" {
  role       = aws_iam_role.rds_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSReadOnlyAccess"
}

# Create Secrets Manager secret for DB credentials
resource "aws_secretsmanager_secret" "db_credentials" {
  name = "aurora-db-credentials"
  description = "Secret for Aurora MySQL DB credentials"
  tags = {
    Name = "aurora-db-credentials"
  }
}

resource "aws_secretsmanager_secret_version" "db_credentials" {
  secret_id = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({
    username = var.db_username
    password = var.db_password
  })
}

# Create Aurora MySQL cluster
resource "aws_rds_cluster" "main" {
  cluster_identifier = var.db_cluster_identifier
  engine             = var.db_engine
  engine_version     = var.db_engine_version
  database_name      = var.db_name
  master_username    = var.db_username
  master_password    = var.db_password
  skip_final_snapshot = true
  db_subnet_group_name = aws_db_subnet_group.aurora.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  iam_roles = [aws_iam_role.rds_role.arn]
  tags = {
    Name = "aurora-cluster"
  }
}

resource "aws_db_subnet_group" "aurora" {
  name       = "aurora-subnet-group"
  subnet_ids = aws_subnet.private.*.id
  tags = {
    Name = "aurora-subnet-group"
  }
}

# Create Aurora MySQL cluster instance
resource "aws_rds_cluster_instance" "main" {
  count = 2
  cluster_identifier = aws_rds_cluster.main.id
  instance_class     = var.db_instance_class
  engine             = var.db_engine
  engine_version     = var.db_engine_version
  db_subnet_group_name = aws_db_subnet_group.aurora.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  tags = {
    Name = "aurora-instance-${count.index + 1}"
  }
}

# Create RDS Proxy
resource "aws_rds_proxy" "main" {
  name = var.db_proxy_name
  auth {
    username = var.db_proxy_auth.username
    auth_type = var.db_proxy_auth.auth_type
    secret_arn = aws_secretsmanager_secret.db_credentials.arn
  }
  target_group {
    db_cluster_identifier = aws_rds_cluster.main.id
    target_type = "RDS"
  }
  vpc_security_group_ids = [aws_security_group.rds.id]
  db_subnet_group_name = aws_db_subnet_group.aurora.name
  tags = {
    Name = "aurora-proxy"
  }
}

# Data source for availability zones
data "aws_availability_zones" "available" {
  state = "available"
}
```

