**Description of the Terraform Program:**

This Terraform configuration sets up an AWS RDS Aurora MySQL cluster with an associated RDS Proxy for enhanced connection management. The infrastructure includes a VPC with public and private subnets, a security group for the RDS cluster and proxy, an IAM role for the RDS proxy, and integration with AWS Secrets Manager for secure credential storage. The RDS Proxy is configured with an idle client timeout of 1800 seconds and debug logging is disabled. All resources are defined with default values and are deployable using Terraform 1.9.8 and the AWS provider version 5.75.

---

**Terraform HCL Code:**

```hcl
provider "aws" {
  region = "us-west-2"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "aurora-vpc"
  }
}

# Public Subnets
resource "aws_subnet" "public" {
  count = 2
  vpc_id = aws_vpc.main.id
  cidr_block = "10.0.${count.index + 1}.0/24"
  map_public_ip_on_launch = true
  availability_zone = "us-west-2${count.index + 1}"
  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

# Private Subnets
resource "aws_subnet" "private" {
  count = 2
  vpc_id = aws_vpc.main.id
  cidr_block = "10.0.${count.index + 3}.0/24"
  availability_zone = "us-west-2${count.index + 1}"
  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "aurora-igw"
  }
}

# Route Table for Public Subnets
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "public-route-table"
  }
}

resource "aws_route" "public" {
  route_table_id = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id = aws_internet_gateway.main.id
}

# Associate Public Subnets with Route Table
resource "aws_route_table_association" "public" {
  count = 2
  subnet_id = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Security Group for RDS and Proxy
resource "aws_security_group" "rds" {
  name        = "rds-sg"
  description = "Allow access to RDS and Proxy"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "rds-sg"
  }
}

# IAM Role for RDS Proxy
resource "aws_iam_role" "rds_proxy" {
  name = "rds-proxy-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "rds.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

# IAM Role Policy for RDS Proxy
resource "aws_iam_role_policy_attachment" "rds_proxy" {
  role       = aws_iam_role.rds_proxy.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSProxyAccess"
}

# RDS Aurora MySQL Cluster
resource "aws_rds_cluster" "aurora" {
  cluster_identifier      = "aurora-cluster"
  engine                  = "aurora-mysql"
  engine_version          = "5.7.mysql_aurora.2.11.2"
  database_name           = "mydb"
  master_username         = "admin"
  master_password         = aws_secretsmanager_secret.aurora_password.secret_string
  skip_final_snapshot     = true
  backup_retention_period = 5
  preferred_backup_window = "01:00-02:00"
  db_subnet_group_name    = aws_db_subnet_group.aurora.name
  vpc_security_group_ids  = [aws_security_group.rds.id]
  tags = {
    Name = "aurora-cluster"
  }
}

# RDS Aurora Subnet Group
resource "aws_db_subnet_group" "aurora" {
  name       = "aurora-subnet-group"
  subnet_ids = aws_subnet.private.*.id
  tags = {
    Name = "aurora-subnet-group"
  }
}

# RDS Proxy
resource "aws_rds_proxy" "proxy" {
  name                   = "aurora-proxy"
  target_group_name      = "aurora-target-group"
  db_cluster_identifier  = aws_rds_cluster.aurora.id
  debug_logging          = false
  idle_client_timeout    = 1800
  role_arn               = aws_iam_role.rds_proxy.arn
  tags = {
    Name = "aurora-proxy"
  }
}

# Secrets Manager for RDS Credentials
resource "aws_secretsmanager_secret" "aurora_password" {
  name        = "aurora-db-password"
  description = "Secret for Aurora MySQL cluster password"
  tags = {
    Name = "aurora-db-password"
  }
}

resource "aws_secretsmanager_secret_version" "aurora_password" {
  secret_id     = aws_secretsmanager_secret.aurora_password.id
  secret_string = jsonencode({
    password = "SecurePassword123!"
  })
}
```

---

This configuration is ready to be applied with `terraform apply` and will create a secure, scalable, and well-architected RDS Aurora MySQL cluster with proxy, VPC, and Secrets Manager integration.

