**Description of the Terraform Program:**

This Terraform configuration sets up an AWS RDS Aurora MySQL cluster with an associated RDS Proxy for enhanced connection management. It provisions a VPC with public and private subnets, a security group to control access, an IAM role for the RDS instance, and integrates AWS Secrets Manager for secure credential storage. The RDS cluster is configured with a backup retention period of 5 days and a preferred backup window from 7 AM to 9 AM.

---

**Terraform HCL Code:**

```hcl
provider "aws" {
  region = "us-west-2"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "aurora-vpc"
  }
}

# Public Subnets
resource "aws_subnet" "public" {
  count = 2
  vpc_id = aws_vpc.main.id
  cidr_block = "10.0.${count.index + 1}.0/24"
  map_public_ip_on_launch = true
  availability_zone = "us-west-2${count.index + 1}"
  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

# Private Subnets
resource "aws_subnet" "private" {
  count = 2
  vpc_id = aws_vpc.main.id
  cidr_block = "10.0.${count.index + 3}.0/24"
  availability_zone = "us-west-2${count.index + 1}"
  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "aurora-igw"
  }
}

# Route Table for Public Subnets
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "public-route-table"
  }
}

resource "aws_route" "public" {
  route_table_id = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id = aws_internet_gateway.main.id
}

# Associate Public Subnets with Route Table
resource "aws_route_table_association" "public" {
  count = 2
  subnet_id = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Security Group for RDS
resource "aws_security_group" "rds" {
  name        = "rds-sg"
  description = "Allow access to RDS cluster"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "rds-sg"
  }
}

# IAM Role for RDS
resource "aws_iam_role" "rds_role" {
  name = "rds-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "rds.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

# IAM Role Policy for Secrets Manager
resource "aws_iam_role_policy_attachment" "rds_secrets" {
  role       = aws_iam_role.rds_role.name
  policy_arn = "arn:aws:iam::aws:policy/SecretsManagerReadWrite"
}

# RDS Proxy
resource "aws_rds_proxy" "proxy" {
  name                   = "aurora-proxy"
  target_group_name      = "aurora-target-group"
  db_cluster_identifier  = aws_rds_cluster.aurora.id
  debug_logging          = true
  require_ssl            = true
  role_arn               = aws_iam_role.rds_role.arn
  tags = {
    Name = "aurora-proxy"
  }
}

# RDS Cluster
resource "aws_rds_cluster" "aurora" {
  cluster_identifier      = "aurora-cluster"
  engine                  = "aurora-mysql"
  engine_version          = "5.7.mysql_aurora.2.11.2"
  database_name           = "mydb"
  master_username         = "admin"
  master_password         = aws_secretsmanager_secret.aurora_secret.secret_string
  backup_retention_period = 5
  preferred_backup_window = "07:00-09:00"
  db_subnet_group_name    = aws_db_subnet_group.aurora.name
  vpc_security_group_ids  = [aws_security_group.rds.id]
  iam_database_authentication_enabled = true
  skip_final_snapshot     = true
  tags = {
    Name = "aurora-cluster"
  }
}

# RDS Cluster Instances
resource "aws_rds_cluster_instance" "aurora_instance" {
  count = 2
  cluster_identifier = aws_rds_cluster.aurora.id
  instance_class     = "db.r5.large"
  engine             = "aurora-mysql"
  tags = {
    Name = "aurora-instance-${count.index + 1}"
  }
}

# DB Subnet Group
resource "aws_db_subnet_group" "aurora" {
  name       = "aurora-subnet-group"
  subnet_ids = aws_subnet.private.*.id
  tags = {
    Name = "aurora-subnet-group"
  }
}

# Secrets Manager Secret for RDS
resource "aws_secretsmanager_secret" "aurora_secret" {
  name = "aurora-db-credentials"
  tags = {
    Name = "aurora-db-credentials"
  }
}

resource "aws_secretsmanager_secret_version" "aurora_secret_version" {
  secret_id       = aws_secretsmanager_secret.aurora_secret.id
  secret_string = jsonencode({
    username = "admin"
    password = "SecurePassword123!"
  })
}
```

---

**Notes:**

- This configuration assumes that the `master_password` is stored in AWS Secrets Manager. You can modify the `secret_string` to use a more secure password or generate it dynamically.
- The RDS cluster is set up with two instances in a multi-AZ configuration.
- The backup retention period is set to 5 days, and the preferred backup window is from 7 AM to 9 AM.
- The RDS Proxy is configured with SSL and debug logging enabled.
- The IAM role allows the RDS cluster to access Secrets Manager for secure credential retrieval.

