**Description of the Terraform Program:**

This Terraform configuration sets up an AWS RDS Aurora MySQL cluster with an associated RDS Proxy for enhanced connection management. It provisions a VPC with public and private subnets, a security group for the RDS cluster and proxy, an IAM role for the RDS instance, and integrates AWS Secrets Manager for secure credential storage. The RDS cluster uses the Aurora MySQL engine version 8.0.mysql_aurora.3.08.0. All resources are defined with default values and are deployable in the `us-east-1` region.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "aurora-vpc"
  }
}

# Public Subnets
resource "aws_subnet" "public" {
  count = 2
  vpc_id = aws_vpc.main.id
  cidr_block = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  map_public_ip_on_launch = true
  availability_zone = data.aws_availability_zones.available.names[count.index]
  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

# Private Subnets
resource "aws_subnet" "private" {
  count = 2
  vpc_id = aws_vpc.main.id
  cidr_block = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 3)
  availability_zone = data.aws_availability_zones.available.names[count.index]
  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "aurora-igw"
  }
}

# Route Table for Public Subnets
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "public-route-table"
  }
}

resource "aws_route" "public" {
  route_table_id = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id = aws_internet_gateway.main.id
}

# Associate Public Subnets with Public Route Table
resource "aws_route_table_association" "public" {
  count = 2
  subnet_id = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Security Group for RDS and Proxy
resource "aws_security_group" "rds" {
  name        = "rds-sg"
  description = "Allow access to RDS and Proxy"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "rds-sg"
  }
}

# IAM Role for RDS
resource "aws_iam_role" "rds_role" {
  name = "rds-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "rds.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

# IAM Role Policy for Secrets Manager
resource "aws_iam_role_policy_attachment" "secretsmanager" {
  role       = aws_iam_role.rds_role.name
  policy_arn = "arn:aws:iam::aws:policy/SecretsManagerReadWrite"
}

# RDS Cluster
resource "aws_rds_cluster" "aurora" {
  cluster_identifier      = "aurora-cluster"
  engine                  = "aurora-mysql"
  engine_version          = "8.0.mysql_aurora.3.08.0"
  database_name           = "mydb"
  master_username         = "admin"
  master_password         = aws_secretsmanager_secret_version.aurora_secret.secret_string
  skip_final_snapshot     = true
  db_subnet_group_name    = aws_db_subnet_group.aurora.name
  vpc_security_group_ids  = [aws_security_group.rds.id]
  iam_roles               = [aws_iam_role.rds_role.arn]
  backup_retention_period = 5
  preferred_backup_window = "01:00-02:00"
}

# RDS Cluster Subnet Group
resource "aws_db_subnet_group" "aurora" {
  name       = "aurora-subnet-group"
  subnet_ids = aws_subnet.private.*.id
  tags = {
    Name = "aurora-subnet-group"
  }
}

# RDS Proxy
resource "aws_rds_proxy" "proxy" {
  name                   = "aurora-proxy"
  target_group_name      = "aurora-target-group"
  db_cluster_identifier  = aws_rds_cluster.aurora.id
  role_arn               = aws_iam_role.rds_role.arn
  debug_logging          = true
  require_ssl            = true
  security_groups        = [aws_security_group.rds.id]
  tags = {
    Name = "aurora-proxy"
  }
}

# Secrets Manager Secret for RDS Credentials
resource "aws_secretsmanager_secret" "aurora_secret" {
  name = "aurora-db-credentials"
  description = "Secret for Aurora MySQL cluster credentials"
  tags = {
    Name = "aurora-db-credentials"
  }
}

resource "aws_secretsmanager_secret_version" "aurora_secret" {
  secret_id     = aws_secretsmanager_secret.aurora_secret.id
  secret_string = jsonencode({
    username = "admin"
    password = "SecurePassword123!"
  })
}
```

