**Description of the Terraform Program:**

This Terraform configuration sets up an AWS RDS Aurora MySQL cluster with a proxy for enhanced connection management. It provisions a VPC with public and private subnets, a security group for the RDS cluster, an IAM role for the RDS instance, and a Secrets Manager secret to securely store database credentials. The RDS cluster is configured to take a final snapshot with the identifier "snapshot" upon deletion.

---

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "aurora-vpc"
  }
}

# Create public subnets
resource "aws_subnet" "public" {
  count = 2
  vpc_id = aws_vpc.main.id
  cidr_block = "10.0.${count.index + 1}.0/24"
  map_public_ip_on_launch = true
  availability_zone = "us-west-2${count.index + 1}"
  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

# Create private subnets
resource "aws_subnet" "private" {
  count = 2
  vpc_id = aws_vpc.main.id
  cidr_block = "10.0.${count.index + 3}.0/24"
  availability_zone = "us-west-2${count.index + 1}"
  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

# Create an internet gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "aurora-igw"
  }
}

# Create a route table for public subnets
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "public-route-table"
  }
}

# Associate public subnets with the public route table
resource "aws_route_table_association" "public" {
  count = 2
  subnet_id = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Create a route to the internet gateway
resource "aws_route" "internet_gateway" {
  route_table_id = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id = aws_internet_gateway.main.id
}

# Create a security group for the RDS cluster
resource "aws_security_group" "rds" {
  name        = "rds-sg"
  description = "Allow access to RDS cluster"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "rds-sg"
  }
}

# Create an IAM role for the RDS instance
resource "aws_iam_role" "rds_role" {
  name = "rds-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "rds.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

# Attach the AmazonRDSFullAccess policy to the IAM role
resource "aws_iam_role_policy_attachment" "rds_role_policy" {
  role       = aws_iam_role.rds_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonRDSFullAccess"
}

# Create a Secrets Manager secret for the RDS credentials
resource "aws_secretsmanager_secret" "rds_secret" {
  name = "rds-db-credentials"
  description = "Secret for RDS database credentials"
  tags = {
    Name = "rds-secret"
  }
}

# Create a Secrets Manager secret version with dummy credentials
resource "aws_secretsmanager_secret_version" "rds_secret_version" {
  secret_id = aws_secretsmanager_secret.rds_secret.id
  secret_string = jsonencode({
    username = "admin"
    password = "SecurePassword123!"
  })
}

# Create an RDS Aurora MySQL cluster
resource "aws_rds_cluster" "main" {
  cluster_identifier      = "aurora-cluster"
  engine                  = "aurora-mysql"
  engine_version          = "5.7.mysql_aurora.2.11.2"
  database_name           = "mydb"
  master_username         = "admin"
  master_password         = "SecurePassword123!"
  skip_final_snapshot     = false
  final_snapshot_identifier = "snapshot"
  backup_retention_period = 5
  preferred_backup_window = "07:00-09:00"
  db_subnet_group_name    = aws_db_subnet_group.main.name
  vpc_security_group_ids  = [aws_security_group.rds.id]
  iam_roles               = [aws_iam_role.rds_role.arn]
  storage_encrypted       = true
  apply_immediately       = true
  tags = {
    Name = "aurora-cluster"
  }
}

# Create a DB subnet group
resource "aws_db_subnet_group" "main" {
  name       = "aurora-subnet-group"
  subnet_ids = aws_subnet.private.*.id
  tags = {
    Name = "aurora-subnet-group"
  }
}

# Create an RDS Proxy
resource "aws_rds_proxy" "main" {
  name = "aurora-proxy"
  target_group_name = "aurora-target-group"
  db_cluster_identifier = aws_rds_cluster.main.id
  role_arn = aws_iam_role.rds_role.arn
  require_tls = true
  tags = {
    Name = "aurora-proxy"
  }
}

# Create a target group for the RDS Proxy
resource "aws_rds_proxy_target_group" "main" {
  name = "aurora-target-group"
  db_cluster_identifier = aws_rds_cluster.main.id
  tags = {
    Name = "aurora-target-group"
  }
}
```

