**Description of the Terraform Program:**

This Terraform configuration creates an AWS S3 bucket designed for long-term data storage and backup. The S3 bucket is configured with versioning enabled to prevent accidental overwrites and to support point-in-time recovery. Additionally, lifecycle rules are applied to transition data to S3 Glacier for cost-effective long-term storage. An IAM role is created to allow secure access to the bucket, and the bucket policy is set to restrict access to only the defined IAM role. The configuration is set up in the `us-west-2` region.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "long_term_backup" {
  bucket = "long-term-backup-bucket-${random_string.suffix.result}"
  acl    = "private"

  versioning {
    enabled = true
  }

  lifecycle_rule {
    id      = "transition-to-glacier"
    prefix  = ""
    status  = "Enabled"

    transition {
      storage_class = "GLACIER"
      days          = 365
    }
  }

  tags = {
    Name        = "LongTermBackupBucket"
    Environment = "Production"
  }
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}

resource "aws_iam_role" "s3_backup_role" {
  name = "s3-backup-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "s3.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "s3_full_access" {
  role       = aws_iam_role.s3_backup_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3FullAccess"
}

resource "aws_s3_bucket_policy" "long_term_backup_policy" {
  bucket = aws_s3_bucket.long_term_backup.bucket

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Deny"
      Principal = "*"
      Action = "s3:*"
      Resource = [
        aws_s3_bucket.long_term_backup.arn,
        "${aws_s3_bucket.long_term_backup.arn}/*"
      ]
      Condition = {
        StringNotLike = {
          "aws:arn" = "arn:aws:iam::*:role/${aws_iam_role.s3_backup_role.name}"
        }
      }
    }]
  })
}
```

---

This configuration ensures that your long-term data and backups are stored securely and cost-effectively in AWS S3, with appropriate access controls and lifecycle management.

