**Description of the Terraform Program:**

This Terraform configuration will create an AWS S3 Glacier vault and set up an AWS Data Lifecycle Manager (DLM) rule to manage the lifecycle of objects stored in the S3 bucket. The lifecycle rule will transition objects to S3 Glacier after a specified number of days. The configuration includes an S3 bucket, an IAM role for DLM, and a DLM lifecycle policy that references the S3 bucket and Glacier vault.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "glacier_bucket" {
  bucket = "my-glacier-bucket-${random_string.bucket_suffix.result}"
  acl    = "private"

  tags = {
    Name        = "glacier-bucket"
    Environment = "production"
  }

  lifecycle {
    ignore_changes = [arn]
  }
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}

resource "aws_iam_role" "dlm_role" {
  name = "dlm-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "dlm.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "dlm_role_policy" {
  role       = aws_iam_role.dlm_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSDataLifecycleManagerRole"
}

resource "aws_dlm_lifecycle_policy" "glacier_lifecycle" {
  description = "Move objects to S3 Glacier after 30 days"
  state       = "enabled"

  execution_role_arn = aws_iam_role.dlm_role.arn

  schedule {
    name = "glacier-transition"
    tags = {
      Environment = "production"
    }

    action {
      type = "archive"

      archive {
        storage_class = "GLACIER"
      }
    }

    schedule_expression = "cron(0 1 * * ? *)"
  }

  resource {
    type = "s3"

    s3 {
      bucket = aws_s3_bucket.glacier_bucket.bucket
      prefix = ""
    }
  }

  tags = {
    Name        = "glacier-lifecycle-policy"
    Environment = "production"
  }
}
```

---

**Notes:**

- The S3 bucket is created with a random suffix to ensure uniqueness.
- The IAM role `dlm-role` is created and attached with the necessary permissions for AWS Data Lifecycle Manager.
- The DLM lifecycle policy is configured to transition objects to S3 Glacier after a daily schedule (every day at 1:00 AM).
- The lifecycle policy is set to apply to the S3 bucket created in this configuration.

This configuration is ready to be applied with Terraform version `~> 1.9.8` and AWS provider version `~> 5.75`.

