**Description of the Terraform Program:**

This Terraform configuration creates an AWS S3 Glacier vault and sets up a notification service to trigger an AWS Lambda function when specific events occur in the vault. The notification service is configured to send event notifications to an SNS topic, which is then linked to a Lambda function for processing. The configuration includes the necessary IAM roles and policies to ensure secure and proper execution of the Lambda function.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_glacier_vault" "glacier_vault" {
  name = "my-glacier-vault"
}

resource "aws_sns_topic" "glacier_notifications" {
  name = "glacier-event-notifications"
}

resource "aws_lambda_function" "glacier_notification_handler" {
  function_name    = "glacier_notification_handler"
  handler          = "index.handler"
  runtime          = "nodejs18.x"
  role             = aws_iam_role.lambda_role.arn
  filename         = "lambda_function.zip"
  source_code_hash = filebase64sha256("lambda_function.zip")

  environment {
    variables = {
      S3_BUCKET = "my-glacier-bucket"
    }
  }
}

resource "aws_iam_role" "lambda_role" {
  name = "lambda_glacier_notification_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "lambda.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_iam_role_policy" "lambda_sns_access" {
  name = "lambda_sns_access"
  role = aws_iam_role.lambda_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "SNS:Publish"
      ]
      Resource = "*"
    }]
  })
}

resource "aws_sns_topic_subscription" "lambda_subscription" {
  topic_arn = aws_sns_topic.glacier_notifications.arn
  protocol  = "lambda"
  endpoint  = aws_lambda_function.glacier_notification_handler.arn
}

resource "aws_glacier_vault_notification" "glacier_notification" {
  vault_name = aws_glacier_vault.glacier_vault.name

  sns_topic = aws_sns_topic.glacier_notifications.arn

  events = [
    "ArchiveRetrievalCompleted",
    "InventoryRetrievalCompleted"
  ]
}
```

---

**Notes:**

- Replace `"lambda_function.zip"` with the actual path to your Lambda deployment package.
- The `S3_BUCKET` environment variable in the Lambda function is a placeholder; you can adjust it to match your use case.
- The `aws_glacier_vault_notification` resource is used to configure the Glacier vault to send notifications to the SNS topic.
- The Lambda function is set up to receive notifications from the SNS topic and can be extended to perform custom actions like logging, alerting, or data processing.

