**Description of the Terraform Program:**

This Terraform script will create a Network Load Balancer (NLB) in AWS, configure a listener on port 80, and attach a single EC2 instance (t2.micro) to the NLB. The script will also create a VPC, subnet, and security group to support the infrastructure. The EC2 instance will be launched in the same subnet as the NLB, and the NLB will forward traffic to the EC2 instance on port 80.

---

**Terraform HCL Code:**

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "nlb-ec2-vpc"
  }
}

# Create a subnet within the VPC
resource "aws_subnet" "main" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  tags = {
    Name = "nlb-ec2-subnet"
  }
}

# Create a security group for the EC2 instance
resource "aws_security_group" "ec2_sg" {
  name        = "ec2-sg"
  description = "Allow HTTP traffic to EC2 instance"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "ec2-sg"
  }
}

# Create a security group for the NLB
resource "aws_security_group" "nlb_sg" {
  name        = "nlb-sg"
  description = "Allow HTTP traffic to NLB"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "nlb-sg"
  }
}

# Create an EC2 instance
resource "aws_instance" "web_server" {
  ami           = "ami-0c55b159cbfafe1f0" # Amazon Linux 2 AMI (us-west-2)
  instance_type = "t2.micro"
  subnet_id     = aws_subnet.main.id
  security_groups = [aws_security_group.ec2_sg.name]

  tags = {
    Name = "web-server"
  }
}

# Create a Network Load Balancer
resource "aws_lb" "nlb" {
  name               = "nlb-web"
  internal           = false
  security_groups    = [aws_security_group.nlb_sg.id]
  subnets            = [aws_subnet.main.id]
  enable_deletion_protection = false
}

# Create a listener for the NLB
resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.nlb.arn
  port              = 80
  protocol          = "TCP"

  default_actions {
    type = "forward"
    target_group_arn = aws_lb_target_group.nlb_tg.arn
  }
}

# Create a target group for the NLB
resource "aws_lb_target_group" "nlb_tg" {
  name     = "nlb-tg"
  port     = 80
  protocol = "TCP"
  vpc_id   = aws_vpc.main.id

  health_check {
    path              = "/"
    protocol          = "HTTP"
    port              = 80
    interval          = 30
    timeout           = 5
    healthy_threshold = 5
    unhealthy_threshold = 2
  }
}

# Register the EC2 instance with the target group
resource "aws_lb_target_group_attachment" "nlb_attachment" {
  target_group_arn = aws_lb_target_group.nlb_tg.arn
  target_id        = aws_instance.web_server.id
  port             = 80
}
```

---

**Notes:**

- This script assumes the use of the `us-west-2` region and creates a single subnet in `us-west-2a`.
- The EC2 instance is launched with a public IP and is accessible via the NLB.
- The NLB is configured to forward traffic on port 80 to the EC2 instance.
- The script includes health checks for the target group.
- The AMI used is for Amazon Linux 2 in the `us-west-2` region. You may need to adjust it for other regions or OS versions.

Let me know if you'd like to add a custom AMI, enable logging, or add more instances to the NLB.

