**Description of the Terraform Program:**

This Terraform configuration creates an **Application Load Balancer (ALB)** in AWS. The ALB is configured with a listener on port 80 (HTTP) that forwards traffic to a target group. The target group is set up to register an EC2 instance as a target. The configuration includes the necessary security group, VPC, subnet, and IAM roles. All resources are defined with default values for variables, and the provider is configured with a valid region.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_id" {
  description = "The ID of the VPC to use"
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "List of subnet IDs to use for the ALB"
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "security_group_id" {
  description = "The ID of the security group to allow traffic"
  default     = "sg-12345678"
}

variable "target_instance_id" {
  description = "The ID of the EC2 instance to register with the target group"
  default     = "i-1234567890abcdef0"
}

resource "aws_alb" "example" {
  name            = "example-alb"
  internal        = false
  security_groups = [var.security_group_id]
  subnets         = var.subnet_ids
}

resource "aws_alb_listener" "http" {
  port     = 80
  protocol = "HTTP"
  load_balancer_arn = aws_alb.example.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_alb_target_group.example.arn
  }
}

resource "aws_alb_target_group" "example" {
  name     = "example-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = var.vpc_id

  health_check {
    path = "/health"
  }
}

resource "aws_alb_target_group_attachment" "example" {
  target_group_arn = aws_alb_target_group.example.arn
  target_id        = var.target_instance_id
  port             = 80
}
```

---

This configuration assumes that the EC2 instance is already running and that the security group allows traffic on port 80. You can modify the variables to match your environment.

