**Description of the Terraform Program:**

This Terraform configuration creates an **Application Load Balancer (ALB)** named `test-lb-tf` in the `us-east-1` region. It provisions the necessary **security groups** to allow HTTP traffic (port 80) and **associates the ALB with public subnets**. The ALB is configured to be **non-internal** (internet-facing), and **deletion protection is enabled** to prevent accidental deletion. The configuration includes a default VPC and subnets, and creates an IAM role for the ALB to allow logging to Amazon S3 (optional but recommended for compliance and monitoring).

---

**Terraform HCL Code:**

```hcl
provider "aws" {
  region = "us-east-1"
}

# Create a security group for the ALB
resource "aws_security_group" "alb_sg" {
  name        = "alb-sg"
  description = "Security group for Application Load Balancer"
  vpc_id      = aws_vpc.default.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "alb-sg"
  }
}

# Create a default VPC and subnets (if not already present)
resource "aws_vpc" "default" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "default-vpc"
  }
}

resource "aws_subnet" "public_subnet1" {
  vpc_id            = aws_vpc.default.id
  cidr_block        = "10.0.1.0/24"
  map_public_ip_on_launch = true
  availability_zone = "us-east-1a"
  tags = {
    Name = "public-subnet-1"
  }
}

resource "aws_subnet" "public_subnet2" {
  vpc_id            = aws_vpc.default.id
  cidr_block        = "10.0.2.0/24"
  map_public_ip_on_launch = true
  availability_zone = "us-east-1b"
  tags = {
    Name = "public-subnet-2"
  }
}

# Create an IAM role for the ALB (for logging)
resource "aws_iam_role" "alb_logging_role" {
  name = "alb-logging-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "elasticloadbalancing.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "alb_logging_attachment" {
  role       = aws_iam_role.alb_logging_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3FullAccess"
}

# Create the Application Load Balancer
resource "aws_lb" "test_lb" {
  name               = "test-lb-tf"
  internal           = false
  security_groups    = [aws_security_group.alb_sg.id]
  subnets            = [aws_subnet.public_subnet1.id, aws_subnet.public_subnet2.id]
  deletion_protection = true

  tags = {
    Name = "test-lb-tf"
  }

  # Optional: Attach the IAM role for logging
  access_logs {
    bucket = "your-logging-bucket-name" # Replace with your S3 bucket name
    prefix = "alb-logs/"
    enabled = true
    iam_role = aws_iam_role.alb_logging_role.arn
  }
}
```

---

**Notes:**

- Replace `"your-logging-bucket-name"` with the name of an existing S3 bucket if you want to enable logging.
- This configuration assumes that the subnets are public and have route tables with an Internet Gateway.
- If you already have a VPC and subnets, you can skip the `aws_vpc` and `aws_subnet` resources and reference existing ones.

