**Description of the Terraform Program:**

This Terraform script will create a Network Load Balancer (NLB) in AWS. The NLB will be configured with a listener on port 80, and it will be associated with a target group that points to an EC2 instance. The script will also create a security group to allow traffic to the NLB and the EC2 instance. All necessary resources, including the VPC, subnets, and IAM roles, will be defined within the configuration.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "nlb-vpc"
  }
}

# Create two public subnets
resource "aws_subnet" "public" {
  count = 2
  vpc_id = aws_vpc.main.id
  cidr_block = "10.0.${count.index + 1}.0/24"
  map_public_ip_on_launch = true
  availability_zone = "us-west-2a"
  tags = {
    Name = "nlb-public-subnet-${count.index + 1}"
  }
}

# Create an internet gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "nlb-igw"
  }
}

# Create a route table and associate with subnets
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "nlb-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count = 2
  subnet_id = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Create a route to the internet gateway
resource "aws_route" "internet" {
  route_table_id = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id = aws_internet_gateway.main.id
}

# Create a security group for the NLB and EC2 instance
resource "aws_security_group" "nlb_sg" {
  name        = "nlb-sg"
  description = "Allow HTTP traffic to NLB and EC2 instance"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "nlb-sg"
  }
}

# Create a target group for the NLB
resource "aws_lb_target_group" "web" {
  name     = "web-tg"
  port     = 80
  protocol = "TCP"
  vpc_id   = aws_vpc.main.id

  health_check {
    path              = "/"
    interval          = 30
    timeout           = 5
    healthy_threshold = 5
    unhealthy_threshold = 2
  }

  tags = {
    Name = "web-tg"
  }
}

# Create a Network Load Balancer
resource "aws_lb" "nlb" {
  name               = "nlb-web"
  internal           = false
  security_groups    = [aws_security_group.nlb_sg.id]
  subnets            = aws_subnet.public[*].id
  load_balancer_type = "network"

  tags = {
    Name = "nlb-web"
  }
}

# Create a listener for the NLB
resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.nlb.arn
  port              = 80
  protocol          = "TCP"

  default_actions {
    type = "forward"
    target_group_arn = aws_lb_target_group.web.arn
  }
}

# Create an EC2 instance to be used as a target
resource "aws_instance" "web" {
  ami           = "ami-0c55b159cbfafe1f0" # Amazon Linux 2 AMI (us-west-2)
  instance_type = "t2.micro"
  subnet_id     = aws_subnet.public[0].id
  security_groups = [aws_security_group.nlb_sg.name]
  tags = {
    Name = "web-server"
  }

  # User data to install a simple web server
  user_data = <<-EOF
              #!/bin/bash
              yum update -y
              yum install -y httpd
              systemctl start httpd
              systemctl enable httpd
              echo "Hello from NLB target" > /var/www/html/index.html
              EOF
}
```

---

This configuration will deploy a complete setup for a Network Load Balancer in AWS, including the necessary VPC, subnets, security groups, target group, and an EC2 instance to serve as a backend target. You can apply this configuration using `terraform apply`.

