LLM Output #0:
**Description of the Terraform Program:**

This Terraform configuration creates an AWS Application Load Balancer (ALB) with a redirect action configured on a listener. The redirect action will redirect HTTP traffic to HTTPS. The ALB is set up with a single listener on port 80 (HTTP) that redirects to port 443 (HTTPS). A basic security group is also created to allow HTTP and HTTPS traffic. The configuration includes a provider block for AWS, a default region, and uses default values for variables where applicable.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_lb" "example" {
  name               = "example-alb"
  internal           = false
  security_groups    = [aws_security_group.example.id]
  subnets            = ["us-east-1a", "us-east-1b", "us-east-1c"]
  enable_deletion_protection = false
}

resource "aws_security_group" "example" {
  name        = "example-alb-sg"
  description = "Allow HTTP and HTTPS traffic"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "example-alb-sg"
  }
}

resource "aws_lb_listener" "http-redirect" {
  load_balancer_arn = aws_lb.example.arn
  port              = 80
  protocol          = "HTTP"

  default_actions {
    type = "redirect"
    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }
}
```

