**Description of the Terraform Program:**

This Terraform configuration creates an AWS Application Load Balancer (ALB) with a listener that uses the "authenticate-cognito" action. This action redirects users to a specified Amazon Cognito User Pool for authentication. The configuration includes the necessary resources such as the VPC, subnets, security group, ALB, listener, and a Cognito User Pool. All required variables are provided with default values, and the provider is configured with a valid region.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_id" {
  description = "The ID of the VPC to use for the ALB"
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "List of subnet IDs for the ALB"
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "security_group_id" {
  description = "The ID of the security group to associate with the ALB"
  default     = "sg-12345678"
}

variable "cognito_user_pool_arn" {
  description = "The ARN of the Cognito User Pool"
  default     = "arn:aws:cognito-idp:us-east-1:123456789012:userpool/us-east-1_abcdef123456"
}

variable "cognito_client_id" {
  description = "The client ID of the Cognito User Pool"
  default     = "abcdef123456"
}

variable "cognito_domain" {
  description = "The domain of the Cognito User Pool"
  default     = "my-cognito-domain.auth.us-east-1.amazoncognito.com"
}

resource "aws_lb" "alb" {
  name               = "my-alb"
  internal           = false
  security_groups    = [var.security_group_id]
  subnets            = var.subnet_ids
  enable_deletion_protection = false
}

resource "aws_lb_listener" "alb_listener" {
  load_balancer_arn = aws_lb.alb.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "authenticate-cognito"

    authenticate_cognito {
      user_pool_arn       = var.cognito_user_pool_arn
      user_pool_client_id = var.cognito_client_id
      user_pool_domain    = var.cognito_domain
    }
  }
}
```

