**Description of the Terraform Program:**

This Terraform configuration creates an **AWS Application Load Balancer (ALB)** with a **rule that uses an Authenticate-OIDC action**. The ALB is configured with a listener on port 80, and the rule directs traffic to an OIDC provider (e.g., AWS Cognito) for authentication. The configuration includes a security group, a target group, and a listener rule with the `authenticate-oidc` action. The OIDC provider is assumed to be already configured, and the necessary parameters (such as the provider ARN, client ID, and client secret) are provided as variables with default values.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "oidc_provider_arn" {
  description = "ARN of the OIDC provider (e.g., AWS Cognito)"
  default     = "arn:aws:iam::123456789012:oidc-provider/cognito-idp.us-east-1.amazonaws.com/abcd1234-abcd-1234-abcd-1234abcd1234"
}

variable "oidc_client_id" {
  description = "Client ID of the OIDC provider"
  default     = "abcd1234-abcd-1234-abcd-1234abcd1234"
}

variable "oidc_client_secret" {
  description = "Client secret of the OIDC provider"
  default     = "your-client-secret"
}

variable "oidc_issuer" {
  description = "OIDC issuer URL"
  default     = "https://cognito-idp.us-east-1.amazonaws.com/abcd1234-abcd-1234-abcd-1234abcd1234"
}

variable "oidc_token_key" {
  description = "Name of the token key in the request header"
  default     = "Authorization"
}

variable "oidc_session_timeout" {
  description = "OIDC session timeout in seconds"
  default     = 300
}

resource "aws_security_group" "alb_sg" {
  name        = "alb-sg"
  description = "Security group for ALB"
  vpc_id      = "vpc-12345678"  # Replace with your VPC ID

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_alb" "example" {
  name            = "example-alb"
  internal        = false
  security_groups = [aws_security_group.alb_sg.id]
  subnets         = ["subnet-12345678", "subnet-87654321"]  # Replace with your subnets
}

resource "aws_alb_listener" "http" {
  load_balancer_arn = aws_alb.example.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "authenticate-oidc"
    authenticate_oidc {
      issuer               = var.oidc_issuer
      client_id            = var.oidc_client_id
      client_secret        = var.oidc_client_secret
      authorization_endpoint = "https://cognito-idp.us-east-1.amazonaws.com/abcd1234-abcd-1234-abcd-1234abcd1234"
      token_endpoint       = "https://cognito-idp.us-east-1.amazonaws.com/abcd1234-abcd-1234-abcd-1234abcd1234"
      user_info_endpoint   = "https://cognito-idp.us-east-1.amazonaws.com/abcd1234-abcd-1234-abcd-1234abcd1234"
      scope                = "email profile openid"
      session_timeout      = var.oidc_session_timeout
      on_unauthenticated_request = "deny"
    }
  }
}

resource "aws_alb_target_group" "example" {
  name     = "example-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = "vpc-12345678"  # Replace with your VPC ID

  health_check {
    path = "/health"
  }
}

resource "aws_alb_listener_rule" "oidc_rule" {
  listener_arn = aws_alb_listener.http.arn
  priority     = 1

  action {
    type = "forward"
    forward {
      target_group_arn = aws_alb_target_group.example.arn
    }
  }

  condition {
    field  = "path-pattern"
    values = ["/"]
  }
}
```

---

**Notes:**

- Replace placeholder values like `vpc-12345678`, `subnet-12345678`, and `subnet-87654321` with your actual VPC and subnet IDs.
- The OIDC provider ARN, client ID, and client secret should be replaced with your actual values.
- The `oidc_issuer`, `authorization_endpoint`, `token_endpoint`, and `user_info_endpoint` should match your OIDC provider's endpoints.
- This configuration assumes that the target group is pointing to an EC2 instance or another resource that is already set up and running.

