LLM Output #0:
**Description of the Terraform Program:**

This Terraform configuration creates an **AWS Application Load Balancer (ALB)** with a **target group** that points to an **AWS Lambda function**. The ALB listens on port 80 and forwards traffic to the Lambda function via the target group. The Lambda function is created with a basic handler that returns a simple HTTP response. An **IAM role** is created for the Lambda function to allow it to be invoked by the ALB. The configuration includes a provider block for AWS, a VPC, subnets, security groups, and all necessary resources to make the setup functional.

---

**Terraform HCL Code:**

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "lambda-alb-vpc"
  }
}

resource "aws_subnet" "public" {
  count = 2
  vpc_id = aws_vpc.main.id
  cidr_block = "10.0.${count.index + 1}.0/24"
  map_public_ip_on_launch = true
  tags = {
    Name = "lambda-alb-subnet-${count.index + 1}"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "lambda-alb-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "lambda-alb-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count = 2
  subnet_id = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route" "internet_gateway" {
  route_table_id = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id = aws_internet_gateway.main.id
}

resource "aws_security_group" "alb" {
  name        = "lambda-alb-sg"
  description = "Allow HTTP traffic to ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "lambda-alb-sg"
  }
}

resource "aws_security_group" "lambda" {
  name        = "lambda-sg"
  description = "Allow ALB to invoke Lambda"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "lambda-sg"
  }
}

resource "aws_iam_role" "lambda_role" {
  name = "lambda_invoke_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "lambda.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic" {
  role       = aws_iam_role.lambda_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_lambda_function" "example" {
  function_name    = "lambda-alb-target"
  role             = aws_iam_role.lambda_role.arn
  handler          = "index.handler"
  runtime          = "nodejs18.x"
  filename         = "lambda_function.zip"
  source_code_hash = filebase64sha256("lambda_function.zip")
  timeout          = 30
  memory_size      = 128

  tags = {
    Name = "lambda-alb-target"
  }
}

resource "aws_lambda_permission" "alb_invoke" {
  statement_id  = "AllowALBInvoke"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.example.function_name
  principal     = "elasticloadbalancing.amazonaws.com"
  source_arn    = aws_lb_listener.listener.arn
}

resource "aws_lb" "alb" {
  name               = "lambda-alb"
  internal           = false
  security_groups    = [aws_security_group.alb.id]
  subnets            = aws_subnet.public.*.id
  tags = {
    Name = "lambda-alb"
  }
}

resource "aws_lb_listener" "listener" {
  load_balancer_arn = aws_lb.alb.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "forward"
    target_group_arn = aws_lb_target_group.lambda_target.arn
  }
}

resource "aws_lb_target_group" "lambda_target" {
  name     = "lambda-target-group"
  port     = 443
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  target_type = "lambda"
  lambda_target {
    arn = aws_lambda_function.example.arn
  }

  health_check {
    interval            = 30
    path                = "/health"
    port                = 443
    protocol            = "HTTP"
    timeout             = 10
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }

  tags = {
    Name = "lambda-target-group"
  }
}
```

---

**Note:**  
- This configuration assumes that you have a `lambda_function.zip` file in the current working directory that contains the Lambda function code. The code should be a Node.js function that listens on port 443 and returns an HTTP response.
- The health check path `/health` must be implemented in your Lambda function to pass the health checks from the ALB.
- The `source_code_hash` is computed using the `filebase64sha256` function, which requires the actual ZIP file to be present. You can replace this with a placeholder or use `filebase64sha256("lambda_function.zip")` if you're using a local file.

