**Description of the Terraform Program:**

This Terraform configuration will create a memory-optimized PostgreSQL database instance on AWS using Amazon RDS. The instance will be configured with a memory-optimized DB instance class (e.g., `db.r6g.large`), which is suitable for workloads that require high memory capacity. The configuration includes a PostgreSQL database, a DB subnet group, a security group, and a VPC. The PostgreSQL instance will be deployed in a specific AWS region (e.g., `us-east-1`) and will use a default VPC if not specified. The configuration also includes IAM roles and policies to ensure secure access and management of the RDS instance.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-east-1"
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "main-vpc"
  }
}

# Create a subnet group for RDS
resource "aws_db_subnet_group" "main" {
  name       = "main-db-subnet-group"
  subnet_ids = [aws_subnet.private1.id, aws_subnet.private2.id]
  tags = {
    Name = "main-db-subnet-group"
  }
}

# Create private subnets
resource "aws_subnet" "private1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-1a"
  map_public_ip_on_launch = false
  tags = {
    Name = "private-subnet-1"
  }
}

resource "aws_subnet" "private2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-east-1b"
  map_public_ip_on_launch = false
  tags = {
    Name = "private-subnet-2"
  }
}

# Create a security group for RDS
resource "aws_security_group" "rds" {
  name        = "rds-sg"
  description = "Allow PostgreSQL access"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "rds-sg"
  }
}

# Create an IAM role for RDS
resource "aws_iam_role" "rds_role" {
  name = "rds-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "rds.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

# Attach the RDS managed policy to the IAM role
resource "aws_iam_role_policy_attachment" "rds_role_policy" {
  role       = aws_iam_role.rds_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonRDSFullAccess"
}

# Create a PostgreSQL RDS instance
resource "aws_db_instance" "postgres" {
  allocated_storage      = 20
  db_name                = "mydb"
  engine                 = "postgres"
  engine_version         = "15.3"
  instance_class         = "db.r6g.large"  # Memory-optimized instance
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  username               = "postgres"
  password               = "SecurePassword123!"
  skip_final_snapshot    = true
  iam_database_authentication_enabled = true
  db_parameter_group_name = "default.postgres15"
  tags = {
    Name = "memory-optimized-postgres"
  }
}
```

---

**Notes:**

- This configuration assumes that the AWS region `us-east-1` is available and that the user has the necessary permissions to create VPC, subnets, security groups, and RDS instances.
- The `db.r6g.large` instance class is memory-optimized and suitable for PostgreSQL workloads that require more memory.
- The IAM role `rds-role` is created to allow RDS to interact with other AWS services if needed.
- The password for the PostgreSQL instance is hardcoded for simplicity, but in a real-world scenario, you should use a secure method like `aws_secretsmanager` or `terraform-aws-modules` to manage credentials.

