**Description of the Terraform Program:**

This Terraform configuration will create an Amazon RDS (Relational Database Service) instance using MySQL as the database engine. It will also create a read replica of the primary database instance. The configuration includes a VPC, subnet group, security group, and IAM roles as needed. The primary database and its replica will be deployed in the same region, and the configuration ensures that all necessary resources are declared and fully specified for deployment.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "private" {
  count = 2
  vpc_id = aws_vpc.main.id
  cidr_block = "10.0.${count.index + 1}.0/24"
  map_public_ip_on_launch = false
  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

resource "aws_db_subnet_group" "main" {
  name       = "main-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id
  tags = {
    Name = "main-db-subnet-group"
  }
}

resource "aws_security_group" "db" {
  name        = "db-sg"
  description = "Allow database access"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "db-sg"
  }
}

resource "aws_iam_role" "rds_replication_role" {
  name = "rds-replication-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "rds.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "rds_replication_role" {
  role       = aws_iam_role.rds_replication_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSReplicationRole"
}

resource "aws_db_instance" "primary" {
  allocated_storage      = 20
  engine                 = "mysql"
  engine_version         = "8.0.33"
  instance_class         = "db.t3.micro"
  db_name                = "mydb"
  username               = "admin"
  password               = "SecurePassword123!"
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.db.id]
  skip_final_snapshot    = true
  tags = {
    Name = "primary-db"
  }
}

resource "aws_db_instance" "replica" {
  engine                 = "mysql"
  engine_version         = aws_db_instance.primary.engine_version
  instance_class         = "db.t3.micro"
  db_name                = aws_db_instance.primary.db_name
  username               = aws_db_instance.primary.username
  password               = aws_db_instance.primary.password
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.db.id]
  replica_source_db_instance_identifier = aws_db_instance.primary.identifier
  skip_final_snapshot    = true
  tags = {
    Name = "replica-db"
  }
}
```

---

**Notes:**

- The primary database and replica are both MySQL 8.0.33 instances.
- The replica is created using the `replica_source_db_instance_identifier` parameter, which references the primary instance.
- The password is hardcoded for simplicity, but in a real-world scenario, you should use a secure method like `terraform.tfvars` or a secret manager.
- The configuration assumes the use of the `us-west-2` region, but you can change it as needed.
- All resources are fully declared and self-contained, ensuring a valid and deployable Terraform configuration.

