**Description of the Terraform Program:**

This Terraform configuration creates an AWS RDS (Relational Database Service) instance with a managed master password stored in AWS Secrets Manager. The password is automatically rotated by Secrets Manager, and the RDS instance is configured to use the secret as its master password. Additionally, a default AWS KMS key is created and associated with the Secrets Manager secret to encrypt the stored password.

The configuration includes:
- An AWS KMS key for encryption.
- A Secrets Manager secret to store the RDS master password.
- An RDS instance that references the secret for its master password.
- IAM roles and policies to allow Secrets Manager to rotate the password and for RDS to access the secret.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a KMS key for encrypting the secret
resource "aws_kms_key" "default" {
  description             = "Default KMS key for Secrets Manager"
  deletion_window_in_days = 7
}

# Create a Secrets Manager secret for the RDS master password
resource "aws_secretsmanager_secret" "rds_master_password" {
  name        = "rds-master-password"
  description = "Secret for RDS master password"
  kms_key_id  = aws_kms_key.default.arn
}

resource "aws_secretsmanager_secret_version" "rds_master_password" {
  secret_id     = aws_secretsmanager_secret.rds_master_password.id
  secret_string = jsonencode({
    username = "admin"
    password = "InitialPassword123!"
  })
}

# IAM role for Secrets Manager to rotate the password
resource "aws_iam_role" "secretsmanager_rotation_role" {
  name = "secretsmanager-rds-rotation-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "secretsmanager.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "secretsmanager_rotation" {
  role       = aws_iam_role.secretsmanager_rotation_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSRDSDataSecretsManagerAccess"
}

# IAM role for RDS to access the secret
resource "aws_iam_role" "rds_secrets_access_role" {
  name = "rds-secrets-access-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "rds.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "rds_secrets_access" {
  role       = aws_iam_role.rds_secrets_access_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSRDSReadOnlyAccess"
}

# RDS instance with managed password via Secrets Manager
resource "aws_db_instance" "example" {
  allocated_storage      = 20
  db_name                = "mydb"
  engine                 = "mysql"
  engine_version         = "8.0.33"
  instance_class         = "db.t3.micro"
  master_username        = "admin"
  master_password        = aws_secretsmanager_secret.rds_master_password.secret_string
  db_subnet_group_name   = "default"
  vpc_security_group_ids = [aws_security_group.rds.id]
  skip_final_snapshot    = true
  apply_immediately      = true
  db_parameter_group_name = "default.mysql80"
  backup_retention_period = 7
  backup_window           = "01:00-02:00"
  monitoring_interval     = 0
  monitoring_role_arn     = aws_iam_role.secretsmanager_rotation_role.arn
  db_instance_identifier = "example-db"
  kms_key_id             = aws_kms_key.default.arn
  storage_encrypted      = true
  tags = {
    Name = "example-db"
  }
}

# Security group for RDS
resource "aws_security_group" "rds" {
  name        = "rds-sg"
  description = "Allow access to RDS instance"
  vpc_id      = "vpc-12345678"

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}
```

---

**Note:** This configuration assumes a VPC with ID `vpc-12345678` exists. You may need to adjust the `vpc_id` in the `aws_security_group` resource to match your actual VPC. Also, ensure that the RDS engine and version are supported in your AWS region.

