**Description of the Terraform Program:**

This Terraform configuration creates an AWS RDS (Relational Database Service) instance that uses AWS Secrets Manager to manage the master password. The password is encrypted using a specific AWS KMS (Key Management Service) key. The configuration includes:

- An AWS KMS key for encrypting the database password in Secrets Manager.
- A Secrets Manager secret that stores the database master password, encrypted with the specified KMS key.
- An RDS instance that references the secret for its master password.

The configuration ensures secure password management and uses best practices for IAM roles and resource tagging.

---

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_kms_key" "db_password_key" {
  description             = "KMS key for encrypting RDS master password"
  deletion_window_in_days = 7
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid = "Allow access to Secrets Manager"
        Effect = "Allow"
        Principal = {
          Service = "secretsmanager.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_secretsmanager_secret" "db_password" {
  name        = "rds-master-password"
  description = "Secret for RDS master password"
  kms_key_id  = aws_kms_key.db_password_key.arn
}

resource "aws_secretsmanager_secret_version" "db_password_version" {
  secret_id     = aws_secretsmanager_secret.db_password.id
  secret_string = jsonencode({
    username = "admin"
    password = "SecurePassword123!"
  })
}

resource "aws_db_instance" "example" {
  allocated_storage      = 20
  engine                 = "mysql"
  engine_version         = "8.0.30"
  instance_class         = "db.t3.micro"
  db_name                = "mydb"
  master_username        = "admin"
  master_password        = aws_secretsmanager_secret_version.db_password_version.secret_string
  vpc_security_group_ids = [aws_security_group.db_sg.id]
  db_subnet_group_name   = aws_db_subnet_group.example.name
  skip_final_snapshot    = true
  tags = {
    Name = "example-db"
  }
}

resource "aws_db_subnet_group" "example" {
  name       = "example-db-subnet-group"
  subnet_ids = [aws_subnet.private1.id, aws_subnet.private2.id]
  tags = {
    Name = "example-db-subnet-group"
  }
}

resource "aws_security_group" "db_sg" {
  name        = "db-sg"
  description = "Allow database access"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "db-sg"
  }
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "private1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  tags = {
    Name = "private1"
  }
}

resource "aws_subnet" "private2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
  tags = {
    Name = "private2"
  }
}
```

---

**Note:** This configuration assumes that you have already created a VPC and subnets, or that you want to create them as part of the setup. If you already have a VPC and subnets, you can remove the `aws_vpc` and `aws_subnet` resources and replace the `vpc_id` and `subnet_ids` in the `aws_db_subnet_group` and `aws_security_group` resources with your existing values.

