**Description of the Terraform Program:**

This Terraform configuration creates a dedicated-tenancy AWS VPC with DNS support and hostnames enabled. It provisions an Internet Gateway (IGW) and a Route Table that allows outbound internet access. All resources are tagged with a variable name to ensure consistent identification and management. The configuration uses the AWS provider and is set up to be deployed in the `us-east-1` region, with default values provided for any variables used.

---

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "resource_name" {
  description = "Name to be used as a tag for all resources"
  default     = "dedicated-vpc-resources"
}

resource "aws_vpc" "dedicated_vpc" {
  cidr_block           = "10.0.0.0/16"
  instance_tenancy     = "dedicated"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.resource_name
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.dedicated_vpc.id

  tags = {
    Name = var.resource_name
  }
}

resource "aws_route_table" "public_route_table" {
  vpc_id = aws_vpc.dedicated_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = var.resource_name
  }
}
```

